// Generated by scripts/generate-runtime-data.mjs. Edit source data, then regenerate.
const STYLE_DETAIL_DATA = Object.freeze({"ancient-egyptian":{"summary":"古埃及艺术横跨三千余年，在王权、神庙、葬仪、日常生活和文字系统中以材料、尺度、方位和图像规范建立秩序。复合视点、等级比例和横向分带常见，但雕像、浮雕、壁画、草纸、金工与不同时期不能共用一套‘侧脸正眼’公式。","recognition":"墓室横向分带、神庙轴线、石碑分区、草纸长卷或三维雕像按媒介与时期组织；复合视点、等级尺度、正面雕像、下凹浮雕或自然观察形体依作品区分；矿物蓝绿、赭红、黄、黑白、石材本色和金按材料与修复证据使用；壁画与草纸用平面色层，浮雕与雕像用真实展示光；不伪造火把戏剧光；石灰岩、花岗岩、木、草纸、泥砖灰泥、玻璃质釉料、金属与真实风化痕迹。","influencedBy":"尼罗河流域社会、早期王权形成、宗教与来世观、写作系统、石材和跨区域贸易","influenced":"地中海与近东王权图像、希腊罗马时期埃及艺术、建筑和后世埃及复兴与Art Deco","sources":[{"label":"The Met：Egypt in the Old Kingdom","url":"https://www.metmuseum.org/essays/egypt-in-the-old-kingdom-ca-2649-2130-b-c"},{"label":"British Museum：Ancient Egypt","url":"https://www.britishmuseum.org/collection/galleries/egyptian-sculpture"}]},"classical-greek":{"summary":"古希腊古典艺术约从前480延续至前323年，以自然观察、理想化比例、对立式平衡和建筑秩序探索公共与宗教形象。所谓“大理石白”是后世接受史造成的偏见之一；雕塑和建筑原本常有彩绘，古典艺术也并非只有静态、对称的一种面貌。","recognition":"均衡轴线、清楚重心与比例化空间；理想化形体、对立式平衡与受控动作；石灰白、陶土红、青铜综合色与有依据的综合色彩绘；柔和方向光揭示连续转折，避免把戏剧强光当作古典性的必要条件；大理石、青铜、陶器与残存综合色彩绘表面。","influencedBy":"希腊古风艺术、城邦公共文化、数学与自然观察","influenced":"希腊化与罗马艺术，并经文艺复兴和新古典主义反复重释","sources":[{"label":"The Met：The Art of Classical Greece","url":"https://www.metmuseum.org/toah/hd/tacg/hd_tacg.htm"},{"label":"The Met：The Art of the Hellenistic Age","url":"https://www.metmuseum.org/toah/hd/haht/hd_haht.htm"}]},"byzantine":{"summary":"拜占庭艺术约从君士坦丁堡建立后的4世纪延续至1453年，横跨早期、中期和晚期阶段，涵盖建筑、马赛克、圣像、手抄本、象牙与金工。金地、正面圣像和等级秩序高度重要，但“逆透视”、细长人物或非自然空间都不是所有时期和媒介的统一规则。","recognition":"圣像常用正面中心与等级对称，建筑和叙事作品则采用多样空间组织；庄严正面形体、轮廓化衣褶与因时期而异的自然体积；金、群青、紫红、绿与象牙白；金地和玻璃马赛克形成非自然亮度，也可用柔和塑形表现体积；玻璃马赛克、蛋彩木板、金箔、象牙、手抄本与金属工艺。","influencedBy":"晚期罗马与早期基督教艺术、希腊化传统、帝国宫廷和东地中海宗教文化","influenced":"东正教圣像、巴尔干与罗斯宗教艺术，并通过地中海交流影响意大利中世纪艺术","sources":[{"label":"The Met：Byzantium (ca. 330–1453)","url":"https://www.metmuseum.org/toah/hd/byza/hd_byza.htm"},{"label":"Encyclopaedia Britannica：Byzantine art","url":"https://www.britannica.com/art/Byzantine-art"}]},"gothic":{"summary":"哥特艺术约自12世纪中叶在法国发展并传播到欧洲各地，延续至不同地区的15或16世纪，涵盖建筑、雕塑、彩绘玻璃、木板画、金工和手抄本。尖拱、肋拱与高窗主要是建筑线索，不能用它们概括全部哥特绘画和雕塑。","recognition":"建筑常见垂直轴与分格立面，图像媒介常用层级叙事和装饰边框；尖拱、肋拱与细柱适用于建筑；雕塑和绘画常见修长形体与流动衣褶；宝石蓝、深红、金、石灰灰与羊皮纸白；彩窗以透射有色光激活建筑，木板画和手抄本多用均匀图像光与金饰高光；彩色玻璃、石雕、木板蛋彩、金箔、金工与羊皮纸。","influencedBy":"罗马式艺术、法兰西岛教堂建筑创新、城市与宫廷赞助及经院文化","influenced":"国际哥特、尼德兰早期绘画，以及19世纪哥特复兴建筑与设计","sources":[{"label":"Encyclopaedia Britannica：Gothic art","url":"https://www.britannica.com/art/Gothic-art"},{"label":"Wikipedia：Gothic art","url":"https://en.wikipedia.org/wiki/Gothic_art"}]},"renaissance":{"summary":"文艺复兴艺术约在14至16世纪的意大利形成重要中心，并通过跨区域交流呈现不同路线；古典复兴、人文主义、自然观察和透视研究推动绘画、雕塑与建筑变化。单点透视、三角构图和柔和明暗是重要方法，却不是所有地区、时期和媒介的必要条件。","recognition":"稳定轴线、比例化空间，以及线性透视、三角或其他清楚构图体系；自然观察与理想化并存，重视比例、体积和受控动作；土红、群青、综合色绿、暖肤色、金与石灰白；方向光和明暗塑形建立连续体积，不把单一柔光公式强加于全部作品；湿壁画、木板或画布油彩、蛋彩、大理石、青铜与建筑石材。","influencedBy":"古希腊罗马遗产、中世纪意大利艺术、人文主义、工坊知识和对自然的系统观察","influenced":"矫饰主义、巴洛克、欧洲学院传统及后世多次古典复兴","sources":[{"label":"The Met：Rome and Southern Italy, 1400–1600 A.D.","url":"https://www.metmuseum.org/toah/ht/08/eusts.html"},{"label":"Encyclopaedia Britannica：Renaissance art","url":"https://www.britannica.com/art/Renaissance-art"}]},"mannerism":{"summary":"矫饰主义是约1520至1600年主要用于意大利并扩展到欧洲宫廷艺术的现代艺术史标签。拉长比例、复杂姿态、不稳定空间和非自然色彩是若干代表性倾向，但不同中心也保留严整、冷静或高度装饰化的路线。","recognition":"偏心重心、压缩或不稳定纵深与复杂人物编排；拉长人体、蛇形姿态、精致手势与有意偏离自然的比例；冷粉、酸绿、银蓝、紫红与不连续综合色过渡；清晰而偏冷的塑形光，或不统一光源强化空间人工感；光滑油彩透明层、湿壁画、抛光大理石与精密装饰表面。","influencedBy":"盛期文艺复兴艺术、古典雕塑、罗马与佛罗伦萨工坊竞争及宫廷赞助","influenced":"晚期16世纪欧洲宫廷艺术，并为巴洛克的复杂动作和空间实验提供部分前提","sources":[{"label":"Encyclopaedia Britannica：Mannerism","url":"https://www.britannica.com/art/Mannerism"},{"label":"Wikipedia：Mannerism","url":"https://en.wikipedia.org/wiki/Mannerism"}]},"baroque":{"summary":"巴洛克艺术约在1600至1750年的欧洲及其全球联系中发展，涵盖绘画、雕塑、建筑和装饰艺术。运动、情感、观者参与和综合空间是重要倾向，但强烈明暗、深黑背景与旋转构图只适用于部分地区和艺术家，不能概括荷兰、法国、伊比利亚及殖民地的全部实践。","recognition":"可采用强对角线、瞬间叙事、深层空间或更克制的轴线和群组，取决于地域与题材；动作与体积强调观者参与，曲线、投射形体和自然观察可并存；深黑、酒红与金并非必需；应按地域使用暖土色、综合色肤色、清亮综合色或克制综合色；聚光与强明暗是部分路线，亦可使用自然窗光、均匀日光或明亮装饰光；厚薄油彩、透明罩染、大理石、灰泥、镀金木雕、织物与金属等多样表面。","influencedBy":"文艺复兴与矫饰主义、天主教改革、宫廷国家、城市市场和跨区域艺术交流","influenced":"洛可可、18世纪晚期戏剧化艺术、浪漫主义及后世舞台和影像视觉","sources":[{"label":"Encyclopaedia Britannica：Baroque art and architecture","url":"https://www.britannica.com/art/Baroque-art-and-architecture"},{"label":"Wikipedia：Baroque","url":"https://en.wikipedia.org/wiki/Baroque"}]},"rococo":{"summary":"洛可可约在1720至1770年代首先发展于法国室内装饰，继而传播到欧洲宫廷和城市文化，涵盖建筑内饰、装饰艺术、绘画与雕塑。非对称涡卷、亲密尺度和轻盈色调很有代表性，但粉彩享乐场景主要属于部分法国绘画，不能替代德语区宗教空间等不同路线。","recognition":"非对称偏心布局、亲密尺度与连续涡卷组织；S形、C形、贝壳和植物曲线，配合轻盈人物或装饰构件；粉蓝、浅粉、奶白、淡金与明亮综合色；柔和漫射光、低对比阴影与镀金或瓷器反光；灰泥、镀金木雕、瓷器、丝绸、细腻油彩与轻快笔触。","influencedBy":"晚期巴洛克室内设计、法国摄政时期文化、贵族沙龙与装饰工艺","influenced":"18世纪欧洲装饰艺术，并促成新古典主义对其装饰性和宫廷趣味的反拨","sources":[{"label":"Tate：Rococo","url":"https://www.tate.org.uk/art/art-terms/r/rococo"},{"label":"Wikipedia：Rococo","url":"https://en.wikipedia.org/wiki/Rococo"}]},"neoclassicism":{"summary":"新古典主义约在1760至1830年间通过考古发现、启蒙思想和学院网络重新解释希腊罗马艺术，遍及绘画、雕塑、建筑与设计。清晰轮廓、古典题材和道德严肃性是重要倾向，但帝政装饰、革命图像与不同国家的建筑并不共享单一冷白视觉。","recognition":"严格轴线、对称或清楚分组，以及浅层舞台式空间；理想化比例、清晰雕塑轮廓与克制或修辞化动作；石灰白、庞贝红、黑、综合色肤色与低饱和土色；均匀冷静光或清楚方向光，强调轮廓和连续体积；薄层油彩、抛光大理石、青铜、灰泥与精确建筑表面。","influencedBy":"古希腊罗马遗存与考古、启蒙思想、学院制度及对洛可可的批评","influenced":"帝政风格、19世纪公共纪念建筑、学院古典主义及后续古典复兴","sources":[{"label":"Tate：Neoclassicism","url":"https://www.tate.org.uk/art/art-terms/n/neoclassicism"},{"label":"Wikipedia：Neoclassicism","url":"https://en.wikipedia.org/wiki/Neoclassicism"}]},"romanticism":{"summary":"浪漫主义约在1790至1850年的欧洲形成于文学、音乐和视觉艺术的多重语境，重视情感、想象、历史、自然崇高与个体经验。它不是单纯反对理性，也没有统一的深蓝风暴画面；法国历史画、英国风景和德语区内省性绘画差异显著。","recognition":"可用动荡对角线、巨大尺度反差、孤立焦点或静默对称表达不同情绪；自然形体、人物动作和边缘处理服从情感与想象，不限定为一种变形方式；深蓝灰、土色与集中暖光常见，也可采用高综合色或冷静单色；从风暴强光、火光到雾化日光等多种大气光线；透明油彩、可见笔触、薄雾边缘、纸本水彩与丰富表面变化。","influencedBy":"启蒙时代内部的感性讨论、崇高美学、革命与民族历史、自然哲学和文学","influenced":"象征主义、部分现实主义与现代风景传统，并长期影响历史和幻想视觉","sources":[{"label":"Tate：Romanticism","url":"https://www.tate.org.uk/art/art-terms/r/romanticism"},{"label":"Wikipedia：Romanticism","url":"https://en.wikipedia.org/wiki/Romanticism"}]},"realism":{"summary":"19世纪现实主义约在1840至1880年间以法国为重要中心，拒绝学院艺术对历史、神话和理想美的等级偏好，使当代劳动、乡村、城市和社会关系成为严肃主题。它是一种历史运动和更广义再现方法的交叉术语，不等同于照片般精细或固定的土褐配色。","recognition":"平视观察、稳定或直接裁切的构图，使当代人物和环境占据主体位置；未经古典理想化的比例、可信重量与具体姿态；土褐、灰绿和低饱和综合色常见，但色彩应服从具体场景而非固定棕色公式；自然日光、室内光或环境光，保持局部阴影和空间可信度；油彩、纸本与版画中的可见制作痕迹，表面可粗粝也可精细。","influencedBy":"1830与1848年前后的社会政治变化、当代生活观察、新闻文化及对浪漫主义和学院等级的回应","influenced":"自然主义、印象主义的现代生活题材、社会现实主义与纪实传统","sources":[{"label":"Tate：Realism","url":"https://www.tate.org.uk/art/art-terms/r/realism"},{"label":"Wikipedia：Realism (arts)","url":"https://en.wikipedia.org/wiki/Realism_(arts)"}]},"pre-raphaelite":{"summary":"前拉斐尔派始于1848年伦敦成立的前拉斐尔兄弟会，随后扩展为更宽的艺术与设计圈。早期成员反对皇家美术学院的程式，重视拉斐尔之前的艺术、自然细节、文学和宗教题材；明亮湿白底技法是重要实践，但不适用于所有后期成员和设计作品。","recognition":"近景密集、叙事性群组与前后景近乎一致的细节清晰度；锐利轮廓、植物学或织物细节与较少学院式概括；翡翠绿、朱红、群青、明亮白与宝石般综合色；均匀明亮的冷调日光、有限雾化与清楚局部反射；湿白底薄涂油彩、细密画布、金饰、织物和设计工艺表面。","influencedBy":"中世纪与意大利早期文艺复兴艺术、浪漫文学、自然研究及对英国学院教学的批评","influenced":"工艺美术运动、唯美主义、象征主义及后来的插画和中世纪复兴设计","sources":[{"label":"Tate：Pre-Raphaelite","url":"https://www.tate.org.uk/art/art-terms/p/pre-raphaelite"},{"label":"Wikipedia：Pre-Raphaelite Brotherhood","url":"https://en.wikipedia.org/wiki/Pre-Raphaelite_Brotherhood"}]},"impressionism":{"summary":"印象主义形成于1860年代末至1880年代的法国，并以1874年起的独立展览获得名称。松散笔触、现代生活、户外光色和瞬时观看是重要方向，但成员在人物画、室内场景、风景及技法上差异明显，也并非全部在户外一次完成。","recognition":"开放式裁切、偏心焦点与现代生活或风景的瞬时取景；可见短笔触、松动轮廓与因艺术家而异的形体简化；高明度综合色、并置互补色与彩色阴影，避免统一泥综合色；自然日光、城市环境光或室内光的时刻性变化；可见油画笔触、画布纹理与薄厚交替的综合色层。","influencedBy":"现实主义与巴比松风景、现代巴黎、摄影裁切、日本版画及新颜料和光色研究","influenced":"后印象主义、新印象主义及欧洲和美国多地的现代绘画实践","sources":[{"label":"Tate：Impressionism","url":"https://www.tate.org.uk/art/art-terms/i/impressionism"},{"label":"Wikipedia：Impressionism","url":"https://en.wikipedia.org/wiki/Impressionism"}]},"post-impressionism":{"summary":"“后印象主义”由罗杰·弗莱在1910年展览语境中推广，用来回顾约1886至1905年若干从印象主义出发的不同实践。塞尚、梵高、高更、修拉等人的结构、表现、象征和综合色方法互不相同，因此不能提炼成一种高纯度配色或厚涂笔触。","recognition":"空间可压缩、几何化、装饰化或由综合色点组织，须按具体艺术家路线选择；简化体积、强化轮廓、方向笔触或规则综合色单元并存；从科学性点彩到主观纯色和土色综合色，不设统一配色；光线可继续研究自然综合色，也可服从结构、情绪或象征目的；平涂、点彩、方向笔触、厚涂与画布纹理等多种油画表面。","influencedBy":"印象主义，以及日本版画、综合色科学、象征主义和不同艺术家的个人研究","influenced":"野兽派、表现主义、立体主义和20世纪多种结构性或表现性绘画","sources":[{"label":"Tate：Post-impressionism","url":"https://www.tate.org.uk/art/art-terms/p/post-impressionism"},{"label":"Wikipedia：Post-Impressionism","url":"https://en.wikipedia.org/wiki/Post-Impressionism"}]},"symbolism":{"summary":"象征主义约在1880至1910年的欧洲文学与视觉艺术中发展，以暗示、梦境、神话、精神性和主观观念反对直接自然主义。它横跨多个国家和媒介，没有统一的暗金、夜蓝或雾化画法；艺术家可采用精密线描、平涂装饰或近乎学术的造型。","recognition":"仪式化中心、封闭场景、悬浮空间或装饰性分区，服从观念而非统一布局；程式轮廓、隐喻形体与自然主义造型可按艺术家并存；暗金、夜蓝和灰紫只是部分路线，也可使用明亮平涂或自然综合色；内向漫射、舞台光、金地亮度或自然光均可承担象征功能；油彩、蛋彩、纸本、版画、金箔与装饰性表面。","influencedBy":"浪漫主义、文学象征主义、神话和宗教复兴、神秘学及对自然主义的反应","influenced":"新艺术运动、表现主义、超现实主义及20世纪幻想和心理图像","sources":[{"label":"Tate：Symbolism","url":"https://www.tate.org.uk/art/art-terms/s/symbolism"},{"label":"Wikipedia：Symbolism (arts)","url":"https://en.wikipedia.org/wiki/Symbolism_(arts)"}]},"arts-crafts":{"summary":"工艺美术运动约在1860至1910年的英国形成并产生国际影响，批评工业生产造成的劳动异化和设计低劣，主张材料、用途、制作与整体环境相协调。威廉·莫里斯式满版植物纹只是其中一支，运动还涵盖建筑、家具、书籍、金属与陶瓷。","recognition":"构图服从用途，可用满版重复、清楚边框、结构网格或简洁家具比例；植物互锁曲线、诚实构造和与制作工艺一致的形体；靛蓝、茜红、橄榄绿、木色与材料本色，避免固定综合色模板；均匀环境光或自然光，突出材料和手工细节而非戏剧效果；木版印刷、织物纤维、木材、金属、陶瓷与轻微手工不规则。","influencedBy":"中世纪工坊理想、哥特复兴、前拉斐尔派、约翰·拉斯金与威廉·莫里斯的社会和设计思想","influenced":"新艺术运动、私人出版社运动、现代设计教育及欧美手工艺复兴","sources":[{"label":"Tate：Arts and Crafts","url":"https://www.tate.org.uk/art/art-terms/a/arts-and-crafts"},{"label":"Wikipedia：Arts and Crafts movement","url":"https://en.wikipedia.org/wiki/Arts_and_Crafts_movement"}]},"art-nouveau":{"summary":"新艺术运动约在1890至1910年以不同名称遍及欧洲和美国，试图把建筑、室内、工艺、海报和字体整合为现代整体设计。鞭状植物曲线是重要路线，但维也纳分离派等也采用几何秩序，不能用单一花卉曲线和橄榄金综合色覆盖全部地域。","recognition":"非对称垂直延展、整体装饰框架，或因地域而采用更几何的分区；鞭状曲线、植物形体、扁平剪影，也可结合几何结构和新材料构件；橄榄绿、赭石、柔金和综合色粉彩常见，但配色随地域和媒介变化；海报多用平面光，建筑和工艺品使用环境光呈现金属、玻璃与釉面；平版印刷、彩色玻璃、铸铁、木材、陶瓷、马赛克与手工表面。","influencedBy":"工艺美术运动、日本版画、象征主义、自然形态研究及新材料和都市商业文化","influenced":"装饰艺术、现代平面设计、建筑与产品设计中的整体化和有机路线","sources":[{"label":"Tate：Art Nouveau","url":"https://www.tate.org.uk/art/art-terms/a/art-nouveau"},{"label":"Wikipedia：Art Nouveau","url":"https://en.wikipedia.org/wiki/Art_Nouveau"}]},"fauvism":{"summary":"野兽派是1905年前后法国画家组成的松散群体，名称源自当时批评，并非有统一宣言的长期组织。高纯度非自然综合色、简化形体和直接笔触高度重要，但马蒂斯、德兰、弗拉芒克等人的空间和笔法并不一致，主要活跃期也短于原条目的1910年。","recognition":"压缩或扁平空间、清楚综合色区域与直接取景；简化形体、粗轮廓和宽阔而可见的笔触；非自然高纯度综合色、互补色冲突与综合色直接塑形；光线服从综合色结构，可保留明亮户外感而不依赖传统明暗；直接少调和的油彩、裸露画布与厚薄不均笔触。","influencedBy":"后印象主义诸路线，尤其梵高、高更、修拉和塞尚，以及19世纪末综合色实验","influenced":"德国表现主义及20世纪以综合色自主性为核心的绘画","sources":[{"label":"Tate：Fauvism","url":"https://www.tate.org.uk/art/art-terms/f/fauvism"},{"label":"Wikipedia：Fauvism","url":"https://en.wikipedia.org/wiki/Fauvism"}]},"expressionism":{"summary":"表现主义是对20世纪初以主观感受改造综合色、形体和空间的广义称呼，尤与德国和奥地利的桥社、蓝骑士及独立艺术家相关。尖角变形、酸性综合色和焦虑主题只代表部分实践；它不是统一组织，也不能等同于一种恐怖视觉。","recognition":"可用倾斜压缩、平面正面、放射结构或相对稳定布局表达主观经验；形体从尖角变形、粗轮廓到流动抽象不等，服从情绪而非统一公式；酸黄、深红与深蓝强撞是部分路线，也可使用土色、黑白或精神性纯色；不均匀明暗、平面综合色光或强烈轮廓对比替代客观光照一致性；干涩厚涂、流动笔触、木刻刀痕、纸本与粗糙印刷表面。","influencedBy":"后印象主义、象征主义、野兽派、现代都市经验，以及当时欧洲对非西方艺术的选择性接受","influenced":"新客观主义的反应、抽象艺术、电影表现主义及后来的新表现主义","sources":[{"label":"Tate：Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"},{"label":"Wikipedia：Expressionism","url":"https://en.wikipedia.org/wiki/Expressionism"}]},"cubism":{"summary":"立体主义约在1907至1914年的巴黎由毕加索、布拉克等人发展，分析和重组对象、画面平面及观看方式。分析立体主义的有限综合色和细碎切面不能代表随后采用拼贴、文字和较大综合色面的综合立体主义；“同时多个视点”是有用概括，但不是机械叠加所有角度。","recognition":"互锁形体压缩传统纵深，并在画面平面上重新组织对象和背景；角状切面、简化几何、局部线索和选择性多视点观察；分析阶段多用赭灰综合色，综合阶段可加入较强综合色与印刷材料；弱化单一光源，以切面明度和材质对比建立结构；颗粒油彩、木炭线、纸张拼贴、印刷字和仿木纹等异质表面。","influencedBy":"塞尚对形体和空间的研究、伊比利亚雕塑，以及现代主义者对非洲艺术的挪用和巴黎先锋网络","influenced":"未来主义、俄国先锋、构成主义、纯粹主义、装饰艺术和现代拼贴","sources":[{"label":"Tate：Cubism","url":"https://www.tate.org.uk/art/art-terms/c/cubism"},{"label":"Wikipedia：Cubism","url":"https://en.wikipedia.org/wiki/Cubism"}]},"futurism":{"summary":"未来主义由马里内蒂1909年宣言开启，意大利第一阶段约延续至第一次世界大战，涉及文学、绘画、雕塑、摄影、表演、建筑和排版。速度、机械、都市与连续运动是核心主题，但政治立场、战争崇拜及其后来与法西斯主义的复杂关系不能从专业介绍中省略。","recognition":"放射对角线、力线和连续运动分解，或以排版突破常规页面轴线；重复轮廓、机械几何、运动残影与形体穿透；钢灰、电蓝、橙红和综合色分割，也可使用黑白印刷对比；闪烁分色、速度造成的综合色断裂与金属高光；油彩、青铜、摄影叠影、印刷纸张和实验排版表面。","influencedBy":"立体主义、分色主义、工业都市、摄影运动研究及先锋宣言文化","influenced":"俄国未来主义、先锋排版、部分构成主义与20世纪动态视觉设计","sources":[{"label":"Tate：Futurism","url":"https://www.tate.org.uk/art/art-terms/f/futurism"},{"label":"Wikipedia：Futurism","url":"https://en.wikipedia.org/wiki/Futurism"}]},"dada":{"summary":"达达约在1916至1924年间由苏黎世、柏林、纽约、巴黎等多个中心发展，以表演、偶然、拼贴、现成品、诗歌和出版物质疑战争、资产阶级文化及艺术制度。它没有统一风格，柏林摄影蒙太奇和红黑排版不能代表杜尚现成品、苏黎世表演或汉诺威梅尔茨。","recognition":"结构随作品而变，可故意失序、偶然排列、反网格或保持现成物原状；突兀比例、剪切重组、机械复制、现成物和非艺术材料并置；色彩取决于来源材料；黑白报刊与红色只是部分柏林作品的常见选择；拼贴和印刷多用平面光，物件与表演保留真实环境光；撕纸、旧报纸、照片、现成物、胶痕、印刷误差及表演记录。","influencedBy":"第一次世界大战、未来主义与立体主义拼贴、先锋诗歌、表演和跨国流亡网络","influenced":"超现实主义、观念艺术、激浪派、行为艺术、朋克与挪用艺术","sources":[{"label":"Tate：Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"},{"label":"Wikipedia：Dada","url":"https://en.wikipedia.org/wiki/Dada"}]},"constructivism":{"summary":"构成主义约自1915年后的俄国先锋中形成，主张以真实材料、空间、技术和生产取代自主艺术品，并扩展到建筑、舞台、摄影、纺织、展览和印刷。红黑对角海报是后来的高识别应用之一，不能代表塔特林、罗德琴科、波波娃等人的全部三维和生产实践。","recognition":"结构可用真实空间中的悬挂、交叉和材料关系，也可用强对角与不对称版面；几何构件、工业连接、摄影蒙太奇和可生产的模块；材料本色、红黑纸白和有限纯色，按物件或传播用途选择；环境光与真实投影揭示空间构件，平面作品保持清楚明度对比；木、金属、玻璃、胶合板、照片、印刷油墨、织物与制作接点。","influencedBy":"立体主义、未来主义、至上主义、工业材料，以及革命时期对艺术社会功能的争论","influenced":"包豪斯、国际现代主义、现代展览、摄影蒙太奇和功能主义平面设计","sources":[{"label":"Tate：Constructivism","url":"https://www.tate.org.uk/art/art-terms/c/constructivism"},{"label":"Wikipedia：Constructivism (art)","url":"https://en.wikipedia.org/wiki/Constructivism_(art)"}]},"suprematism":{"summary":"至上主义由马列维奇在1915年前后提出，以基本几何和有限综合色追求脱离对象再现的“纯粹感受”。黑方块并非整个运动的唯一模式，漂浮矩形、圆、十字、综合色构成及后期白上白共同形成内部发展，也应与强调材料和社会生产的构成主义区分。","recognition":"白色场域中漂浮、旋转或轴向排列的非客观几何关系；方形、矩形、圆、十字和简化线形，边缘可保留手工变化；黑、白、红和有限纯色，并包括白上白的窄明度体系；无自然光源，以形色关系和综合色差建立视觉重量；哑光油彩、可见手工边缘、画布纹理与少量颜料不均。","influencedBy":"立体主义与未来主义的形体分解、俄国先锋实验和马列维奇的非客观艺术理论","influenced":"俄国先锋、构成主义的形成语境，以及后来的几何抽象与极简主义接受史","sources":[{"label":"Tate：Suprematism","url":"https://www.tate.org.uk/art/art-terms/s/suprematism"},{"label":"Wikipedia：Suprematism","url":"https://en.wikipedia.org/wiki/Suprematism"}]},"de-stijl":{"summary":"风格派由1917年创办的《风格》杂志及其松散成员网络形成，探索将视觉语言简化为垂直水平、矩形、原色和中性色，并扩展至绘画、建筑、家具与字体。蒙德里安的新造型主义最具代表性，但范杜斯堡的对角元素主义等变化说明它并非始终只有正交网格。","recognition":"不对称平衡、垂直水平网格和开放边界，后期部分作品可加入对角线；矩形色面、不同粗细直线与简化建筑或家具构件；红、黄、蓝三原色配黑、白、灰，实际作品可有材料本色和有限变化；平面无阴影构成，建筑与家具则使用真实环境光和投影；平滑油彩、木材、玻璃、灰泥和清楚制作接缝。","influencedBy":"立体主义、荷兰现代建筑、神智学与第一次世界大战期间对普遍秩序的追求","influenced":"包豪斯、国际现代主义、现代建筑、家具和平面设计中的几何秩序","sources":[{"label":"Tate：De Stijl","url":"https://www.tate.org.uk/art/art-terms/d/de-stijl"},{"label":"Wikipedia：De Stijl","url":"https://en.wikipedia.org/wiki/De_Stijl"}]},"bauhaus":{"summary":"包豪斯是1919至1933年先后设于魏玛、德绍和柏林的德国学校，而非一套固定的红黄蓝几何风格。其不同阶段和教师在建筑、工坊、舞台、摄影、字体与基础课程上立场多样，共同问题是如何重组艺术、工艺、技术、教育与现代生产。","recognition":"构图随课程与媒介变化，可采用功能网格、非对称页面或清楚空间模块；基础几何、材料构造、模块和功能部件，不把圆方三角当作唯一造型；原色与黑白是部分课程和作品的系统，亦使用材料本色与摄影灰阶；平面作品使用均匀综合色关系，建筑和物件保留真实环境光与投影；纸张、印刷油墨、钢管、玻璃、木材、织物、摄影与可见构造。","influencedBy":"德国工艺联盟、工艺美术教育、表现主义，以及风格派和构成主义等欧洲先锋交流","influenced":"现代设计教育、国际现代主义建筑、字体、摄影、家具与工业设计","sources":[{"label":"Tate：Bauhaus","url":"https://www.tate.org.uk/art/art-terms/b/bauhaus"},{"label":"Wikipedia：Bauhaus","url":"https://en.wikipedia.org/wiki/Bauhaus"}]},"surrealism":{"summary":"超现实主义以布勒东1924年宣言为重要起点，是跨文学、绘画、摄影、电影、物件和展览的国际运动，探索潜意识、欲望、偶然与自动性。达利式精细梦境只是其中一路，自动绘画、拼贴、摄影实验和超现实物件同样关键。","recognition":"可用不可能空间、偶然拼合、自动性场域或物件陈列，不限定写实舞台；精确硬边、流动生物形、摩擦转印、拼贴和现成物可按具体路线选择；自然综合色、局部异色、自动绘画综合色或黑白摄影均可；光线可冷静清晰、来源暧昧，也可由暗房、投影或真实展示环境产生；平滑油彩、自动笔触、拼贴纸、摄影、现成物和实验印痕。","influencedBy":"达达、精神分析、形而上绘画、象征主义、自动写作与第一次世界大战后的先锋文化","influenced":"抽象表现主义的自动技法、观念与行为实践、实验摄影电影及后来的幻想和广告图像","sources":[{"label":"Tate：Surrealism","url":"https://www.tate.org.uk/art/art-terms/s/surrealism"},{"label":"Wikipedia：Surrealism","url":"https://en.wikipedia.org/wiki/Surrealism"}]},"art-deco":{"summary":"装饰艺术在1920至1940年代成为跨国建筑、室内、时尚、珠宝、交通工具和平面设计语言，名称后来因1925年巴黎现代装饰与工业艺术博览会而固定。阶梯几何、奢华材料与机器意象常见，但其路线可从手工豪华到流线量产，不能等同于黑金对称。","recognition":"轴线对称、阶梯轮廓、放射扇形或流线型水平组织随地区和阶段变化；几何化植物、锯齿、日芒、流线体与精确装饰构件；黑金和宝石色是豪华路线，亦可用铬银、粉彩、土色和材料本色；锐利高光、分区照明或均匀商业展示光突出表面与轮廓；抛光金属、漆、玻璃、木皮、石材、珐琅、印刷油墨与纺织物。","influencedBy":"立体主义和几何先锋、古代及非欧洲艺术的现代挪用、奢侈工艺、考古热与机器时代设计","influenced":"流线型现代主义、影院和商业建筑、消费品造型及后来的装饰艺术复兴","sources":[{"label":"Tate：Art Deco","url":"https://www.tate.org.uk/art/art-terms/a/art-deco"},{"label":"Wikipedia：Art Deco","url":"https://en.wikipedia.org/wiki/Art_Deco"}]},"abstract-expressionism":{"summary":"抽象表现主义约在1940年代至1960年代初以纽约为重要中心，包含行动绘画、色域倾向及形态各异的抽象实践。大尺幅和对制作过程的强调具有共性，但滴洒、无中心满幅和猛烈身体手势主要描述部分艺术家，不能概括罗斯科、纽曼等不同路线。","recognition":"大尺幅画面可采用无中心满幅、集中综合色区、垂直区隔或开放边界；滴流、挥洒、擦抹、宽阔综合色面和简化符号随艺术家路线变化；综合色范围从高反差多色到有限深色或综合色场，不设统一综合色公式；画面光由颜料明度、叠层和裸画布关系产生，不模拟固定摄影光源；滴洒、厚涂、薄染、擦除、裸露画布与可见制作过程。","influencedBy":"欧洲现代抽象、超现实主义自动技法、美国现代艺术、移民艺术网络与第二次世界大战前后经验","influenced":"色域绘画、后绘画性抽象、极简和后极简的反应，以及后来的新表现主义","sources":[{"label":"Tate：Abstract expressionism","url":"https://www.tate.org.uk/art/art-terms/a/abstract-expressionism"},{"label":"Wikipedia：Abstract expressionism","url":"https://en.wikipedia.org/wiki/Abstract_expressionism"}]},"color-field":{"summary":"色域绘画约自1940年代末发展，以大尺幅综合色区、综合色关系和观看尺度弱化具象与显著手势。罗斯科的悬浮矩形、纽曼的纵向色带和后续浸染绘画差异很大；柔边、硬边、薄染与较厚涂层都可能出现。","recognition":"大尺幅、低事件密度的连续综合色区、悬浮色块、条带或开放场；描绘形体退居其次，边界可渗化、漂浮、笔直或保持画布形状；有限综合色之间的明度、饱和度、温度和面积关系构成主体；综合色自身产生发光、吸收或平面张力，不依赖自然光源模拟；薄染裸画布、叠层油彩、均匀哑光或精确硬边表面。","influencedBy":"抽象表现主义、欧洲现代抽象，以及对崇高、综合色和大尺度观看的探索","influenced":"后绘画性抽象、华盛顿色彩画派、硬边绘画、极简主义和后续综合色装置","sources":[{"label":"Tate：Colour field painting","url":"https://www.tate.org.uk/art/art-terms/c/colour-field-painting"},{"label":"Wikipedia：Color field","url":"https://en.wikipedia.org/wiki/Color_field"}]},"pop-art":{"summary":"波普艺术于1950年代中期先在英国、继而在1960年代美国等地发展，以广告、漫画、商品、明星和大众传播研究消费文化与图像复制。粗黑轮廓、原色和网点主要对应部分漫画式作品；摄影丝网、雕塑、拼贴和冷静复制同样关键。","recognition":"广告式裁切、重复模块、商品陈列、漫画格或媒体拼贴随具体路线选择；机械复制轮廓、放大日常物、摄影转印和工业化雕塑形体；商业印刷原色、高纯度综合色、摄影综合色或消费品固有综合色；平面复制光、影棚商品光或展厅环境光，避免统一戏剧照明；丝网印刷、半调网点、丙烯、拼贴、搪瓷、塑料和工业制作表面。","influencedBy":"大众传媒、广告和消费文化、达达现成品与拼贴，以及英国独立小组等战后讨论","influenced":"后现代主义、观念与挪用艺术、新波普和多种商业—艺术跨界实践","sources":[{"label":"Tate：Pop art","url":"https://www.tate.org.uk/art/art-terms/p/pop-art"},{"label":"Wikipedia：Pop art","url":"https://en.wikipedia.org/wiki/Pop_art"}]},"op-art":{"summary":"欧普艺术约在1950年代中期至1970年代通过精确综合色和几何关系激活观看过程，1965年MoMA的《The Responsive Eye》展览推动其名称普及。黑白振动和莫尔纹只是部分方法，综合色相互作用、渐变、曲面与观看移动也同样重要。","recognition":"满幅重复、渐变网格、图底反转和随观看位置激活的视觉场；线距、密度、曲率、尺度与几何模块的连续变化；黑白极端对比、互补综合色振动或精确综合色渐变；完全平面图像光，运动与纵深由视觉系统而非真实投影产生；锐利硬边、平滑颜料、精确印刷、塑料或反射材料。","influencedBy":"构成主义、包豪斯和几何抽象的综合色研究、视觉心理与知觉科学","influenced":"动力与参与式艺术、综合色和图案设计、时尚及后来的数字视觉实验","sources":[{"label":"Tate：Op art","url":"https://www.tate.org.uk/art/art-terms/o/op-art"},{"label":"Wikipedia：Op art","url":"https://en.wikipedia.org/wiki/Op_art"}]},"minimalism":{"summary":"极简主义约在1960年代美国形成，强调物体的字面存在、简单几何、系列重复、工业制造及作品与展场和观者身体的关系。“少即是多”式视觉简洁不足以界定它，单色、留白和无痕表面也不是所有作品的必要条件。","recognition":"基本单元的系列排列、重复间隔与作品—展场—观者的实际空间关系；简单几何、标准构件、清楚尺度和非表现性工业连接；单色、材料本色或有限综合色，综合色不承担叙事象征的必要任务；展厅环境光与真实投影揭示物体、间隔、反射和观看移动；钢、铝、荧光灯、胶合板、砖、玻璃纤维及工业制作表面。","influencedBy":"构成主义、包豪斯与现代抽象，同时反对抽象表现主义的主观手势和构图中心","influenced":"观念艺术、后极简主义、装置艺术及现代雕塑对场地和观者的关注","sources":[{"label":"Tate：Minimalism","url":"https://www.tate.org.uk/art/art-terms/m/minimalism"},{"label":"Wikipedia：Minimalism (visual arts)","url":"https://en.wikipedia.org/wiki/Minimalism#Visual_arts"}]},"neo-expressionism":{"summary":"新表现主义是1970年代末至1980年代在德国、意大利、美国等地重新强调具象、历史引用和强烈绘画性的宽泛标签，各地另有Neue Wilde、Transavanguardia等名称。厚涂、粗野人物和涂写并非共同公式，市场复兴与性别偏见也是接受史的一部分。","recognition":"画面可满幅、分区、正面或叙事，依据艺术家建立强焦点而非统一失衡；具象、符号和抽象形体可粗犷变形，也可使用克制或历史化轮廓；综合色从浑浊土色到高纯度冲突不等，不固定暗底红黄蓝；画面光服从颜料与综合色结构，写实光仅在具体作品需要时出现；厚涂、刮擦、稀薄综合色、拼贴、油彩或丙烯的可见制作差异。","influencedBy":"历史表现主义、战后具象绘画、朋克与都市文化、观念和极简之后的绘画回归","influenced":"1980年代绘画市场、当代具象与街头艺术，并引发对男性英雄主义和市场机制的批评","sources":[{"label":"Tate：Neo-expressionism","url":"https://www.tate.org.uk/art/art-terms/n/neo-expressionism"},{"label":"Guggenheim：Neo-Expressionism","url":"https://www.guggenheim.org/artwork/movement/neo-expressionism"}]},"photorealism":{"summary":"照相写实主义约在1960年代末至1970年代的美国形成，以照片为中介，通过投影、网格、喷笔或精密描绘研究相机观看、反射和日常都市表面。它不是单纯追求“像照片”，也应与后来更强调感官过度和尺度放大的超写实主义区分。","recognition":"摄影式裁切、镜头视点、街景或物件的反射层级和景深线索；严格透视、比例转译、边缘清晰度与相机造成的局部失焦；照片来源的自然综合色、综合色偏差、铬金属反射和准确中性色；日光或商品环境光按照片记录呈现高光、反射和投影；无痕油彩或丙烯、喷笔过渡、投影或网格转描与光滑画面。","influencedBy":"摄影、波普艺术的日常和消费图像，以及对抽象表现主义手势和传统写生的反应","influenced":"超写实主义、商业插画及摄影与绘画边界的后续讨论","sources":[{"label":"Tate：Photorealism","url":"https://www.tate.org.uk/art/art-terms/p/photorealism"},{"label":"Wikipedia：Photorealism","url":"https://en.wikipedia.org/wiki/Photorealism"}]},"postmodernism":{"summary":"后现代主义自1970年代成为艺术、建筑和设计中的宽泛批判框架，质疑现代主义的普遍性、原创性和媒介纯粹性，运用引用、挪用、戏仿、通俗文化与身份政治。它不是一套折衷综合色和混排字体风格，不同领域也有各自时间线和争论。","recognition":"结构由引用和批评目的决定，可分层、并置、序列化或采用传统构图；历史语汇、现代几何、媒体图像、复制品和身份符号以明确语境重组；综合色可引用任何来源；不协调强调色只是部分设计路线而非必要条件；光线服从被引用媒介、摄影、展场或建筑环境，不设统一视觉效果；复制图像、照片、录像、工业材料、装饰表面、历史构件和数字媒介。","influencedBy":"波普与观念艺术、符号学和后结构主义、女权与后殖民批评，以及对现代主义制度和形式正统的反思","influenced":"挪用艺术、图片一代、后现代建筑与设计，以及1990年代以后多元跨媒介实践","sources":[{"label":"Tate：Postmodernism","url":"https://www.tate.org.uk/art/art-terms/p/postmodernism"},{"label":"Wikipedia：Postmodern art","url":"https://en.wikipedia.org/wiki/Postmodern_art"}]},"lowbrow":{"summary":"Lowbrow是从南加州地下漫画、热棒、滑板、朋克、纹身和定制文化发展出的自我意识艺术网络，后来与‘Pop Surrealism’部分重叠。精细卡通、怪诞角色和珐琅表面常见，但艺术家从绘画到雕塑和玩具差异很大，不能统一为糖果色大头人物。","recognition":"海报、漫画、绘画、雕塑或玩具按媒介建立焦点，不固定中心头像和浅空间；卡通、写实、怪诞和定制机械形体依艺术家变化，不强制圆润比例；综合色可糖果鲜艳、热棒综合色、单色或暗色，不设红黑粉统一配方；平涂、喷绘、影棚高光或绘画光按媒介选择，不一律珐琅发亮；油彩、丙烯、喷绘、丝网、树脂、乙烯基、金属和手工线纹。","influencedBy":"地下漫画、Kustom Kulture、朋克、滑板、纹身、商业插画、超现实主义和大众玩具","influenced":"当代插画、艺术玩具、街头与画廊文化，以及高低艺术边界讨论","sources":[{"label":"Laguna Art Museum：Lowbrow Art","url":"https://lagunaartmuseum.org/exhibitions/lowbrow-art/"},{"label":"Wikipedia：Lowbrow art movement","url":"https://en.wikipedia.org/wiki/Lowbrow_(art_movement)"}]},"psychedelic":{"summary":"迷幻艺术与1960年代反文化、摇滚音乐、药物经验和政治运动相关，海报、灯光秀、唱片封面与漫画通过视觉振动、空间翻转和变形字体挑战稳定阅读。东方图像的使用常含去语境挲用，高饱和虹彩与不可读字体也不是必备条件。","recognition":"海报、唱片封面、灯光投影或漫画按媒介建立焦点与阅读路径；流动曲线、振动边界、拼贴形体和平面纹样可分别使用，不强制满幅变形；高饱和对比、有限专色、黑白或荧光投影色均有历史实例；印刷平光、液体灯光投影、舞台色光或摄影曝光按媒介处理；丝网与胶印、拼贴、液体投影、荧光颜料、廉价纸和印刷套色误差。","influencedBy":"Art Nouveau、Op Art、超现实主义、反文化音乐、意识变化经验及对亚洲和原住民图像的选择性挲用","influenced":"音乐海报、动画、时尚、地下漫画、视觉音乐与当代数字迷幻图像","sources":[{"label":"Tate：Art terms","url":"https://www.tate.org.uk/art/art-terms"},{"label":"MoMA：Art terms","url":"https://www.moma.org/collection/terms"}]},"ink-wash":{"summary":"水墨画是以墨的浓淡、干湿、积破与笔触结构组织图像的广义方法传统，唐宋以后在山水、人物、花鸟等领域持续发展。它与文人画有重要交集但并不等同：院体、禅画、职业和近现代实验同样可以使用水墨。","recognition":"留白、层叠、散点游观或集中近景按题材组织，不把空白自动等同于文人意境；以勾、皴、点、染及书写性笔触构形，精细或简放取决于具体传统；焦、浓、重、淡、清等墨阶与纸绢底色为主，也可有依据地结合淡彩；空间由墨色层次、虚实和湿边生成，不模拟统一摄影光或任意投影；纸绢吸水性、积墨、破墨、渴笔飞白、晕染边缘和真实纤维。","influencedBy":"毛笔书写、早期线描和设色绘画，以及唐宋画家对墨法与纸绢性能的探索","influenced":"文人画、禅画、东亚水墨传统和现代实验性水墨","sources":[{"label":"The Met：Landscape painting in Chinese art","url":"https://www.metmuseum.org/essays/landscape-painting-in-chinese-art"},{"label":"Wikipedia：Ink wash painting","url":"https://en.wikipedia.org/wiki/Ink_wash_painting"}]},"gongbi":{"summary":"工笔是以严谨勾线、层层分染和受控制作程序为核心的绘画方法体系，不是特定画院、朝代或花鸟仕女题材的同义词。它可用于人物、花鸟、走兽和山水，也可采用重彩、淡彩或以墨为主的不同方案。","recognition":"轮廓、主体层级和背景关系精确组织，可满幅、折枝、册页或叙事而不固定一种构图；有控制的勾线与多次分染塑形，边缘清楚但不等同于矢量硬边；矿物重彩、透明淡彩或墨色方案均可，按题材和时代选择而非固定综合色表；以综合色层次、罩染和局部明暗塑造体积，通常不依赖强烈摄影投影；熟纸或绢、墨线、胶矾层、矿物和植物综合色、反复罩染与细部点写。","influencedBy":"早期人物与叙事线描、唐宋院体制作、纸绢和矿物综合色技术","influenced":"宋元明清人物花鸟画、宫廷与职业绘画及现代工笔","sources":[{"label":"Britannica：Chinese painting","url":"https://www.britannica.com/art/Chinese-painting"},{"label":"Wikipedia：Gongbi","url":"https://en.wikipedia.org/wiki/Gongbi"}]},"ukiyo-e":{"summary":"浮世绘是江户城市文化中的绘画与木版画体系，题材包括役者、美人、名所、相扑、春画、武者和讽刺等，并依赖版元、绘师、雕师和摺师协作。大胆裁切与平面套色很重要，但早期墨摺、锦绘、风景和肉笔画不共享固定靛蓝朱红综合色。","recognition":"非对称裁切、连续组画、扇面或较稳定中心构图依题材和时期变化；清楚主版线、平面色块、云母或空摺细节，也包括无综合色墨摺与肉笔绘画；综合色从墨摺单色到多版锦绘，靛蓝、朱红和纸色只是常见选择；印刷图像多以综合色边界和重叠建空间，风景版可有大气综合色而非写实投影；多版木刻、和纸、颜料、云母、空摺、木纹和可辨套印微差。","influencedBy":"江户城市出版、绘本和肉笔画、歌舞伎与游里文化、大和绘和汉画资源","influenced":"日本近代版画、印象派和新艺术、现代漫画与全球大众图像","sources":[{"label":"The Met：Art of the pleasure quarters and the ukiyo-e style","url":"https://www.metmuseum.org/essays/art-of-the-pleasure-quarters-and-the-ukiyo-e-style"},{"label":"British Museum：Ukiyo-e","url":"https://www.britishmuseum.org/collection/galleries/japan-the-great-wave"},{"label":"Wikipedia：Ukiyo-e","url":"https://en.wikipedia.org/wiki/Ukiyo-e"}]},"rinpa":{"summary":"琳派是后世用于概括俵屋宗达、尾形光琳及酒井抱一等跨世代复兴网络的称谓，不是同时成立的正式画派。屏风跨幅、金银地、节奏化形体和湿中叠染重要，但成员、年代和媒介差异很大。","recognition":"跨屏非对称、偏置重心、重复裁切或图案满幅按具体世代和媒介选择；简化流线、植物动物节奏和书写形体可平面也可保留观察细节；金银地、群青、朱红、石绿、墨和纸色随作品变化，不限定华丽综合色；金属箔真实反射、综合色层和湿中叠染产生空间，不统一为无影平面；纸绢、金银箔、矿物综合色、云母、墨和垂らし込み形成的潮边。","influencedBy":"大和绘、古典文学与书法、工艺设计、俵屋工房和宫廷文化","influenced":"江户装饰艺术、日本画、现代设计和国际对日本平面性的接受","sources":[{"label":"The Met：Rinpa painting style","url":"https://www.metmuseum.org/essays/rinpa-painting-style"},{"label":"Wikipedia：Rinpa school","url":"https://en.wikipedia.org/wiki/Rinpa_school"}]},"nihonga":{"summary":"日本画是明治时期在现代美术制度和西洋画对照中形成的分类，使用胶彩、矿物综合色、纸绢等传统资源，同时不断吸收写生、透视和现代题材。它不是古代日本绘画的原样延续，也没有统一的柔和综合色与浅空间。","recognition":"屏风、卷轴、展览画幅和现代裁切均可，空间从平面装饰到写实纵深；精细勾线、没骨、颗粒综合色面或写生造型按艺术家和时期选择；矿物综合色、胡粉、墨、金属箔与现代综合色构成广泛范围，不强制低饱和；综合色层、胡粉和金属反射或现代观察光共同塑形，避免统一柔光；和纸或绢、岩综合色、胶、胡粉、墨、金属箔和颗粒哑光表面。","influencedBy":"江户诸画派、明治美术教育、传统材料复兴、西洋画和现代展览制度","influenced":"20世纪日本绘画、东亚胶彩画和现代传统绘画教育","sources":[{"label":"The Met：Nihonga","url":"https://www.metmuseum.org/art/collection/search?q=Nihonga"},{"label":"Wikipedia：Nihonga","url":"https://en.wikipedia.org/wiki/Nihonga"}]},"wabi-sabi":{"summary":"Wabi与sabi原本是历史变化且并不完全同义的概念，在日本茶文化、禅宗接受、和歌与工艺中与简朴、孤寂、时间变化和不完满相关。当代英语设计将两者合并为室内风格，容易误写成米色、破损、金缮和空房间的固定配方。","recognition":"茶室、器物组合、花园、纸面或修复场景按具体历史和用途组织，不设通用空室；不规则口沿、手工尺度差、简朴建筑节点或自然磨损必须来自真实对象与工艺；陶土、灰釉、漆、木、纸和苔类的具体色彩，不限米色、灰色与棕色；茶室天光、屏风纸散射光、展柜光或户外日光清楚显示材料；信乐烧陶、木、竹、和纸、漆、金属修复或无修复风化，不伪造裂缝。","influencedBy":"日本茶道、禅宗文化、和歌与隐逸观、信乐烧等茶器、材料风化与修复实践","influenced":"日本工艺与室内、现代陶艺、设计中对时间与不完满的讨论及全球商业化简约美学","sources":[{"label":"The Met：The Japanese Tea Ceremony","url":"https://www.metmuseum.org/essays/the-japanese-tea-ceremony"},{"label":"V&A：Japanese ceramics","url":"https://www.vam.ac.uk/collections/japan"}]},"superflat":{"summary":"超扁平由村上隆在2000年前后以展览和论述提出，既指压缩图像纵深的视觉语言，也批判性连接日本战后消费、御宅文化、动画漫画和艺术市场。糖果色、可爱角色只是部分作品；其理论和参与艺术家不能缩减为通用扁平插画。","recognition":"无纵深满幅、商品陈列、重复角色或空旷色场按艺术家作品选择；均匀轮廓和平面剪影可与怪诞、性化、暴力或传统图像引用并存；高饱和综合色常见，也有黑白、有限色和传统日本画综合色；视觉纵深被压缩，但光泽、综合色层与物件展示光依媒介区分；丙烯、丝网、数字印刷、雕塑光泽、动画线和日本画材料均可。","influencedBy":"日本画平面性论述、漫画动画、御宅文化、波普艺术、消费与战后社会批评","influenced":"当代日本艺术、角色和品牌跨界，以及全球对动画式艺术的接受","sources":[{"label":"MOCA：Superflat","url":"https://www.moca.org/exhibition/superflat"},{"label":"Wikipedia：Superflat","url":"https://en.wikipedia.org/wiki/Superflat"}]},"korean-minhwa":{"summary":"民画（minhwa）是后世用于概括朝鲜王朝后期及近代多类非宫廷或民间绘画的弹性称谓，题材包括文字图、虎鹊、花鸟、山水、册架与吉祥图像。它不是单一“稚拙”风格，作者、用途、制作水平和与宫廷图像的关系差异很大。","recognition":"正面、对称、屏风分幅、连续故事或不稳定透视按题材使用，不设统一满幅布局；轮廓从精细宫廷式到大胆概括不等，程式化动物器物须按真实题材选择；朱红、蓝绿、黄、墨与纸绢底常见，也有淡彩或单色作品；平面色区、有限晕染和物体叠置建立层次，不强制反常透视；纸绢、墨、矿物或植物色、屏风装裱、手工线和真实老化。","influencedBy":"朝鲜宫廷绘画、儒释道与民间信仰、岁时生活、工匠和城市图像市场","influenced":"韩国现代民俗图像、设计和对朝鲜绘画的再评价","sources":[{"label":"The Met：Korean art","url":"https://www.metmuseum.org/essays/korean-art"},{"label":"Wikipedia：Minhwa","url":"https://en.wikipedia.org/wiki/Minhwa"}]},"persian-miniature":{"summary":"波斯细密画在伊儿汗、帖木儿、萨法维等不同宫廷与城市工坊中发展，常作为诗歌、史书和相册的一部分，并涉及画家、书法家、装帧者等协作。高视点、密集细节和宝石色很重要，但赫拉特、设拉子、大不里士等中心并不共享一个综合色和空间公式。","recognition":"高视点、垂直叠置、建筑剖开、庭园或较疏人物页按时期工坊和文本选择；精细轮廓、平面纹样、人物比例与岩石云树程式依城市和画家变化；群青、朱红、粉、绿、金和纸色形成广泛综合色，不固定“珠宝色”强度；综合色层和重叠建立空间，金色仅产生真实细微反光，不模拟自然投影；抛光纸、不透明水彩、金银、精细墨线、边饰、书法和装帧接缝。","influencedBy":"伊朗写本传统、伊斯兰书法装帧、蒙古和中国图像交流、宫廷诗歌文化","influenced":"莫卧儿、德干、奥斯曼和中亚细密画，以及欧洲和现代书籍艺术","sources":[{"label":"The Met：Painting in Iran","url":"https://www.metmuseum.org/essays/painting-in-iran"},{"label":"Britannica：Persian miniature","url":"https://www.britannica.com/art/Persian-miniature"}]},"mughal-miniature":{"summary":"莫卧儿绘画由胡马雍和阿克巴时期宫廷工坊发展，在波斯写本基础上吸收印度画师传统、欧洲版画和自然观察，涵盖巨型史诗写本、肖像、动物植物、历史和相册页。所谓“波斯线描、印度综合色、欧洲写实”的公式过度简化了皇帝、画家和阶段差异。","recognition":"多人物叙事、单幅肖像、动物植物研究、相册边饰或历史场景按皇帝和工坊选择；精细轮廓、个体肖像、自然观察和综合色渐层与程式化边饰并存；矿物综合色、透明洗染、金、纸色和欧洲来源明暗按阶段作品变化；综合色体积、局部投影或平面叙事光均可，不以统一自然主义定义；抛光纸、不透明与透明水彩、金、精细毛笔、拼贴边饰和题记。","influencedBy":"波斯和中亚写本、印度画师传统、莫卧儿宫廷赞助、欧洲版画与自然观察","influenced":"德干、拉贾斯坦、帕哈里和公司画，以及南亚肖像与自然史图像","sources":[{"label":"The Met：The art of the Mughals before 1600","url":"https://www.metmuseum.org/essays/the-art-of-the-mughals-before-1600"},{"label":"Britannica：Mughal painting","url":"https://www.britannica.com/art/Mughal-painting"}]},"madhubani":{"summary":"米提拉绘画（常称Madhubani）由印度比哈尔和尼泊尔特莱米提拉地区不同社群与女性传统发展，墙面、地面和纸本绘画在仪式、婚礼、市场与社会议题中作用不同。双线满纹和彩色密填是若干流派特征，不应掩盖kachni、bharni、godna等方法及身份差异。","recognition":"边框满幅、中心仪式图、重复线场或保留空地按kachni、bharni、godna等路线选择；双线、单线、密集排线、综合色填充和纹身式图形依社群与艺术家不同；天然或商业综合色、黑白线画、纸墙本色并存，不强制高饱和满色；完全平面或由线密度产生明度，不使用写实投影和综合色渐变；泥墙、手工纸、布、天然或商业综合色、竹笔和真实手工不均。","influencedBy":"米提拉婚礼与宗教仪式、女性家居绘画、种姓社群传统和地方自然材料","influenced":"印度民间与当代艺术、女性艺术史、纸本市场和社会倡议图像","sources":[{"label":"Google Arts & Culture：Madhubani painting","url":"https://artsandculture.google.com/entity/madhubani-art/m03f6q4"},{"label":"Wikipedia：Madhubani art","url":"https://en.wikipedia.org/wiki/Madhubani_art"}]},"islamic-geometry":{"summary":"伊斯兰艺术中的几何装饰是跨西亚、北非、伊比利亚、南亚等地发展的构造方法，使用圆规直尺、星形多边形、交织和镶嵌；它不是宗教统一规定，也不是所有伊斯兰艺术的本质。综合色、网格复杂度和材料随地域与时代显著变化。","recognition":"放射、星网、交织带或周期镶嵌按具体遗址和构造系统展开，不强制中心对称；多边形、星形、strapwork和节点须保持可施工连接与一致拓扑；综合色来自砖、木、石、釉砖、马赛克和写本，不固定钴蓝绿松石金；平面图样保持清楚；建筑和物件使用真实环境光、凹凸阴影和釉面反射；砖、石木雕、石膏、马赛克、釉砖、金属、纸和手工接缝。","influencedBy":"晚期古代和区域几何传统、数学实践、建筑工艺与伊斯兰世界跨地域交流","influenced":"建筑、木石金属、瓷砖和书籍装饰，以及现代图案和数学设计","sources":[{"label":"The Met：Geometric patterns in Islamic art","url":"https://www.metmuseum.org/essays/geometric-patterns-in-islamic-art"},{"label":"Victoria and Albert Museum：Islamic art","url":"https://www.vam.ac.uk/articles/islamic-art"}]},"thangka":{"summary":"Thangka是藏传佛教与喜马拉雅地区的便携式卷轴图像，用于灌顶、观想、教学、节庆与供奉，图像依传承、本尊、仪轨与地区画派而异。中心神祗80对称不是所有thangka的统一格式，比例、手印、颜色、文字与开光状态都不得凭空拼造。","recognition":"坛城、单尊、传承上师、本生叙事或护法构图须依具体仪轨与传承区分；身体比例、手印、法器、莲座、背光与眷属位置必须根据可核实图像学；矿物蓝绿、朱砂、金、黑底或红底依时期、画派、本尊和修复证据使用；平面绘画明度与展示环境柔光为主，金色反射来自真实材料，不添加电子辉光；处理棉布、矿物与有机颜料、金线、织锦装裱、背布、经卷磨损与真实修复。","influencedBy":"印度佛教图像、尼泊尔纽瓦丽艺术、藏地宗教与文字传统、元明清宫廷交流和地区画派","influenced":"藏传佛教修行、寺院教学、喜马拉雅卷轴画与当代藏人艺术对传统图像的重译","sources":[{"label":"Rubin Museum：Verbal Description Tours","url":"https://rubinmuseum.org/verbal-description-tours/"},{"label":"Himalayan Art Resources：Thangka","url":"https://www.himalayanart.org/search/set.cfm?setID=234"}]},"mexican-muralism":{"summary":"墨西哥壁画运动在1920年代革命后国家文化计划中兴起，以公共建筑中的壁画讨论革命、劳动、土地、原住民历史与国家身份。里维拉、奥罗斯科和西凯罗斯等人的政治立场、构图与技术并不相同，运动也不能化约为土红色英雄群像。","recognition":"建筑尺度的连续叙事、纪念群组、对角动力或多场景历史结构；坚实体积、清楚轮廓、概括人物与因艺术家而异的表现性变形；土红、赭黄、蓝绿和黑白常见，也使用综合色鲜明的现代工业颜料；大面积明度分区服从远距阅读，并与建筑自然光或室内光协调；湿壁画、灰泥、硅酸盐综合色、喷绘和实验工业材料。","influencedBy":"墨西哥革命、公共教育政策、前西班牙时期艺术、殖民壁画、欧洲壁画传统与现代先锋","influenced":"美国新政壁画、社会现实主义、拉丁美洲公共艺术和后续政治壁画传统","sources":[{"label":"The Met：Mexican Muralism","url":"https://www.metmuseum.org/essays/mexican-muralism"},{"label":"Wikipedia：Mexican muralism","url":"https://en.wikipedia.org/wiki/Mexican_muralism"}]},"afrofuturism":{"summary":"Afrofuturism是从黑人历史、非洲离散经验、科技、音乐和推想叙事重新思考未来的跨媒介框架，相关实践早于1993年术语。它不等于‘非洲纹样加科幻金属’，也必须区分非洲大陆、加勒比、美国及其他离散社群的不同历史和作者位置。","recognition":"从具体人物、社群、时间观和技术关系组织场景，可纪念、日常、抽象或叙事；未来装置、服饰、身体与历史物件必须来自具体创作者和文化语境，不拼贴泛非符号；综合色依音乐、电影、地区和艺术家变化，不固定黑紫金宝石色；舞台光、日光、档案光、科幻光或平面综合色按具体媒介处理；织物、珠饰、金属、塑料、影像、声音、档案和数字材料按作品真实组合。","influencedBy":"非洲与离散历史、黑人音乐和科幻、民权与黑人解放运动、科技政治、Sun Ra、Octavia Butler等创作者","influenced":"音乐、文学、电影、时尚、视觉艺术和关于种族、技术及未来的全球讨论","sources":[{"label":"Smithsonian NMAAHC：Afrofuturism","url":"https://nmaahc.si.edu/explore/exhibitions/afrofuturism"},{"label":"Tate：Afrofuturism","url":"https://www.tate.org.uk/art/art-terms/a/afrofuturism"}]},"swiss":{"summary":"瑞士国际主义又称国际字体风格，约在1950年代由瑞士和德国的平面设计实践系统化，以非对称网格、无衬线字体、摄影和清晰信息层级追求可复制的视觉沟通。它不是只有左对齐、Helvetica和红黑白；不同设计师的网格、字体与综合色使用并不相同。","recognition":"模数网格、非对称对齐和清楚阅读顺序，网格可见或隐含；摄影、几何形、规则线和功能性图像形成精确关系；黑白红是常见方案之一，也使用全综合色摄影、蓝黄或其他受控综合色；平面印刷光与摄影原有光线并置，不添加装饰性立体光效；精确胶印、摄影网点、哑光纸、清楚裁切和有限印刷误差。","influencedBy":"新字体运动、包豪斯、构成主义、现代摄影和瑞士战前设计教育","influenced":"国际企业识别、公共信息系统、编辑设计和数字产品中的网格与信息层级","sources":[{"label":"MoMA：The International Typographic Style","url":"https://www.moma.org/collection/terms/international-typographic-style"},{"label":"Wikipedia：International Typographic Style","url":"https://en.wikipedia.org/wiki/International_Typographic_Style"}]},"mid-century-modern":{"summary":"“中世纪现代主义”是后来用于概括约1940年代中期至1960年代末建筑、家具、室内和平面设计的宽泛标签，尤其常指美国战后现代生活。它不是当时统一自称的运动，也不必然使用芥末黄、青绿、原子图案或复古插画。","recognition":"开放平面、非对称平衡、清楚功能分区或家具与建筑的整体关系；简化几何与有机曲线、细脚结构、轻巧悬挑和人体尺度；综合色随材料与地区变化，木色、中性色和明快强调色均可出现；自然日光和室内功能光揭示空间、结构和材料，不套用复古综合色滤镜；木材、胶合板、钢、玻璃、塑料、砖、织物及工业和手工结合表面。","influencedBy":"国际现代主义、包豪斯移民网络、斯堪的纳维亚设计、战时技术与战后工业和住宅生产","influenced":"战后住宅、家具和企业设计，并在20世纪末以来形成持续复兴和收藏文化","sources":[{"label":"V&A：What was Modernism?","url":"https://www.vam.ac.uk/articles/what-was-modernism"},{"label":"Wikipedia：Mid-century modern","url":"https://en.wikipedia.org/wiki/Mid-century_modern"}]},"scandinavian-modern":{"summary":"斯堪的纳维亚现代设计约在1930至1970年代获得国际影响，涵盖丹麦、芬兰、瑞典、挪威和冰岛彼此不同的建筑、家具、玻璃、陶瓷和纺织传统。人本功能、材料感和可负担性是重要议题，但“浅木、白墙、柔光”是后来的简化商品形象。","recognition":"低密度功能布局、人体尺度与物件之间清楚使用关系；从有机弯木到严格几何的多样形体，连接和结构保持可读；浅木与中性色常见，但深木、强综合色、图案织物和玻璃综合色同样存在；自然漫射光和功能照明呈现表面、使用场景与季节性环境；实木、胶合板、皮革、羊毛、玻璃、陶瓷和金属的真实材料差异。","influencedBy":"北欧工艺与民族浪漫传统、功能主义、现代工业、社会民主公共建设和各国材料文化","influenced":"国际家具、家居和公共设计，以及后来的可持续、人本和生活方式设计","sources":[{"label":"V&A：Scandinavian design","url":"https://www.vam.ac.uk/articles/scandinavian-design"},{"label":"Wikipedia：Scandinavian design","url":"https://en.wikipedia.org/wiki/Scandinavian_design"}]},"streamline-moderne":{"summary":"流线型现代主义是装饰艺术在1930至1940年代强调空气动力学、速度和量产形象的分支，横跨建筑、车辆、家电和商品设计。水平线带、圆角和光滑表面常见，但真实功能、象征性“流线化”和不同材料之间应加以区分。","recognition":"拉长水平轴、连续线带、圆角转折和前后收束的速度轮廓；水滴形、圆鼻、包覆壳体、齐平开口和流畅连接；奶油白、海军蓝、铬银及材料本色，配色并非固定三色；连续高光和环境反射强调曲面，建筑使用真实日照和凹口阴影；搪瓷钢、铝、铬、玻璃、烤漆、塑料和光滑灰泥。","influencedBy":"装饰艺术、空气动力学研究、交通工具工程、工业设计和大萧条时期的消费营销","influenced":"战后交通与家电设计、中世纪现代主义及后来的复古未来视觉","sources":[{"label":"Cooper Hewitt：Streamlining","url":"https://www.cooperhewitt.org/2017/06/20/streamlining/"},{"label":"Wikipedia：Streamline Moderne","url":"https://en.wikipedia.org/wiki/Streamline_Moderne"}]},"atomic-age":{"summary":"原子时代设计约在1945至1965年把核科学、分子图示、卫星和太空想象带入建筑、家具、纺织、广告与娱乐。它同时包含战后乐观、冷战竞争和核焦虑，不能只描述为轻快消费乐观，也不应把1957年后的太空竞赛倒推到全部时期。","recognition":"非对称爆发、轨道环、分子节点和尺度跳变组织图案或产品轮廓；星芒、回旋镖、球体、锥体、卫星和拟科学线形；青绿、珊瑚、芥末黄、黑白和金属色为常见但非固定综合色；平面广告光、商品高光或建筑霓虹与夜间环境光；丝网和胶印颗粒、塑料、铝、玻璃纤维、层压板与霓虹。","influencedBy":"核时代科学传播、中世纪现代主义、冷战、战后消费生产，以及1957年后加速的太空竞赛","influenced":"太空时代设计、Googie建筑、科幻视觉和后来的复古未来主义","sources":[{"label":"Designing Buildings：Atomic Age design","url":"https://www.designingbuildings.co.uk/wiki/Atomic_Age_design"},{"label":"Wikipedia：Atomic Age","url":"https://en.wikipedia.org/wiki/Atomic_Age"}]},"new-wave-typography":{"summary":"新浪潮字体设计约在1970年代末至1980年代由沃尔夫冈·魏因加特在瑞士教学中的实验及美国设计师进一步发展，扭转国际字体风格的中性秩序。斜向、层叠、不同字距和摄影拼合常见，但它是在网格知识上扩展阅读路径，而非任意破坏可读性。","recognition":"斜向轴、层叠信息、越界元素和可变阅读路径建立受控张力；文字块、规则线、摄影和几何形通过缩放、旋转与叠印关联；黑白、高饱和强调和综合色摄影按信息层级组织；平面印刷综合色与摄影明暗并置，半透明叠印形成综合色变化；胶印网点、复印、半透明叠层、套印偏差和纸面颗粒。","influencedBy":"瑞士国际字体风格、魏因加特的教学实验、摄影制版技术、朋克和后现代设计","influenced":"实验编辑、音乐文化、解构排版和早期数字字体设计","sources":[{"label":"AIGA Eye on Design：New Wave Typography","url":"https://eyeondesign.aiga.org/a-new-wave-of-design/"},{"label":"Wikipedia：New Wave (design)","url":"https://en.wikipedia.org/wiki/New_Wave_(design)"}]},"memphis":{"summary":"孟菲斯集团1981年在米兰成立，1988年解散，以家具、灯具、陶瓷和室内设计中的鲜明综合色、塑料层压板、图案与反功能主义姿态挑战现代主义“良好品味”。它不是一种粉彩平面背景，作品也常包含黑白、强原色和坚硬不舒适的造型。","recognition":"不对称物件组合、舞台式陈列和图案与结构的故意冲突；基础几何、曲线、锯齿、点阵和比例夸张的家具构件；强原色、粉彩、黑白和彩色材料碰撞，不限定高明度粉彩；均匀商品或展览光突出轮廓、层压板和光泽材料；塑料层压板、彩色金属、陶瓷、玻璃、木材和印刷图案。","influencedBy":"意大利激进设计、波普艺术、装饰艺术、后现代建筑和大众消费材料","influenced":"1980年代后现代产品和平面设计，以及后来的新孟菲斯、玩具和数字图形复兴","sources":[{"label":"V&A：Memphis Group","url":"https://www.vam.ac.uk/articles/the-memphis-group"},{"label":"Wikipedia：Memphis Group","url":"https://en.wikipedia.org/wiki/Memphis_Group"}]},"punk-visual":{"summary":"朋克视觉约在1970年代中期随英国、美国等地音乐和DIY文化形成，涵盖传单、同人志、唱片、服装、徽章和现场摄影。剪贴字、复印和撕纸高度重要，但不同城市、乐队和政治立场形成多种语言，黑白红并非统一配色。","recognition":"反网格剪贴、突兀裁切、越界重叠和快速传播的信息优先级；手写、模板、剪贴字、粗轮廓、照片截取和直接标记；黑白高反差、红色或来源材料综合色，不设固定三色；现场硬光、直接闪光或复印平面明度，保留记录性；复印颗粒、撕纸、胶痕、报纸、丝网、布料、别针和磨损。","influencedBy":"达达拼贴、情境主义挪用、地下出版、廉价复印技术、音乐亚文化与青年政治","influenced":"后朋克和硬核视觉、独立出版、抗议设计、时尚和后来的Grunge平面","sources":[{"label":"V&A：Punk: an aesthetic","url":"https://www.vam.ac.uk/articles/punk-an-aesthetic"},{"label":"Wikipedia：Punk visual art","url":"https://en.wikipedia.org/wiki/Punk_visual_art"}]},"grunge-design":{"summary":"Grunge平面设计约在1980年代末至1990年代与另类音乐、独立杂志和桌面出版实验相互发展，常用侵蚀字体、层叠图像和低保真复制挑战现代主义整洁。它不是音乐风格的自动视觉对应，也不能只归于单一设计师或“脏污滤镜”。","recognition":"不规则层叠、破损网格、密集边缘和仍可辨认的阅读路径；侵蚀字、手写标记、照片裁切、扫描碎片和不规则边界；脏灰、暗褐和低饱和强调常见，也可使用高纯度专色和黑白；复印平面明度、现场摄影硬光和扫描造成的局部综合色损失；划痕、污渍、油墨渗漏、复印噪点、粗纸和早期数字像素。","influencedBy":"朋克与后朋克出版、新浪潮字体、另类音乐、复印文化和早期桌面排版软件","influenced":"1990年代音乐和青年品牌、实验杂志、网页设计及后来的复古低保真视觉","sources":[{"label":"AIGA Eye on Design：Grunge Typography","url":"https://eyeondesign.aiga.org/how-grunge-typography-became-a-design-cliche/"},{"label":"Wikipedia：Grunge, graphic design","url":"https://en.wikipedia.org/wiki/Grunge#Graphic_design"}]},"architectural-brutalism":{"summary":"建筑粗野主义约在1950至1970年代发展，名称与法语 béton brut 及英国新粗野主义讨论相关，重视材料、结构、服务系统和社会用途的直接表达。清水混凝土很常见，但砖、钢、玻璃和粗糙砌体也可使用；它也并非天然等同于压迫性巨构。","recognition":"体量、交通、结构和功能单元清楚表达，可巨型也可保持紧凑公共尺度；厚重构件、深凹开口、悬挑、重复模块和外露服务或结构；综合色主要来自混凝土、砖、钢、玻璃和风化，不强制灰色单色；真实日照、阴天漫射与深凹投影显示材料和体量关系；清水混凝土模板纹、砖、粗石、钢、玻璃及可见接缝和风化。","influencedBy":"战前现代主义、勒·柯布西耶的晚期建筑、战后重建、公共机构与英国新粗野主义论述","influenced":"晚期现代建筑、高技派和当代清水混凝土建筑，并为数字“粗野主义”提供名称参照","sources":[{"label":"RIBA：Brutalism","url":"https://www.architecture.com/explore-architecture/brutalism"},{"label":"Wikipedia：Brutalist architecture","url":"https://en.wikipedia.org/wiki/Brutalist_architecture"}]},"brutalism":{"summary":"数字或网页粗野主义约在2010年代成为非正式设计标签，借用建筑粗野主义之名，以默认字体、裸露结构、直接链接、强边框或故意不精致的界面反对模板化商业网页。它不是建筑粗野主义的直接延续，也与反设计有交集但不能完全等同。","recognition":"裸露页面结构、直接信息区块、强边界或故意破坏常规网格；浏览器默认控件、硬切矩形、未装饰链接和显式系统构件；默认网页综合色、黑白、高对比或荧光强调，不设统一配色；通常无装饰光效，界面层级由边界、尺寸和浏览器状态表达；HTML默认外观、低加工位图、粗边框、重复背景和可见系统状态。","influencedBy":"早期网页的默认界面、朋克和DIY出版、现代主义系统设计，以及对高度模板化商业UX的反应","influenced":"实验网页、独立文化平台和当代反设计趋势，同时也被商业品牌吸收","sources":[{"label":"Nielsen Norman Group：Brutalism and Antidesign","url":"https://www.nngroup.com/articles/brutalism-antidesign/"},{"label":"Wikipedia：Web design, Brutalism","url":"https://en.wikipedia.org/wiki/Web_design#Brutalism"}]},"flat-design":{"summary":"扁平设计在数字界面中于2000年代末至2010年代初集中普及，以简化形体、平涂综合色、图标和排版减少装饰性拟物材质。它并非完全禁止层级、渐变和阴影；过度扁平化会削弱可点击性，后续界面已重新引入受控深度线索。","recognition":"响应式网格、清楚层级、稳定导航和以任务为中心的界面区块；简化几何图标、一致轮廓和可辨控件状态，避免把所有元素压成同一平面；有限平涂综合色与足够文字对比，可用受控综合色变化区分状态；通常减少装饰高光，必要时以轻微阴影或层级线索支持可用性；清楚矢量边缘、一致图标系统和适配不同屏幕的数字表面。","influencedBy":"国际字体风格、现代图标和信息系统、早期数字界面及对重度拟物装饰的反应","influenced":"响应式产品界面、图标与品牌插画系统，并推动Material Design等重新引入受控层级","sources":[{"label":"Nielsen Norman Group：Flat Design","url":"https://www.nngroup.com/articles/flat-design/"},{"label":"Wikipedia：Flat design","url":"https://en.wikipedia.org/wiki/Flat_design"}]},"corporate-memphis":{"summary":"Corporate Memphis是对科技公司和平台在2010年代后期广泛采用的一类模块化矢量人物插画的批评性昵称，与1980年代Memphis设计集团没有直接组织连续性。夸张比例、无面孔和柔和综合色便于品牌复用，也因同质化、去个性与掩饰平台权力而受批评。","recognition":"围绕产品任务组织人物、界面和几何模块，保留清楚信息焦点而非装饰散点；夸张肢体、简化脸部和圆润形状是常见惯例，但人物身份与无障碍信息不能被抹除；综合色来自品牌系统，可柔和或高对比，不固定蓝珊瑚芥末黄；平面综合色和有限遮叠为主；轻阴影仅服务层级与可读性；矢量面、统一描边或无描边、可复用组件和数字输出边缘。","influencedBy":"扁平设计、矢量图库、产品插画系统、现代主义几何和对Memphis综合色形状的松散借用","influenced":"SaaS品牌、 onboarding与空状态插画，也推动品牌转向更具地域、质感和人物差异的反应","sources":[{"label":"AIGA Eye on Design：Corporate Memphis","url":"https://eyeondesign.aiga.org/dont-worry-these-gangly-armed-cartoons-are-here-to-protect-you-from-big-tech/"},{"label":"Wikipedia：Corporate Memphis","url":"https://en.wikipedia.org/wiki/Corporate_Memphis"}]},"skeuomorphism":{"summary":"拟物化是让新对象保留旧对象外观或操作线索的广义设计原则，远早于智能手机；数字界面自图形用户界面早期即广泛采用，约2007至2013年在移动系统中达到高峰。皮革、木纹和立体按钮只是特定阶段的视觉表现，功能隐喻才是核心。","recognition":"界面结构映射熟悉物件、容器或操作流程，优先保证功能可理解；斜面、压印、旋钮、纸页和现实控件形态按交互用途选择；综合色模拟来源材料或功能状态，不限定暖综合色和局部高光；方向一致的高光、投影和遮挡建立可操作层级，不制造相互矛盾光源；木、皮革、金属、纸张、玻璃等数字模拟纹理和触感线索。","influencedBy":"工业产品中的历史拟形、桌面隐喻、早期图形用户界面及降低新技术学习成本的交互需求","influenced":"移动和游戏界面、数字怀旧，并在扁平设计反拨后以更克制方式持续存在","sources":[{"label":"Interaction Design Foundation：Skeuomorphism","url":"https://www.interaction-design.org/literature/topics/skeuomorphism"},{"label":"Wikipedia：Skeuomorph","url":"https://en.wikipedia.org/wiki/Skeuomorph"}]},"acid-graphics":{"summary":"“酸性图形”是2010年代后期设计媒体和青年文化中使用的非正式标签，常把荧光综合色、极端字体、液态或铬质3D、扫描噪声与锐舞/Y2K引用组合。它不是有宣言、成员和固定起止年的艺术运动，与酸性之家、迷幻艺术及acid house图形虽有联系但不能混同。","recognition":"密集越界、边到边信息、中心3D物件或多个层级冲突的海报结构；液态扭曲、尖锐几何、镀铬体和极端压缩或拉伸字体；酸绿、电紫、荧光粉、深黑和高综合色数字渐变，配色不是名称定义；镀铬反射、过曝辉光、屏幕综合色和刻意不自然的3D照明；数字噪点、扫描纹、压缩伪影、液态金属、塑料和光栅图像。","influencedBy":"锐舞与俱乐部传单、Y2K复兴、实验排版、早期互联网、3D软件和数字后处理","influenced":"当代音乐、时尚、活动视觉和动态图形中的高刺激反规范设计","sources":[{"label":"It’s Nice That：Acid graphics","url":"https://www.itsnicethat.com/search?query=acid%20graphics"},{"label":"AIGA Eye on Design：Acid Graphics","url":"https://eyeondesign.aiga.org/?s=acid+graphics"}]},"glitch-art":{"summary":"故障艺术把模拟信号失真、设备误用、数据损坏、软件错误和压缩异常转化为作品方法。电子先例可追溯到1960年代，数字实践在1990年代后扩展；RGB分离、像素撕裂和扫描线只是若干可见结果，不能代替对故障来源和媒介过程的说明。","recognition":"结构由具体错误过程产生，可切片、错位、重复、冻结或破坏时间连续性；信号弯折、数据重排、块状压缩、像素断裂和设备反馈痕迹；综合色通道偏移、过曝、位深损失和异常调色取决于技术故障类型；屏幕自发光、信号剪切和设备显示特性构成光线，不添加无关霓虹；磁带噪声、模拟雪花、数据弯折、压缩块、坏像素和软件处理痕迹。","influencedBy":"实验电子和录像艺术、设备干预、计算机文化、噪音音乐及对技术系统失效的研究","influenced":"网络和数字艺术、动态图形、音乐影像以及批判性媒体设计","sources":[{"label":"Tate：Glitch art","url":"https://www.tate.org.uk/art/art-terms/g/glitch-art"},{"label":"Wikipedia：Glitch art","url":"https://en.wikipedia.org/wiki/Glitch_art"}]},"cyberpunk":{"summary":"赛博朋克首先是20世纪80年代形成的科幻文学类型，围绕网络、企业权力、身体改造、监控和社会边缘展开；电影、动画、漫画和游戏随后形成多样视觉传统。“高科技、低生活”是有效概括，但霓虹雨夜亚洲招牌只是部分影视惯例，不能替代社会主题。","recognition":"从人物、权力系统、基础设施和界面关系组织空间，可拥挤也可冷清，不强制巨型霓虹都市；机械改造、线缆、终端和建筑层叠须服务叙事，不堆砌科技零件；综合色可低调、荧光、工业灰或日光化；青洋红不是必要配色；黑色电影式低调光、屏幕光、工业日光或过曝均可按作品设定使用；金属、玻璃、湿地面、塑料、屏幕、旧基础设施和数字噪声依场景选择。","influencedBy":"新浪潮科幻、黑色电影、朋克、控制论、城市化、冷战企业文化，以及对东京和香港等城市图像的选择性挪用","influenced":"科幻电影、动画、漫画、游戏、电子音乐与关于数字资本和身体政治的视觉讨论","sources":[{"label":"Encyclopaedia Britannica：Cyberpunk","url":"https://www.britannica.com/art/cyberpunk"},{"label":"BFI：Blade Runner and cyberpunk","url":"https://www.bfi.org.uk/features/blade-runner-cyberpunk"}]},"steampunk":{"summary":"蒸汽朋克是20世纪末形成的科幻类型与亚文化，以19世纪工业、帝国和维多利亚想象重构另类技术史。蒸汽机械和手工材料重要，但齿轮、护目镜、黄铜与褐色并非充分定义；殖民、阶级和技术幻想的历史语境也不可省略。","recognition":"按交通、工坊、城市或角色叙事组织机械系统，不在任何主体表面粘贴齿轮；锅炉、阀门、连杆、仪表和铆接须具可读功能或明确幻想规则；黄铜、铜、铁、木、皮革与综合色织物随世界设定变化，不固定褐金黑；煤气、日光、炉火或电弧光按技术设定使用，保留真实金属反射和烟尘；钢铁、铜合金、木、皮革、玻璃、织物、油污、铆接和手工加工。","influencedBy":"凡尔纳、威尔斯等早期科幻、维多利亚工业和设计、冒险文学、蒸汽技术及20世纪另类历史小说","influenced":"文学、时尚、工艺、游戏、影视和主题娱乐中的复古技术世界","sources":[{"label":"Museum of the History of Science：Steampunk","url":"https://www.hsm.ox.ac.uk/steampunk"},{"label":"Wikipedia：Steampunk","url":"https://en.wikipedia.org/wiki/Steampunk"}]},"solarpunk":{"summary":"太阳朋克是围绕气候正义、可再生能源、生态修复和互助社会的推想类型与创作社群，不是单纯“绿色版赛博朋克”。它既可呈现可实现的低技术与社区维护，也可讨论冲突和转型；植物覆盖白色未来城市只是其中一种图像。","recognition":"从能源、食物、水、交通、修复和公共生活的关系组织社区，不只让高楼长满植物；生物系统、可维修设施、地方建筑和适度高技术保持功能可读；综合色来自生态区、材料和文化，可明亮也可克制，不固定鲜绿陶土天蓝；真实日光、遮阳和能源条件塑造环境，不用普遍暖光乌托邦滤镜；木土石、再生材料、太阳能与风能设施、织物、维修痕迹和生长变化。","influencedBy":"生态科幻、气候行动、可持续设计、Arts and Crafts、去中心化技术、环境正义和原住民未来思想","influenced":"小说、插画、游戏、社区实践、气候传播和对希望型未来叙事的讨论","sources":[{"label":"Smithsonian Magazine：Solarpunk","url":"https://www.smithsonianmag.com/arts-culture/solarpunk-wants-save-world-180972452/"},{"label":"Wikipedia：Solarpunk","url":"https://en.wikipedia.org/wiki/Solarpunk"}]},"retrofuturism":{"summary":"复古未来主义是后来回看过去未来想象的文化框架，把旧时代对科技、城市、太空和日常生活的预测重新置于当代。它不是单一的1950年代太空风格，也包含乐观、讽刺、失落未来和替代历史等不同态度；视觉必须明确引用的历史时期。","recognition":"构图应服从明确引用年代，可用世界博览会轴线、太空海报、技术剖面或旧广告布局；流线机器、火箭、巨构、家电和服装造型必须与所选年代的未来观一致；综合色引用具体历史印刷、电影或产品资料，不使用通用青绿珊瑚模板；光线模拟所引年代的摄影、喷绘、舞台或印刷方法，并保留当代回看距离；旧杂志网点、喷笔、搪瓷金属、塑料、模型摄影和当代数字重构。","influencedBy":"19至20世纪世界博览会、科幻出版、交通和工业设计、原子与太空时代图像，以及后来的历史怀旧","influenced":"电影、游戏、插画、主题娱乐和品牌中的替代历史及旧未来视觉","sources":[{"label":"The Encyclopedia of Science Fiction：Retrofuturism","url":"https://sf-encyclopedia.com/entry/retrofuturism"},{"label":"Wikipedia：Retrofuturism","url":"https://en.wikipedia.org/wiki/Retrofuturism"}]},"synthwave":{"summary":"Synthwave是约2000年代中期形成的电子音乐流派及其伴生视觉文化，重构1980年代电影配乐、街机、VHS和复古未来想象。霓虹地平线、透视网格和跑车是高度流通的封面惯例，却不是所有音乐分支的必要视觉，也不应与真实1980年代设计混同。","recognition":"封面可用中心消失点、夜间道路、水平地平线或电影海报式主体结构；硬边剪影、低多边形地形、跑车、合成器界面和80年代标题几何；洋红、电青、紫和橙色渐变常见，也可按暗潮等分支使用低饱和综合色；深色背景、霓虹边光、落日辉光和VHS综合色扩散；光栅渐变、扫描线、磁带噪声、铬字、喷绘和早期3D表面。","influencedBy":"1980年代合成器音乐和电影配乐、街机与家用游戏图形、VHS媒介及复古未来文化","influenced":"独立游戏、音乐封面、网络怀旧和2010年代影视中的80年代复兴","sources":[{"label":"The Conversation：Synthwave and 1980s nostalgia","url":"https://theconversation.com/search?q=synthwave"},{"label":"Wikipedia：Synthwave","url":"https://en.wikipedia.org/wiki/Synthwave"}]},"vaporwave":{"summary":"Vaporwave约在2010年代初由网络音乐和图像文化形成，通过减速采样、企业氛围音乐、早期电脑、商场和全球化消费图像制造怀旧、疏离与讽刺。古典雕像、日文、粉青渐变只是流行语汇；其对资本主义的态度可能批判、暧昧或纯粹沉浸，不能一概而论。","recognition":"拼贴、重复、空旷商场、旧桌面界面或刻意错位的对称结构；低多边形、古典复制品、企业标识碎片、早期3D和界面窗口；粉、青、薰衣草、冷白是常见子类型，也可保留来源广告和录像综合色；柔和屏幕辉光、低对比渐变、荧光室内光和录像综合色漂移；VHS扫描线、低清数字图、压缩、塑料与铬反射、旧系统界面。","influencedBy":"采样音乐、chillwave、1980至1990年代商业媒体、早期互联网、企业图形和全球消费文化","influenced":"网络美学、音乐微流派、Y2K复兴、封面设计和社交媒体怀旧视觉","sources":[{"label":"The Conversation：Vaporwave","url":"https://theconversation.com/search?q=vaporwave"},{"label":"Wikipedia：Vaporwave","url":"https://en.wikipedia.org/wiki/Vaporwave"}]},"y2k":{"summary":"Y2K视觉指千禧年前后由互联网、消费电子、锐舞、时尚和早期CG共同形成的多种未来想象，也包含对2000年计算机问题的焦虑。铬、凝胶、液态字体和冰蓝界面是部分路线；泡泡糖粉色、网络像素和极简科技同样存在，不能合成一种统一复古滤镜。","recognition":"界面、杂志、广告、时尚或三维对象按具体媒介组织悬浮、轨道、网格或拼贴；液态圆形、锐利科技线、像素和早期CG体块按来源年代选择，不全部叠加；冰蓝银绿、粉彩、黑白或高饱和流行综合色均可，依具体子路线；影棚高光、屏幕光、闪光灯或早期CG照明按媒介使用，不统一边缘辉光；铬、透明塑料、凝胶、网布、像素、低多边形、印刷光泽和压缩痕迹。","influencedBy":"1990年代后期互联网、电子消费品、锐舞与流行音乐、科幻、杂志设计和早期三维软件","influenced":"2010年代末以来的时尚和音乐复兴、网络设计、生成式三维和品牌怀旧","sources":[{"label":"V&A：Y2K fashion","url":"https://www.vam.ac.uk/articles/y2k-fashion"},{"label":"Wikipedia：Y2K aesthetic","url":"https://en.wikipedia.org/wiki/Y2K_aesthetic"}]},"gothic-subculture":{"summary":"哥特亚文化在1980年代初英国后朋克与夜店场景中形成，音乐、粉丝网络和DIY自我造型比泛化的中世纪建筑或维多利亚服饰更能界定其起源。黑色、苍白妆面、网袜和宗教意象只是部分分支；浪漫哥特、deathrock、cybergoth等在时间和地区上需分开。","recognition":"乐队舞台、夜店群体、街头全身或亲密肖像按时期与场景组织；后朋克窄身、浪漫层搭、deathrock破损或其他分支廓形必须具体，不套用吸血鬼模板；黑色常见，但可与白、红、紫、宝石色或后朋克冷色并用，不设单色禁令；舞台逆光、夜店暗光、日间街拍、直接闪光或棚光按场景使用；皮革、蕾丝、天鹅绒、棉布、金属、网眼、发胶与低成本DIY改造。","influencedBy":"英国后朋克与punk、glam rock、恐怖电影、德国表现主义影像、夜店与粉丝杂志网络","influenced":"全球哥特音乐与时尚、夜店造型、杂志摄影、gothic lolita、cybergoth和当代暗色流行视觉","sources":[{"label":"V&A：Gothic fashion","url":"https://www.vam.ac.uk/articles/gothic-fashion"},{"label":"Museum of Youth Culture：Goth","url":"https://www.museumofyouthculture.com/goth/"}]},"film-noir":{"summary":"黑色电影是法国评论家在1946年后对一批美国犯罪电影进行回溯性归类的术语，并非当时电影人共同签署的运动。都市犯罪、道德暧昧、宿命叙事和低调光影常见，但影片也有白天、外景、纪实化和不同性别视角，不能缩成百叶窗阴影公式。","recognition":"构图可使用深景、倾斜机位、狭窄室内或白天外景，须服务犯罪与道德关系；人物、建筑、道具和阴影的轮廓随具体摄影风格变化，不强制斜线与剪影；黑白灰阶、染色或早期彩色均可，不把死黑高反差作为必备条件；低调侧光、现场日光、夜景反射或较平的纪实化用光按影片选择；35mm胶片颗粒、棚景或实景表面、烟雾、潮湿反光和时代性服化道。","influencedBy":"德国表现主义电影与流亡影人、硬汉派犯罪小说、1930年代法国诗意现实主义、美国都市化与战时社会","influenced":"新黑色电影、犯罪影视、摄影、广告、漫画和游戏中对都市、权力与道德暧昧的表达","sources":[{"label":"BFI：What is film noir?","url":"https://www.bfi.org.uk/features/what-film-noir"},{"label":"Encyclopaedia Britannica：Film noir","url":"https://www.britannica.com/art/film-noir"}]},"maximalism":{"summary":"极繁主义不是边界清楚的单一运动，而是以丰盛、重复、综合色、图案、收藏和多重历史引用对抗简约规范的跨媒介倾向。高密度并不意味着无层级堆砌；巴洛克、维多利亚室内、后现代设计和当代时尚各有不同机制。","recognition":"以主次焦点、分区和重复节奏控制高密度，不把所有空白填满；图案、物件、纹理和历史引用可多层并置，但保持尺度与边界可辨；综合色可以宝石色、粉彩、黑白或地方综合色体系构成，不固定深色底和金色；真实环境光区分材质和层级，局部强调不等于全场戏剧照明；织物、壁纸、木、漆、金属、陶瓷、纸张和收藏物的真实表面。","influencedBy":"巴洛克与洛可可装饰、历史主义、收藏陈设、波普艺术、后现代主义及反极简立场","influenced":"当代室内、时尚、编辑设计、品牌与沉浸式展览中的高密度表达","sources":[{"label":"V&A：Maximalism in fashion","url":"https://www.vam.ac.uk/articles/maximalism-in-fashion"},{"label":"Wikipedia：Maximalism","url":"https://en.wikipedia.org/wiki/Maximalism"}]},"neo-futurism":{"summary":"新未来主义是对20世纪后期至当代未来导向建筑和设计的宽泛称呼，常强调技术、动态空间和新材料，但不是成员明确的统一运动。连续曲面、轻质结构或可持续系统只是不同路线，不能把参数化白色壳体当作充分定义。","recognition":"按交通、文化、居住或基础设施功能组织动态路径和空间序列，不只追求流线轮廓；壳体、肋骨、张拉结构、曲面或模块依项目技术选用，不固定白色空气动力造型；材料本色、白灰、综合色表皮和功能色随项目变化；真实日光与人工环境光显示结构、透明和使用状态，不加无依据未来辉光；钢、混凝土、玻璃、复合材料、膜材、数字制造节点和可维护接缝。","influencedBy":"历史未来主义、战后技术建筑、高技派、太空时代设计、数字建模与环境工程","influenced":"交通枢纽、文化地标、参数化建筑、科技产品与未来城市想象","sources":[{"label":"RIBA：Neo-futurism","url":"https://www.architecture.com/explore-architecture/neo-futurism"},{"label":"Wikipedia：Neo-futurism","url":"https://en.wikipedia.org/wiki/Neo-futurism"}]},"biomorphic":{"summary":"生物形态抽象是从细胞、器官、植物和生长过程中提炼非几何形体的宽泛倾向，常联系超现实主义和20世纪现代设计，但不是统一运动。软曲线可平面、雕塑、家具或数字化，也不必呈现半透明树脂和粉绿珊瑚综合色。","recognition":"去中心化的流动布局与形态包含；细胞式圆润轮廓与连续柔性曲面；珊瑚粉、海水绿与乳白过渡；柔和漫射光、透光与次表面散射；半透明树脂、胶质与柔软陶土。","influencedBy":"自然形态研究、超现实主义自动性、现代雕塑、显微图像和有机设计","influenced":"现代雕塑与家具、有机建筑、抽象动画和数字生成形态","sources":[{"label":"Tate：Biomorphic","url":"https://www.tate.org.uk/art/art-terms/b/biomorphic"},{"label":"MoMA：Biomorphic abstraction","url":"https://www.moma.org/collection/terms/biomorphic-abstraction"}]},"neo-pop":{"summary":"Neo-Pop是对1980年代以来重新使用商品、名人、玩具、漫画和品牌图像的宽泛评论标签，并非正式团体。作品可采用挪用、雕塑、摄影、装置或数字媒介；粗黑轮廓、电光原色和乙烯基光泽只代表部分艺术家。","recognition":"单一超大焦点与大胆边缘裁切；粗黑轮廓、简化平涂与图标式剪影；电光红黄蓝与黑白硬边分区；两至三级平涂明暗与小面积塑料高光；丝网印刷、漫画网点与乙烯基光泽。","influencedBy":"Pop Art、Pictures Generation、商品与名人文化、漫画、广告和后现代挪用","influenced":"当代商品图像、艺术玩具、品牌合作和关于消费与作者性的批评","sources":[{"label":"Tate：Neo-pop","url":"https://www.tate.org.uk/art/art-terms/n/neo-pop"},{"label":"Wikipedia：Neo-pop","url":"https://en.wikipedia.org/wiki/Neo-pop"}]},"naive-art":{"summary":"‘稚拙艺术’是艺术史和市场对未受学院训练或有意采用直接、非学院表现的作品所用外部分类，容易把不同创作者幼儿化。平面空间和非标准比例常见但不是能力缺失；具体艺术家、地区、自我定位和专业实践必须优先说明。","recognition":"叙事、肖像、风景或图案按具体艺术家组织，不预设简单前后排列；比例、透视和轮廓应尊重艺术家选择，不将差异描述为儿童能力；综合色随作者、材料与地区变化，不固定清澈原色；平面光、观察光或象征性综合色按作品处理，不统一两级阴影；油彩、水粉、铅笔、木板、纸、纤维或其他具体材料及手工痕迹。","influencedBy":"民间和自学艺术实践、现代主义对非学院表达的接受、收藏与画廊分类","influenced":"现代绘画、Outsider Art讨论、插画和对学院训练标准的反思","sources":[{"label":"Tate：Naive art","url":"https://www.tate.org.uk/art/art-terms/n/naive-art"},{"label":"MoMA：Henri Rousseau","url":"https://www.moma.org/artists/5056"}]},"atompunk":{"summary":"原子朋克是后来的复古未来类型标签，借用二战后至1960年代中期的核能、太空竞赛、民防和消费设计想象。它既包含技术乐观，也应容纳核焦虑和冷战政治；原子轨道、回旋镖、铬和粉彩只是历史图像资源，不是统一世界设定。","recognition":"按家庭、实验室、民防、交通或太空叙事组织场景，不拼贴所有原子时代图标；圆顶、胶囊、回旋镖、轨道和机械装置依据具体年代参照与功能使用；综合色可来自1950年代商品、军用设施、宣传印刷或黑白档案，不固定樱桃红青绿奶黄；影棚日光、荧光灯、电视光或警报光按叙事使用，不一律乐观明亮；珐琅金属、铬、玻璃、早期塑料、印刷纸、混凝土和使用磨损。","influencedBy":"原子时代设计、冷战科幻、Googie、Streamline Moderne、航天宣传、民防与核武器文化","influenced":"游戏、动画、插画和影视中的中世纪复古未来世界观","sources":[{"label":"MoMA：Designs for the Atomic Age","url":"https://www.moma.org/calendar/exhibitions/1775"},{"label":"Wikipedia：Atomic Age in design","url":"https://en.wikipedia.org/wiki/Atomic_Age_(design)"}]},"dieselpunk":{"summary":"柴油朋克是以两次世界大战之间及二战年代的柴油工业、Art Deco、航空、宣传和大众文化构造另类历史的后设类型。重型机械、铆接钢板和烟尘常见，但军绿色和战争崇拜不是必要条件；法西斯主义、殖民与战争图像需被准确而非装饰性地处理。","recognition":"按城市、交通、工厂、角色或冲突叙事组织重型系统，不默认战争宣传构图；发动机、装甲、散热格、铆接外壳和流线体须具功能或一致幻想逻辑；钢灰、煤黑、军用色、Art Deco综合色和民用广告综合色均依设定，不固定军绿暗红；工业日光、探照灯、黑色电影低调光或广告棚光按场景使用；钢、铝、橡胶、玻璃、油污、烟尘、磨损漆面、纸张和铆接。","influencedBy":"Art Deco、Streamline Moderne、柴油交通、航空与城市工业、纸浆科幻、黑色电影和战争宣传","influenced":"游戏、漫画、影视和模型中的重工业复古未来及另类历史","sources":[{"label":"Cooper Hewitt：Machine Age design","url":"https://www.cooperhewitt.org/tag/machine-age/"},{"label":"Wikipedia：Dieselpunk","url":"https://en.wikipedia.org/wiki/Dieselpunk"}]},"blue-green-landscape":{"summary":"青绿山水是以石青、石绿等矿物色层层设染山石的设色传统，不是封闭于某一朝代的画派。它可从唐宋宫廷性重彩到明清仿古和近现代转化；综合色、勾线、皴法与金色使用强度均随作品而变。","recognition":"层叠山体、卷轴游观和水陆间隔形成连续路径，可工整也可与水墨结构结合；先以轮廓和皴法立骨，再分层罩染石青石绿；不把山体简化为统一扁平色块；石青、石绿为核心，配赭石、朱砂、白粉和纸绢底；金色并非必要；综合色明度与层层罩染建立空间，纸绢作品不模拟戏剧性自然投影；纸绢、墨线、矿物综合色颗粒、胶结层、罩染与局部金泥。","influencedBy":"早期中国山水与人物背景、矿物颜料技术及隋唐宫廷绘画","influenced":"金碧山水、宋元明清设色山水及近现代中国画的矿物综合色实践","sources":[{"label":"The Met：Landscape painting in Chinese art","url":"https://www.metmuseum.org/essays/landscape-painting-in-chinese-art"},{"label":"Wikipedia：Blue-green landscape","url":"https://en.wikipedia.org/wiki/Blue-green_landscape"}]},"song-court-painting":{"summary":"宋代画院绘画是北宋、南宋宫廷机构和职业画家实践的宽泛集合，涵盖山水、花鸟、人物、道释与纪实题材。精察物象、制作控制和皇室文化很重要，但小景、诗意留白或边角构图只适用于部分南宋路线，不能概括整个宋院。","recognition":"全景、册页小景、折枝花鸟或人物叙事均可，构图必须与北宋或南宋具体门类相符；精细勾染、写生形态、皴法和受控笔墨按山水、花鸟、人物分别选择；水墨、淡彩、矿物重彩与绢地色均存在，不以灰绿金色统一宋院；综合色和墨阶建立空气与体积，光线处理随媒介题材而变而非统一柔光；绢纸、墨、矿物或植物综合色、反复罩染和保存状态中的磨损。","influencedBy":"五代及更早宫廷绘画、写生观察、画院制度和宋代皇室收藏文化","influenced":"元明清宫廷与职业绘画、东亚院体传统和后世工笔花鸟山水","sources":[{"label":"Britannica：Chinese painting, Five Dynasties and Song dynasty","url":"https://www.britannica.com/art/Chinese-painting/Five-Dynasties-907-960-and-Ten-Kingdoms-902-978"},{"label":"Wikipedia：Song dynasty painting","url":"https://en.wikipedia.org/wiki/Song_dynasty_painting"}]},"baimiao":{"summary":"白描是以单色墨线为主要造型手段、尽量少设或不设综合色的绘画方法，尤其用于人物，也可表现花卉等题材。其质量依赖线条的轻重、顿挫、疏密和结构准确性；“白”不是白色颜料，白描也不排斥少量淡墨辅助。","recognition":"以人物或主体轮廓组织留白，线群疏密和相互穿插代替综合色分区；单色墨线通过粗细、提按、顿挫和转折说明结构，避免均一矢量描边；以墨与纸绢本色为主，可有极少淡墨层次但不转为综合色画；均匀观看光保持线条清楚，体积主要由线性结构而非投影塑造；纸绢、毛笔墨、流畅长线、干湿变化与少量淡墨，不添加假旧裂纹。","influencedBy":"早期人物线描、顾恺之等传统归属、唐宋人物画和书法用笔","influenced":"人物画稿本、道释画、工笔底稿与后世线描教学和出版图像","sources":[{"label":"The Met：Chinese painting","url":"https://www.metmuseum.org/essays/chinese-painting"},{"label":"Wikipedia：Baimiao","url":"https://en.wikipedia.org/wiki/Baimiao"}]},"zen-painting":{"summary":"‘禅画’是对禅宗僧侣、寺院网络或禅宗题材相关绘画的宽泛称呼，包括道释人物、山水、兰竹、圆相和题诗书写。简笔、留白与不完满墨迹很有影响，但不能将所有黑白水墨或随意一笔圆归入禅画。","recognition":"人物、山水、花木、圆相或题诗空间按作者、寺院、卷轴与用途组织；减笔轮廓、精密皔法、湿墨团块、干笔飞白或书法线并非同时必备；墨色层次、纸绢暖色、淡设色或印章朱红依作品与时代变化；绘画以墨密度组织层次，展示时采用保护性柔光，不添加影棚投影；纸、绢、磨墨、湿干笔痕、装裱、印章和真实年代磨损。","influencedBy":"中国宋元禅宗、文人与寺院书画、水墨技法、中日僧侣交流和公案与诗文","influenced":"日本水墨画、茶文化、寺院艺术、近现代书画与全球现代主义对‘自发性’的重译","sources":[{"label":"The Met：Zen Buddhism","url":"https://www.metmuseum.org/essays/zen-buddhism"},{"label":"Kyoto National Museum：Collection","url":"https://www.kyohaku.go.jp/eng/collection/"}]},"sosaku-hanga":{"summary":"创作版画以“自画、自刻、自摺”强调艺术家的直接创作，反对版元分工成为定义艺术价值的唯一机制，但实践中也有协作和多种版种。粗刀痕与错版并非必然，木版、水印、拓印和抽象路线差异明显。","recognition":"直接不对称、块面构成、具象场景或抽象结构按艺术家选择，保留版面决策；刀刻粗线、细线、木纹、拓印或几何块面皆可，不把粗糙当作真实性标志；黑色主版、有限套色、多综合色或纸张本色随版种与艺术家改变；平面综合色关系、透明水印和纸面吸收建立层次，不强制无影；自刻木版、和纸、刀痕、水性或油性油墨、套印微差和手工压印。","influencedBy":"近代个人艺术观、浮世绘和民间版画、欧洲版画与日本美术教育","influenced":"日本现代版画、战后国际版画交流和个人工作室印刷","sources":[{"label":"The Met：Sosaku hanga","url":"https://www.metmuseum.org/art/collection/search?q=sosaku%20hanga"},{"label":"Wikipedia：Sosaku-hanga","url":"https://en.wikipedia.org/wiki/S%C5%8Dsaku-hanga"}]},"yamato-e":{"summary":"大和绘是平安时代以来相对于唐绘等分类形成的日本绘画传统，题材涉及宫廷文学、名所、四季、寺社缘起和历史叙事。吹拔屋台、连续卷轴和浓丽设色是重要方法，却不能覆盖屏风、册页、白描式作品或不同阶段。","recognition":"斜向俯视、连续绘卷、屏风跨幅或册页分场按作品选择，不强制吹拔屋台；细线、平涂、引目钩鼻式人物或写实细节依时代题材变化；群青、朱红、石绿、金银和纸绢底色常见，也有水墨与白描路线；以色区、重叠和金银反光组织浅空间，不套用统一平面柔光；纸绢、矿物综合色、墨线、金银箔、颜料脱落和卷轴折痕。","influencedBy":"奈良和平安宫廷绘画、唐绘的选择性吸收、日本文学和四季名所文化","influenced":"土佐派、琳派、绘卷传统和近代对日本本土绘画的建构","sources":[{"label":"The Met：Yamato-e painting","url":"https://www.metmuseum.org/essays/yamato-e-painting"},{"label":"Wikipedia：Yamato-e","url":"https://en.wikipedia.org/wiki/Yamato-e"}]},"shanghai-school-painting":{"summary":"海上画派形成于开埠后的上海艺术市场，汇聚来自江浙等地的职业和文人画家，以金石书法、写意花鸟、人物和适应城市销售的画幅与题材见长。鲜艳综合色和近距裁切很常见，但任伯年、吴昌硕等人的造型与笔墨不能被合并为一种商业风格。","recognition":"条幅、册页、扇面和近距花鸟人物按市场与题材组织，可疏可满；金石书写、写生人物、没骨或勾线花鸟随画家变化，不设统一粗线；墨、朱砂、花青、石绿、藤黄和纸本暖白形成从淡雅到浓艳的范围；墨色和综合色层次结合观察塑形，不把西式明暗或平光设为统一模式；纸绢、水墨、矿物或植物综合色、书法题跋、印章和商品化装裱。","influencedBy":"扬州画坛、金石学、民间图像、传统人物花鸟和上海城市艺术市场","influenced":"近现代中国画、岭南画派的部分交流、月份牌和城市视觉文化","sources":[{"label":"Britannica：Chinese painting, Qing dynasty","url":"https://www.britannica.com/art/Chinese-painting/Qing-dynasty-1644-1911-12"},{"label":"Wikipedia：Shanghai School","url":"https://en.wikipedia.org/wiki/Shanghai_School"}]},"dansaekhwa":{"summary":"韩国单色画（Dansaekhwa）是对1970年代起若干韩国艺术家近单色、重复动作和材料过程的后设集合称谓，而非当时纲领统一的团体。白色和禅意并非必要条件；刮、推、浸透、折叠与画布关系因艺术家而异，也不能简单等同西方极简主义。","recognition":"满幅、网格、重复线或材料渗透按艺术家过程组织，不以空白中心代表单色画；推、刮、点、压、折或反面渗透产生微小单元和真实表面起伏；白、灰、土色、深蓝和其他窄综合色域均可，不把白色设为韩国性；柔侧光揭示真实低浮雕、纤维和微综合色差，避免精神化辉光；油彩、铅笔、麻布、韩纸、颜料吸收、重复劳动和物理磨损。","influencedBy":"韩国战后艺术、实验艺术、传统材料观、现代抽象和日本及国际展览网络","influenced":"韩国当代艺术、过程性绘画和21世纪国际市场对战后亚洲抽象的重估","sources":[{"label":"Guggenheim：Only the Young, Experimental Art in Korea","url":"https://www.guggenheim.org/exhibition/only-the-young-experimental-art-in-korea-1960s-1970s"},{"label":"Wikipedia：Dansaekhwa","url":"https://en.wikipedia.org/wiki/Dansaekhwa"}]},"han-dynasty-silk-painting":{"summary":"汉代帛画以墓葬出土绢画为重要材料，题材和结构并不统一；马王堆T形帛画的宇宙分区只是著名个案。细劲线描、平涂设色、层叠与轴向组织可作为材料特征，但不能把一件作品的天地结构推广为全部汉代帛画。","recognition":"按具体作品采用轴向、分层、横卷或仪仗式组织，不把T形宇宙图式设为通例；细线轮廓、平涂色面与流动带状形，也保留因残损造成的断续；老化绢褐、墨黑、朱红、赭黄与有限矿物蓝绿，综合色依据现存颜料；均匀文物光显示绢和薄色层，空间由重叠与分区而非投影塑造；老化绢纤维、墨线、矿物或植物色、折痕、脱落与修复痕迹。","influencedBy":"战国楚地帛画与漆器图像、汉代礼制和墓葬观念","influenced":"中国人物与叙事绘画、绢本设色传统及后世对早期绘画史的认识","sources":[{"label":"The Met：Han dynasty (206 B.C.–220 A.D.)","url":"https://www.metmuseum.org/essays/han-dynasty-206-b-c-220-a-d"},{"label":"Wikipedia：Han dynasty art","url":"https://en.wikipedia.org/wiki/Han_dynasty_art"}]},"han-dynasty-pictorial-stone":{"summary":"汉代画像石是在墓室、祠堂等建筑构件上雕刻的图像，地域、题材和技法差异显著，常见宴饮、车马、神话、历史故事与生产活动。分栏和浅浮雕很重要，但连续叙事、侧面剪影或拓片黑白并非每件原石的唯一观看方式。","recognition":"可用横向分栏、独立画面或建筑构件连续关系，按出土地与原物结构选择；减地、线刻或浅浮雕产生硬边轮廓、侧面人物和压缩体积；原石灰褐、残留综合色与拓片黑白须区分呈现，不将拓片综合色当作原作色；原石以擦边光揭示凿刻深度；拓片以均匀平面对比阅读墨色转印；石材颗粒、凿线、浅浮雕、风化、残色与纸本拓印纤维。","influencedBy":"汉代墓葬与祭祀制度、工匠图像传统、建筑石作和历史神话叙事","influenced":"墓葬叙事、石刻图像、金石学和拓片传播","sources":[{"label":"The Met：Han dynasty (206 B.C.–220 A.D.)","url":"https://www.metmuseum.org/essays/han-dynasty-206-b-c-220-a-d"},{"label":"Wikipedia：Han dynasty art","url":"https://en.wikipedia.org/wiki/Han_dynasty_art"}]},"oracle-bone-script-aesthetic":{"summary":"甲骨文主要见于商代晚期用于占卜记录的龟甲和兽骨刻辞，是已知成熟汉字体系的早期材料之一。字形、行列和刻痕受骨片形状、钻凿与裂纹影响；现代转用必须准确保留给定文字，不能把象形感当作可随意拼造的装饰符号。","recognition":"刻辞行列随骨片边界、钻凿与裂纹调整，字距、大小和方向保留实际差异；以刀刻细线、尖折和简化象形成字，避免把后世毛笔笔意倒置为甲骨特征；龟甲或兽骨暖白、刻槽褐黑与拓片黑白；综合色来自材料和记录方式；档案式均匀光用于阅读，擦边侧光仅用于揭示真实浅刻和裂纹；骨甲、刀刻凹线、钻凿、占卜裂纹、风化和拓印颗粒。","influencedBy":"更早的汉字书写实践、商代占卜制度，以及骨甲表面的刻写条件","influenced":"商周文字研究与后世书法、篆刻和金石学对古文字的再认识","sources":[{"label":"British Museum：How to read an oracle bone","url":"https://www.britishmuseum.org/blog/how-do-you-read-oracle-bone"},{"label":"Wikipedia：Oracle bone script","url":"https://en.wikipedia.org/wiki/Oracle_bone_script"}]},"bronze-inscription-aesthetic":{"summary":"青铜器铭文跨商代晚期、西周、春秋与战国而持续变化，常铸或刻于礼器内外，内容涉及族徽、作器、册命与纪功。圆厚或团块化字形是部分阶段与器物的表现，不能把千余年的金文归并为一种字体或把铜锈当成书体本身。","recognition":"铭文按器内壁、盖、腹或底部空间排列，纵列和字幅随器形及时代改变；铸刻线条可圆厚、匀整或保留不规则边缘，必须依据具体时代与器物；青铜本色、鎏金、铜锈与拓片黑白分别处理，不将绿锈设为必要综合色；擦边光显示铸刻高低和器壁曲率，拓片版本保持平面明度；铸造铜合金、凹凸铭文、范铸痕、腐蚀层和纸本拓印。","influencedBy":"商代文字传统、礼制铸造技术与不同区域的青铜器生产","influenced":"战国文字、篆书系统，以及宋代以来金石学、篆刻与书法复古","sources":[{"label":"The Met：Chinese calligraphy","url":"https://www.metmuseum.org/essays/chinese-calligraphy"},{"label":"Wikipedia：Chinese bronze inscriptions","url":"https://en.wikipedia.org/wiki/Chinese_bronze_inscriptions"}]},"gutai-art-association":{"summary":"具体美术协会由吉原治良等1954年在关西创立，鼓励艺术家‘做前所未有之事’，以材料、身体、户外、舞台和技术实验重新定义绘画。撕纸、脚绘和泼洒是重要个案，但Gutai并不等同日本版行动绘画。","recognition":"行动痕迹、非中心扩散与材料事件；撕裂、泼洒、穿透与大尺度手势；高对比原色、黑白与材料本色；展示光突出凹凸和材料变化；厚颜料、纸布破口与行为制作痕迹。","influencedBy":"战后日本社会、吉原治良的抽象实践、儿童美术、国际抽象和新材料","influenced":"日本及全球行为、装置、材料与跨媒介艺术的重新评价","sources":[{"label":"Guggenheim：Gutai","url":"https://www.guggenheim.org/artwork/movement/gutai"},{"label":"Tate：Gutai","url":"https://www.tate.org.uk/art/art-terms/g/gutai"}]},"clerical-script-aesthetic":{"summary":"隶书由战国秦汉书写实践逐步形成，并在汉代简牍、帛书和碑刻中呈现多样面貌。扁方、横势与方折是重要倾向；“蚕头雁尾”和波磔是成熟汉隶的代表性处理，却不是每个时期、每个字或每一横画都必须出现。","recognition":"横向展开的字域与清楚行列可形成稳定节奏，同时保留简牍和碑刻的差异；方折、横势和波磔按具体汉隶范本使用，蚕头雁尾不机械复制到所有笔画；墨黑、纸白、木简褐、碑石灰与少量印色，避免固定复古综合色；墨迹使用平面光；简牍、石刻和拓片按真实载体控制侧光与对比；毛笔墨、竹木简、帛、碑刻、拓片颗粒与纸纤维。","influencedBy":"战国秦系书写、篆隶转换、行政文书与简牍快速书写","influenced":"楷书的形成、汉碑传统、金石学与近现代书法复兴","sources":[{"label":"The Met：Chinese calligraphy","url":"https://www.metmuseum.org/essays/chinese-calligraphy"},{"label":"Wikipedia：Clerical script","url":"https://en.wikipedia.org/wiki/Clerical_script"}]},"lingnan-school":{"summary":"岭南画派是20世纪初以广东为中心的改革中国画网络，通常联系高剑父、高奇峰、陈树人等人，吸收日本画、西方写生与摄影，同时重估中国笔墨。它不是单纯“水墨加明亮水彩”，成员对政治、教育和风格的立场也不完全相同。","recognition":"近代裁切、明确焦点、卷轴留白或叙事场景按画家和题材选用；观察性轮廓、水墨线、湿润综合色面和局部精描形成中外方法交汇；墨、灰绿、明亮水彩或日本画综合色及纸本暖白，不设统一岭南综合色谱；方向性自然光、空气综合色和水墨晕染可共同塑形，但须服从具体作品；纸本水墨、水彩或日本画综合色、撞水撞粉、细颗粒和现代装裱。","influencedBy":"中国画传统、日本画教育、西方写生和摄影、晚清民国改革思想","influenced":"广东和港澳现代中国画、美术教育及20世纪中国画革新","sources":[{"label":"Hong Kong Museum of Art：Chih Lo Lou Gallery","url":"https://hk.art.museum/en/web/ma/exhibitions-and-events/chih-lo-lou-gallery.html"},{"label":"Wikipedia：Lingnan School","url":"https://en.wikipedia.org/wiki/Lingnan_School"}]},"ma-xia-school":{"summary":"‘马夏’指马远、夏圭及与南宋画院相关的山水传统与后世归类，并非成员名册明确的正式画派。偏角布景、斗量留白和斧劈皔具有代表性，但手卷、册页、宫扇及各作品归属复杂，不应将每幅都做成‘马一角’。","recognition":"偏角、半边、手卷连续、册页对景或宫扇构图按实物格式选择，不强制一角；斧劈皔、湿墨山石、精细建筑人物、树枝和远山轮廓随作品变化；墨色、绢本暖色、淡赭、灰绿或局部设色依保存和归属证据使用；空间依靠墨色、烟岚与留白建立，展示使用保护性柔光，不添加现代逆光；绢或纸、水墨、淡色、干湿皔法、装裱和真实磨损与修补。","influencedBy":"北宋与南宋山水、宫廷画院、李唐传统、江南水域经验和诗意观景","influenced":"元明山水画批评、日本室町水墨、浙派与后世对南宋院体的评价","sources":[{"label":"The Met：Southern Song Painting","url":"https://www.metmuseum.org/essays/landscape-painting-in-chinese-art"},{"label":"National Palace Museum：Painting collection","url":"https://theme.npm.edu.tw/selection/Category.aspx?sNo=04000012&lang=2"}]},"mianzhu-new-year-print":{"summary":"四川绵竹年画以木版墨线后自由手绘施彩的做法最具代表性，也包含素版等类型。综合色、刷痕和造型随作坊与画师而变；粗放边缘、粉笺和中心主图不是所有绵竹作品的固定条件。","recognition":"单幅、对幅、条屏或故事场景按用途组织，保留手绘施彩的自由密度；木版墨线提供骨架，手工填色、勾染和夸张造型因画师而异；大红、桃红、黄、绿、蓝、墨和纸白可明快碰撞，也存在素版与有限色版本；印线平面清楚，手绘综合色保留刷色浓淡，不用立体投影统一塑形；木版墨线、手绘颜料、地方纸张或粉笺、刷痕、印压与使用磨损。","influencedBy":"四川雕版、民间绘画、戏曲与岁时信仰、地方纸张和手工施彩","influenced":"西南年画、现代民间美术研究和当代非遗创作","sources":[{"label":"China Daily：Mianzhu New Year paintings","url":"https://www.chinadaily.com.cn/a/202302/01/WS63d9fd6ea31057c47ebac264.html"},{"label":"Wikipedia：Mianzhu New Year picture","url":"https://en.wikipedia.org/wiki/Mianzhu_New_Year_picture"}]},"japanese-nanga":{"summary":"日本南画或文人画是江户画家通过中国画谱、输入绘画、诗文与想象重构的文人实践，并非中国文人画的直接复制。职业身份、社交和地方网络多样，池大雅、与谢芜村等人的笔墨、设色和题材也不一致。","recognition":"平远层叠、密集山水、诗画轴或册页按画家选择，不统一为疏淡书斋小景；干笔皴擦、松动轮廓、点线和设色形态来自对中国图像的个体再解释；墨、淡赭、透明青绿和纸色常见，也有综合色更丰富作品；墨阶与设色层建立空间，不强制均匀柔光和无投影审美；纸绢、水墨、透明淡彩、干湿笔触、汉诗题跋和印章。","influencedBy":"中国明清文人画和画谱、输入书画、汉诗文化与日本文人社交","influenced":"近代日本南画、日本画讨论和东亚文人画接受史","sources":[{"label":"The Met：The arts of the Edo period","url":"https://www.metmuseum.org/essays/the-arts-of-the-edo-period-1615-1868"},{"label":"Wikipedia：Nanga","url":"https://en.wikipedia.org/wiki/Nanga_(Japanese_painting)"}]},"kano-school":{"summary":"狩野派是从室町延续至江户末期、服务幕府和众多委托人的大型职业画家家系，内部跨越水墨、金碧屏障画、人物花鸟和不同地域支系。金地巨幅和强劲墨线是显著路线，但不能代表四百余年全部狩野绘画。","recognition":"大画面屏风、襖绘、卷轴或扇面按建筑和委托组织，可纪念性也可细密；强劲墨线、概括体块、精细鸟兽人物和装饰性色面随支系时期变化；水墨、金地、矿物蓝绿、朱红和纸绢本色均可，不固定黑金综合色；真实室内环境光与金箔反射或墨阶共同塑形，避免统一辉光；屏风纸、金箔、水墨、矿物综合色、木构接缝和可见笔触。","influencedBy":"中国宋元水墨、日本禅宗绘画、大和绘和武家宫廷委托制度","influenced":"桃山江户屏障画、各地职业画坛和日本近世绘画教育","sources":[{"label":"Britannica：Kano school","url":"https://www.britannica.com/art/Kano-school"},{"label":"Wikipedia：Kano school","url":"https://en.wikipedia.org/wiki/Kano_school"}]},"four-wangs-school":{"summary":"“四王”指王时敏、王鉴、王翚、王原祁四位山水画家，并非同一时段共同成立的正式画派。他们共享对董其昌所建正统谱系和古代笔墨的重视，但各自的构图、用笔和综合色并不相同，也不能把仿古误解为机械复制。","recognition":"古代山水结构被重新组合为严谨层次和卷轴节奏，四位画家的空间密度分别处理；皴法模块、书写轮廓和积墨形成受控笔墨系统，而不是复制同一古画表面；墨色、淡赭、灰绿、青绿和纸本暖白按画家与仿古对象改变；综合色和积墨层次建立空间，不添加现代景观摄影式光影；纸绢、水墨、层层皴染、淡彩、题跋和经核实的印章。","influencedBy":"董其昌和松江画派、元代文人山水、明清收藏鉴赏与摹古实践","influenced":"清代宫廷和正统山水教学、娄东虞山等地域传统及后世山水规范","sources":[{"label":"Britannica：Four Wangs","url":"https://www.britannica.com/art/Four-Wangs"},{"label":"Wikipedia：Four Wangs","url":"https://en.wikipedia.org/wiki/Four_Wangs"}]},"taohuawu-new-year-print":{"summary":"苏州桃花坞年画源于城市版刻环境，涵盖门画、戏曲故事、风俗、美人和城市图景，常见精细线版与多版套色，也曾吸收西洋透视和铜版图像。所谓雅致桃红嫩绿或较深建筑空间只代表部分作品。","recognition":"可采用门画对幅、故事分场、城市全景、室内人物或装饰边框，不统一为建筑深景；细密木刻线、精确或可见偏差的套色，以及部分作品中的透视缩短；桃红、黄、绿、蓝、墨黑和纸白范围随时期版次变化，不固定柔和综合色；平面印刷明度为主，透视作品可用有限明暗说明空间而非写实光效；多版木刻、印刷颜料、细纸纤维、版次叠印、套准差和真实磨损。","influencedBy":"苏州版画和出版、地方绘画、戏曲小说、城市消费文化及部分西洋图像交流","influenced":"江南年画、日本浮世绘研究中的交流讨论及现代苏州版画复兴","sources":[{"label":"China Daily：Taohuawu woodblock New Year prints","url":"https://www.chinadaily.com.cn/a/202301/19/WS63c8be37a31057c47ebaa477.html"},{"label":"Wikipedia：Taohuawu woodblock New Year pictures","url":"https://en.wikipedia.org/wiki/Taohuawu_woodblock_New_Year_pictures"}]},"tosa-school":{"summary":"土佐派是室町至江户时期与宫廷画所和大和绘传统密切相关的职业画家家系，并非从9世纪持续不变的统一画派。精细绘卷、古典文学和金云设色重要，但尺幅、题材和笔法随成员与委托而变。","recognition":"绘卷、册页、小屏风或扇面采用紧密分场和叙事节奏，金云只按作品需要使用；极细轮廓、程式化人物和精密衣纹建筑随题材调整；群青、朱红、石绿、金和高明度纸绢常见，也有较克制方案；综合色分区和金属反光建立层次，不以金色辉光覆盖全部表面；纸绢、矿物综合色、金箔、精细墨线、反复罩染和装裱接缝。","influencedBy":"大和绘、宫廷绘所、古典文学绘卷和中世职业画家制度","influenced":"江户宫廷绘画、住吉派、复古大和绘和近代日本画","sources":[{"label":"Britannica：Tosa school","url":"https://www.britannica.com/art/Tosa-school"},{"label":"Wikipedia：Tosa school","url":"https://en.wikipedia.org/wiki/Tosa_school"}]},"wei-jin-tomb-mural":{"summary":"魏晋南北朝墓葬图像分布广泛，包含壁画、画像砖和漆画等不同材料，并随河西、东北、江南和中原地区而变化。仪仗、宴饮、出行、孝子和神异题材常见，但横向推进、砖红灰绿或简化线描不能成为所有墓室的统一模板。","recognition":"按墓室结构采用分壁、长卷式推进、独立砖格或中心图像，不假定统一横向叙事；线描、平涂、画像砖模印和局部晕染依地区与载体变化；砖土、石灰底、墨、朱、赭及青绿残色依据考古记录，不用统一褪色滤镜；文物记录使用均匀光，侧光只用于显示真实墙面、砖缝和起伏；砖石或灰泥、矿物与有机综合色、模印刻线、烟尘、脱落和经记录的修复。","influencedBy":"汉代墓葬图像、地方丧葬制度、壁画和画像砖工艺，以及民族与区域文化交流","influenced":"隋唐墓室壁画、人物叙事和中国墓葬美术研究","sources":[{"label":"The Met：The Six Dynasties period","url":"https://www.metmuseum.org/essays/the-six-dynasties-period-220-589"},{"label":"Wikipedia：Chinese painting","url":"https://en.wikipedia.org/wiki/Chinese_painting"}]},"wu-school":{"summary":"吴门画派以明代苏州为中心，通常联系沈周、文徵明、唐寅、仇英等不同身份和实践；“文人画派”并不能完整容纳职业性很强的成员。古画重释、诗书画交游与苏州文化重要，但粗笔、细笔、青绿和人物等路线不可统一成淡墨山水。","recognition":"卷轴游观、册页小景、园林雅集或密集叙事按画家与题材选用；从沈周粗笔到文徵明细笔、仇英精工设色均可，不以单一皴法定派；水墨、淡赭、青绿和矿物重彩均存在，纸绢底色参与画面；墨色和综合色层建立空间，工笔人物与写意山水的明暗机制分别处理；纸绢、书写性水墨、精细勾染、矿物设色、题跋和可靠印章。","influencedBy":"元代文人画、苏州收藏与诗书画社交、院体和职业绘画传统","influenced":"晚明文人和职业绘画、松江画派及清代对明画的接受","sources":[{"label":"Britannica：Wu school","url":"https://www.britannica.com/art/Wu-school"},{"label":"Wikipedia：Wu School","url":"https://en.wikipedia.org/wiki/Wu_School"}]},"mono-ha":{"summary":"物派是对1968年前后日本艺术家以石、木、纸、玻璃、钢和空间关系展开实践的后设名称，成员没有统一宣言。材料常少加工，但选择、切割、支撑和场地配置仍是艺术行为，不能称作未经介入的自然物陈列。","recognition":"少量元素、重力关系与开放负空间；未经修饰的几何或自然材料原形；石木土金属本色与中性背景；自然展示光与接触阴影；石、木、玻璃、钢与现场接触关系。","influencedBy":"日本战后雕塑、极简与观念艺术、禅和现象学的当代解释，以及1968年前后社会语境","influenced":"日本装置与材料艺术、亚太战后艺术史及场地关系实践","sources":[{"label":"Tate：Mono-ha","url":"https://www.tate.org.uk/art/art-terms/m/mono-ha"},{"label":"Guggenheim：Mono-ha","url":"https://www.guggenheim.org/artwork/movement/mono-ha"}]},"shin-hanga":{"summary":"新版画由渡边庄三郎等版元推动，以绘师、雕师、摺师分工更新浮世绘版画，面向国内外市场并吸收写实光色。雨雪夜景和美人风景著名，却只是题材路线之一；其核心也不是所有作品都柔和怀旧。","recognition":"现代裁切、单一焦点、纵深风景或人物半身像按题材选择；精细主版线、多版渐层、空摺和写实细节由专业雕摺协作完成；综合色可柔和或鲜明，深蓝夜色、暖红和纸白并非固定配方；日光、夜光、雨雪和室内光通过版次渐层表达，而非数字柔光滤镜；精细木版、和纸、颜料、ぼかし渐层、空摺、云母和准确套印。","influencedBy":"浮世绘协作生产、明治新版技术、西方写实和国际版画市场","influenced":"20世纪日本木版画、旅游图像和国际对现代日本版画的收藏","sources":[{"label":"The Met：Shin hanga","url":"https://www.metmuseum.org/art/collection/search?q=shin%20hanga"},{"label":"Wikipedia：Shin-hanga","url":"https://en.wikipedia.org/wiki/Shin-hanga"}]},"eight-eccentrics-of-yangzhou":{"summary":"“扬州八怪”是对18世纪扬州一批以书画谋生、风格不循正统的画家的弹性称谓，名单不止一种，也不是恰好八人组成的宣言团体。金农、郑燮、李鱓等人的金石书写、兰竹花卉和泼写设色差异明显。","recognition":"偏心、满幅、册页或条幅布局按具体画家题材选择，不固定为一物加大片留白；金石线、兰竹笔、泼写花卉和夸张造型必须区分画家，不混成统一怪笔；墨黑、纸白、朱砂、花青、藤黄和淡彩均可，综合色不必克制到单色；墨色与设色层次塑形，书写速度和纸性比模拟自然投影更关键；纸本水墨、枯湿笔、泼写设色、金石题跋和真实印章。","influencedBy":"扬州商业与盐商赞助、金石学、文人花鸟和明清个性主义绘画","influenced":"海上画派、近现代写意花鸟、书画市场与金石审美","sources":[{"label":"Britannica：Eight Eccentrics of Yangzhou","url":"https://www.britannica.com/art/Eight-Eccentrics-of-Yangzhou"},{"label":"Wikipedia：Eight Eccentrics of Yangzhou","url":"https://en.wikipedia.org/wiki/Eight_Eccentrics_of_Yangzhou"}]},"yangliuqing-new-year-print":{"summary":"天津杨柳青年画以木版套印轮廓和色版后再手工开脸、晕染及局部描金著称，属于“半印半绘”的代表传统。工艺与题材随年代和作坊变化，丰满人物、中心对称和金粉不能成为所有杨柳青作品的必要条件。","recognition":"门神可成对中心组织，娃娃、仕女、故事和风俗画按题材采用群组或多场景；木版轮廓结合手工开脸、晕染和细部描绘，手绘程度依版次与作坊而变；朱红、粉、黄、绿、蓝及局部金色常见，但不设固定综合色配方；平面套印综合色与受控手绘明暗结合，不模拟油画式强投影；木版套印、手工施彩、颜料晕染、金粉或金泥和纸面压痕。","influencedBy":"天津地区雕版印刷、工笔人物画、城市市场和岁时民俗","influenced":"北方年画、清代民间人物图像和现代年画保护复兴","sources":[{"label":"Google Arts & Culture：Yangliuqing New Year Pictures","url":"https://artsandculture.google.com/entity/yangliuqing-new-year-pictures/m0b6g8q6"},{"label":"Wikipedia：Yangliuqing","url":"https://en.wikipedia.org/wiki/Yangliuqing"}]},"yuefenpai-calendar-art":{"summary":"月份牌是民国城市商业广告与历书结合的印刷品，以上海出版、品牌委托、照相参考和擦笔水彩式绘制建构现代女性、商品和家庭想象。时尚女性肖像很有识别度，但不应删除品牌、历法、多语文字、性别规训与殖民商业环境。","recognition":"中心肖像、商品、品牌报头、历表和装饰边框组成功能层级，不只保留人物；人物面部、时装、发型、家具与商品形体必须符合具体年代，避免统一娃娃脸；粉彩肤色、时装色、品牌专色、纸张暖色和套印色偏按实物使用；擦笔式影棚柔光、摄影参考高光与印刷平光结合，不添加现代美颜辉光；胶印或石印纸、擦笔水彩效果、印刷网点、套色误差与真实旧化。","influencedBy":"晚清画报与年画、照相摄影、商业石印与胶印、上海时尚、国际品牌和城市消费文化","influenced":"中国现代广告、包装、电影明星图像、时尚插画和后来民国复古视觉","sources":[{"label":"M+：Calendar posters","url":"https://www.mplus.org.hk/en/collection/"},{"label":"British Museum：Chinese advertising poster","url":"https://www.britishmuseum.org/collection/term/x112048"}]},"zhe-school":{"summary":"浙派是后世对明代职业画家网络的宽泛称呼，常以戴进为核心并承续南宋院体，但成员、地域和边界并不固定。强烈斧劈皴、对角构图和水墨对比是部分重要路线，不应把所有浙派作品都写成粗放戏剧山水。","recognition":"对角近景、紧凑山水、人物叙事或较平稳布局按作品选择，不设统一压迫构图；斧劈皴、浓淡突变和有力轮廓是重要手段，同时保留精细和较克制笔法；深墨、灰褐、淡赭、青绿或纸绢本色随题材和时期变化；浓墨与雾化远景可形成对比，但不把戏剧高反差设为全部浙派特征；纸绢、水墨、湿笔、干皴、淡彩及职业画家受控制作痕迹。","influencedBy":"南宋画院和马夏传统、元代职业绘画及明代宫廷和地方画家网络","influenced":"明代宫廷与职业山水、日本室町水墨和后来的浙派接受史","sources":[{"label":"Britannica：Zhe school","url":"https://www.britannica.com/art/Zhe-school"},{"label":"Wikipedia：Zhe School","url":"https://en.wikipedia.org/wiki/Zhe_School"}]},"arnhem-land-bark-painting":{"summary":"阿纳姆地树皮画来自澳大利亚北领地多个原住民族和语言群体，艺术家在桉树皮上以天然综合色表现祖先、土地、法律与公开或受限知识。交叉排线并非通用装饰纹；图像解释、氏族设计和复制权限必须由艺术家、社群与机构资料决定。","recognition":"树皮纵向、氏族设计、主体和边界按具体艺术家作品组织，不套用通用X光构图；交叉排线、轮廓、内部器官或几何氏族图形只在有公开依据时使用；赭石红黄、白土和炭黑来自地方综合色，也有地区和时代差异；均匀文物光显示天然综合色和树皮曲率，不添加神秘光效；桉树皮、天然赭石、白土、炭、植物胶、纤维刷和真实裂翘。","influencedBy":"阿纳姆地各原住民族的土地、祖先法律、仪式、岩画与树皮材料知识","influenced":"澳大利亚原住民当代艺术、土地权运动、博物馆实践和国际展览","sources":[{"label":"National Museum of Australia：Bark paintings","url":"https://www.nma.gov.au/collections/highlights/aboriginal-bark-paintings"},{"label":"National Gallery of Australia：Aboriginal and Torres Strait Islander art","url":"https://nga.gov.au/art-artists/aboriginal-torres-strait-islander-art/"}]},"ethiopian-icon-painting":{"summary":"埃塞俄比亚基督教绘画涵盖教堂壁画、木板圣像、十字架和写本插图，依埃塞俄比亚正统Tewahedo传统发展并吸收拜占庭、科普特、伊斯兰和欧洲图像。大眼正面人物是部分阶段特征，不能覆盖全部地区和世纪。","recognition":"三联圣像、壁画分区、写本页或连续叙事按礼仪和载体组织；正面圣像、侧面恶者、清楚轮廓和综合色体积随时期画家变化；红、黄、绿、蓝、黑白和金依颜料与年代，不固定国旗综合色；平面综合色与有限明暗保持礼仪可读性，金色仅有真实反光；木板、石膏底、羊皮纸、蛋彩、墨、金和使用磨损。","influencedBy":"埃塞俄比亚正统教会、阿克苏姆和中世纪本地传统、科普特拜占庭及跨红海交流","influenced":"埃塞俄比亚现代宗教绘画、离散社群和非洲基督教艺术研究","sources":[{"label":"The Met：Ethiopian art","url":"https://www.metmuseum.org/essays/ethiopian-art"},{"label":"British Museum：Ethiopia","url":"https://www.britishmuseum.org/collection/galleries/africa"}]},"australian-aboriginal-dot-painting":{"summary":"常称“澳大利亚原住民点画”的条目更准确地指1971年后Papunya及西部沙漠多个社群的丙烯画运动。点并非古老统一风格，也曾用于转换或遮蔽受限图像；艺术家、土地、Dreaming叙事和复制权限不可泛化。","recognition":"同心地点、路径、地貌和点场必须来自具体艺术家公开作品，不组成泛沙漠地图；点、圆、线和符号具有艺术家及社群语境，不作为可自由调用图标库；赭色、黑白和高纯度丙烯综合色均可，随社群、年代和艺术家变化；平面丙烯综合色与真实画布展场光，不添加沙漠发光或立体点珠效果；画布或板、丙烯、点绘工具、综合色层、底图和真实制作痕迹。","influencedBy":"西部沙漠地面和仪式图像、Papunya艺术家与学校项目、丙烯材料和社群艺术中心","influenced":"澳大利亚原住民当代艺术、土地权表达、国际当代绘画和社区艺术经济","sources":[{"label":"National Museum of Australia：Papunya painting","url":"https://www.nma.gov.au/defining-moments/resources/papunya-tula-art-movement"},{"label":"National Gallery of Australia：Papunya","url":"https://searchthecollection.nga.gov.au/search?keyword=Papunya"}]},"benin-court-art":{"summary":"贝宁宫廷艺术由今尼日利亚埃多王国的Oba宫廷、行会与仪式系统委托，涵盖铜合金铸件、象牙雕刻、木雕、铁器与珠饰。等级比例和正面国王形象重要，但不能概括全部对象；1897年英军惩罚性远征的掠夺、流散和返还讨论必须说明。","recognition":"宫殿浮雕牌、祭坛头像、象牙、王权器物或仪式群像按物件用途和原始位置组织；等级尺度、正面或侧向人物、高浮雕、珠饰网格与动植物符号须依对象区分；铜合金金棕、氧化绿、象牙色、铁黑和珊瑚珠红依真实材料与保存状态使用；柔和展示光或擦边光显示铸造与雕刻深度，不伪造神秘火光；失蜡法铜合金、象牙、木、铁、珊瑚珠、铸造芯痕、使用磨损与馆藏修复。","influencedBy":"埃多王权与宫廷仪式、专业铸造与雕刻行会、跨撒哈拉与大西洋贸易、周边地区交流","influenced":"埃多当代艺术与王宫传统、非洲艺术史、现代主义对非洲形式的挲用及全球博物馆返还讨论","sources":[{"label":"The Met：The Art of Benin","url":"https://www.metmuseum.org/essays/the-art-of-benin"},{"label":"British Museum：Benin Bronzes","url":"https://www.britishmuseum.org/about-us/british-museum-story/contested-objects-collection/benin-bronzes"}]},"ndebele-house-painting":{"summary":"南部恩德贝勒墙绘由女性在住宅外墙上发展，以建筑分区、几何综合色和不断更新的现代母题表达家户、身份与社会变化。它不是无时间的部落图案；商业综合色、殖民和种族隔离时期迁移、旅游市场都影响其现代形态。","recognition":"门窗、墙角、檐线和墙面板块决定几何分区，不把纹样脱离建筑悬浮；硬边折线、阶梯、三角和现代具象母题由手绘构成，保留个体差异；黑白边界配高纯度商业综合色或早期土色综合色，年代须区分；真实户外日光、墙体凹凸和檐下阴影，不做矢量无材质背景；泥灰墙、水泥、商业漆、手绘边缘、裂缝、粉化和重涂。","influencedBy":"南部恩德贝勒住宅与女性装饰实践、珠饰、迁移和南非殖民及种族隔离历史","influenced":"Esther Mahlangu等当代艺术、全球设计合作和南非文化身份表达","sources":[{"label":"South African History Online：Ndebele","url":"https://www.sahistory.org.za/article/ndebele"},{"label":"Wikipedia：Ndebele house painting","url":"https://en.wikipedia.org/wiki/Ndebele_house_painting"}]},"west-african-studio-portraiture":{"summary":"西非摄影棚肖像在独立前后城市摄影文化中发展，摄影师与顾客通过布景、服装、姿态和物件共同塑造现代身份。Seydou Keïta、Malick Sidibé等人的摄影棚、夜生活和技术不同，不能以统一黑白图案背景概括整个西非。","recognition":"全身、坐姿、双人或群像由顾客姿态、布景和道具共同组织；服装剪影、身体姿态、自行车收音机等物件须按摄影师与年代选择；黑白银盐为经典路线，也有综合色摄影；图案布景不等于主体服装；摄影棚漫射光、直接闪光或夜生活环境光按摄影师实践区分；银盐底片和相纸、布景织物、冲印综合色、划痕和档案标记。","influencedBy":"殖民和城市摄影、独立时代社会流动、时尚、音乐与顾客自我呈现","influenced":"非洲摄影史、时尚摄影、当代身份艺术和全球肖像实践","sources":[{"label":"The Met：West African photography","url":"https://www.metmuseum.org/essays/photography-in-west-africa"},{"label":"Tate：Seydou Keita","url":"https://www.tate.org.uk/art/artists/seydou-keita-2426"}]},"nok-art":{"summary":"Nok是考古学对尼日利亚中部一批铁器时代遗址与赤陶雕塑的命名，而非历史文献记载的单一王国或艺术家群体。空心人物、几何眼与穿孔常见，但大量对象脱离考古上下文并受非法盗掘影响，功能、宗教和与后世文化的直接连续性不得臆测。","recognition":"独立头像、躯干残片、群像或考古陈列必须显示残存尺度与来源，不虚构完整神庙；三角或D形眼、穿孔瞳孔、几何发式、空心造型与破损边缘按实物区分；赤陶红棕、橙褐、土黄、烟燏黑和出土附着色依物件状态使用；考古记录用均匀柔光，雕塑展示用克制擦边光显示粘土和残损；粗粒赤陶、手塑与盘条痕迹、烧成色差、土壤附着、断面与保护修复。","influencedBy":"尼日利亚中部新石器至铁器时代社会、陶器技术、冶铁与区域交流；具体艺术前史仍存争议","influenced":"西非古代艺术史研究、考古遗产保护和关于盗掘、来源与返还的国际讨论","sources":[{"label":"The Met：Nok Terracottas","url":"https://www.metmuseum.org/essays/nok-terracottas-500-b-c-200-a-d"},{"label":"Encyclopaedia Britannica：Nok culture","url":"https://www.britannica.com/topic/Nok-culture"}]},"tingatinga-painting":{"summary":"廷加廷加绘画得名于坦桑尼亚艺术家Edward Saidi Tingatinga，约1968年后在达累斯萨拉姆发展为作坊和市场网络。硬板瓷漆、动物和重复点饰常见，但后续艺术家扩展了城市、社会与幻想题材，不能当作无作者的泛非民俗画。","recognition":"单一或重复形体平铺、强轮廓与浅背景；圆润简化剪影、点状装饰与平滑硬边；高饱和红黄蓝绿、黑色轮廓与纯色底；均匀平面光，以色块关系塑形；硬质板面、工业瓷漆的光滑高饱和平涂。","influencedBy":"Edward Tingatinga的实践、达累斯萨拉姆城市与旅游市场、招牌画和东非大众图像","influenced":"坦桑尼亚与东非当代大众绘画、旅游艺术和个体艺术家工作室","sources":[{"label":"British Museum：Tingatinga painting","url":"https://www.britishmuseum.org/collection/term/x106748"},{"label":"Wikipedia：Tingatinga painting","url":"https://en.wikipedia.org/wiki/Tingatinga_(painting)"}]},"aboriginal-x-ray-art":{"summary":"‘X-ray art’是收藏与艺术史对澳大利亚北部部分岩画和树皮画中同时显示外轮廓、骨骼、器官或内部分区的描述性术语，并非一个全澳洲统一的原住民风格。图像的氏族、地点、物种、故事和观看权限必须由相关社群界定。","recognition":"单一物种、人物、狩猎关系或内部结构场按具体地区、作者与讲述权限组织；外轮廓与骨骼、器官、食物或内部分区并置；排线和形体必须依原作而非通用解剖；天然赭红、黄赭、白土、炭黑和树皮或岩面本色依地区材料使用；岩面记录采用现场散射光，树皮画采用均匀保护性展示光，不添加体积阴影；岩面、桉树皮、天然赭石、植物或人工固着剂、细笔排线与真实磨损。","influencedBy":"澳大利亚北部特定原住民社群的土地、亲属、物种知识、仪式与岩画和树皮画传统","influenced":"当代原住民树皮画与纸上作品、博物馆收藏史、土地权利和原住民知识权限讨论","sources":[{"label":"National Museum of Australia：Aboriginal bark paintings","url":"https://www.nma.gov.au/collections/highlights/aboriginal-bark-paintings"},{"label":"Australian Museum：Aboriginal art","url":"https://australian.museum/learn/cultures/atsi-collection/aboriginal-art/"}]},"akkadian-art":{"summary":"阿卡德时期艺术约形成于前2334至前2154年，在延续苏美尔材料和图像传统的同时强化君主中心、连续动作与纪念性。纳拉姆辛胜利碑的上升对角线很有代表性，但不宜把单件作品的构图概括成全部阿卡德艺术的固定公式。","recognition":"单一主轴结合上升对角线；有力体块、深刻线与浮雕转折；矿物土色、炭黑、石灰白与克制强调色；均匀正面光或擦边侧光，避免现代电影式光效；磨光石材、铜铸表面与清晰刻痕。","influencedBy":"苏美尔城邦艺术、圆筒印章传统与阿卡德帝国王权","influenced":"后续两河王权纪念像、胜利叙事与帝国视觉","sources":[{"label":"The Met：Mesopotamia, 8000–2000 B.C.","url":"https://www.metmuseum.org/toah/ht/02/wam.html"},{"label":"Wikipedia：Art of Mesopotamia","url":"https://en.wikipedia.org/wiki/Art_of_Mesopotamia"}]},"achaemenid-persian-art":{"summary":"阿契美尼德艺术约在前550至前330年的多民族帝国中形成。波斯波利斯的轴线、阶梯和朝贡队列最具代表性，但其建筑、石雕、金属器与釉砖也综合了伊朗、两河、埃及和希腊—爱奥尼亚工匠传统，不应被描述为孤立发展的单一路线。","recognition":"轴线对称、长列重复与阶梯层级；克制侧面造型、浅浮雕与精确轮廓；矿物土色、炭黑、石灰白与克制强调色；均匀正面光或擦边侧光，避免现代电影式光效；磨光石材、浅浮雕与釉砖细节。","influencedBy":"伊朗高原传统，以及米底、两河、埃及和希腊—爱奥尼亚工匠体系","influenced":"塞琉古、帕提亚与萨珊宫廷艺术中的帝国秩序和王权表达","sources":[{"label":"The Met：The Achaemenid Persian Empire","url":"https://www.metmuseum.org/toah/hd/acha/hd_acha.htm"},{"label":"Encyclopaedia Iranica：Art in Iran","url":"https://www.iranicaonline.org/articles/art-in-iran"}]},"ottonian-art":{"summary":"奥托艺术约在950至1050年的德意志王国与神圣罗马帝国宫廷、主教区和修道院中形成，涵盖手抄本、金工、象牙和大型雕塑。强调神圣等级、正面权威与表现性手势，但并非简单抛弃加洛林的古典遗产。","recognition":"严格中心轴、层叠等级区与宽阔金地；拉长比例、强调手势与平面化纪念体积；金、紫、深红、蓝、绿与羊皮纸白；均匀正面图像光强化金地亮度；羊皮纸蛋彩、金箔、珐琅、象牙与浮雕金属工艺。","influencedBy":"加洛林艺术、晚期古代和拜占庭宫廷图像，以及帝国与教会赞助","influenced":"萨利安时期与罗马式手抄本、金工、纪念雕塑和王权图像","sources":[{"label":"The Met：Ottonian Art","url":"https://www.metmuseum.org/essays/ottonian-art"},{"label":"Encyclopaedia Britannica：Ottonian art","url":"https://www.britannica.com/art/Ottonian-art"}]},"babylonian-art":{"summary":"巴比伦艺术横跨古巴比伦、加喜特及新巴比伦等相隔数百年的阶段，不能归结为单一视觉样式。本页的高饱和蓝色釉砖、模块化墙面和行列式节奏主要对应前626至前539年的新巴比伦宫殿与城门装饰；古巴比伦艺术还包括石碑、陶塑和圆筒印章。","recognition":"模块化墙面分区与带状重复；清楚外轮廓、低浮雕模块与规则节奏；钴蓝、青绿、赭黄、砖红与黑边；均匀正面光或擦边侧光，避免现代电影式光效；彩釉砖、烧结陶面与深色勾缝。","influencedBy":"苏美尔—阿卡德图像传统、两河书写文化及历代巴比伦王朝","influenced":"新巴比伦城市纪念艺术，并参与阿契美尼德宫廷视觉的区域交流","sources":[{"label":"The Met：Mesopotamia, 1000 B.C.–1 A.D.","url":"https://www.metmuseum.org/toah/ht/04/wam.html"},{"label":"Wikipedia：Art of Mesopotamia","url":"https://en.wikipedia.org/wiki/Art_of_Mesopotamia"}]},"northern-renaissance":{"summary":"北方文艺复兴是15至16世纪低地国家、德语区、法国等阿尔卑斯山以北艺术的广义标签，涵盖绘画、版画、雕塑与人文主义出版文化。精密油画只是重要路线之一，不能把整个北方文艺复兴等同于尼德兰早期木板画。","recognition":"因地域与媒介而异，常见稳定空间、层叠景深与多个细节焦点；精确轮廓、具体表面差异、自然比例或有意表现性变形；深红、综合色绿、群青、土色与细腻冷暖肤色；可追踪自然光、精细反射与透明阴影；油画木板、版画线刻、雕塑和精细织物等多媒介表面。","influencedBy":"晚期哥特与尼德兰早期绘画、地方工艺、人文主义、印刷传播和跨阿尔卑斯交流","influenced":"16世纪欧洲绘画与版画、宗教改革视觉、肖像和风俗图像传统","sources":[{"label":"Encyclopaedia Britannica：Northern Renaissance","url":"https://www.britannica.com/art/Renaissance-art/Northern-Renaissance-art"},{"label":"Wikipedia：Northern Renaissance","url":"https://en.wikipedia.org/wiki/Northern_Renaissance"}]},"international-gothic":{"summary":"国际哥特约在1375至1425年的欧洲宫廷和城市网络中传播，以优雅曲线、修长人物、豪华材质和精密自然细节形成跨地域共同语汇。它仍包含显著地方差异，也不只存在于手抄本，还见于木板画、壁画、雕塑和金工。","recognition":"浅层舞台空间、流动S形动线与精密装饰框架；修长比例、柔和连续曲线与尖细轮廓；群青、朱红、玫瑰红、绿、金与羊皮纸白；均匀宫廷图像光伴随细小金饰高光和有限投影；羊皮纸蛋彩、木板画、金箔与精密织纹表面。","influencedBy":"法国哥特宫廷艺术、意大利绘画、波希米亚与低地国家工坊，以及跨宫廷艺术家流动","influenced":"尼德兰早期绘画、晚期哥特宫廷艺术与部分意大利文艺复兴画家","sources":[{"label":"The Met：The International Gothic Style","url":"https://www.metmuseum.org/toah/hd/inte/hd_inte.htm"},{"label":"Wikipedia：International Gothic","url":"https://en.wikipedia.org/wiki/International_Gothic"}]},"carolingian-art":{"summary":"加洛林艺术约在780至900年的法兰克宫廷和修道院网络中发展，通过古典与晚期古代范本、基督教礼仪和地方工艺推动建筑、手抄本、象牙雕刻与金工复兴。古典体积和快速线描常见于特定抄本流派，不是全部作品的统一形式。","recognition":"手抄本常用层级页框、中心图像区与清楚装饰边界；复兴的古典体积、快速轮廓与精密首字构造；羊皮纸白、紫、红、绿、蓝与克制金色；均匀手抄本图像光伴随小面积金属反光；羊皮纸、蛋彩、金箔、象牙雕刻与金属工艺。","influencedBy":"晚期古代与早期基督教范本、拜占庭和不列颠—爱尔兰手抄本传统、法兰克宫廷改革","influenced":"奥托艺术、西欧中世纪手抄本、修道院建筑与礼仪器物","sources":[{"label":"Smarthistory：Carolingian art, an introduction","url":"https://smarthistory.org/carolingian-art-an-introduction/"},{"label":"Wikipedia：Carolingian art","url":"https://en.wikipedia.org/wiki/Carolingian_art"}]},"coptic-art":{"summary":"科普特艺术是埃及基督教社群约3至12世纪的多媒介传统，包括纺织、石雕、壁画、手抄本与木器。正面人物、强调轮廓和几何边饰常见，但把整套传统归结为粗线、平面体积或织物风格会忽略时期与媒介差异。","recognition":"正面中心、近对称组织与清楚边饰结构；强轮廓、概括体积与因媒介而异的几何化形体；本色亚麻、羊毛红、深蓝、赭黄、黑与乳白；均匀图像光，以有限塑形或织纹色差建立层次；亚麻羊毛织物、蛋彩木板、壁画、石雕与可见织纹。","influencedBy":"晚期埃及、希腊罗马和早期基督教传统，以及地中海东部的工艺交流","influenced":"埃及修道院艺术、科普特手抄本与礼仪器物，并与早期伊斯兰埃及的工艺持续交流","sources":[{"label":"Encyclopaedia Britannica：Coptic art","url":"https://www.britannica.com/art/Coptic-art"},{"label":"Wikipedia：Coptic art","url":"https://en.wikipedia.org/wiki/Coptic_art"}]},"roman-imperial-art":{"summary":"本页以从前27年至约4世纪的罗马帝国艺术为核心，涵盖纪念建筑、肖像、历史浮雕、壁画、马赛克和奢侈工艺。宏大轴线与连续叙事主要适用于公共纪念工程，不能替代私人住宅、行省艺术和晚期古代多样面貌。","recognition":"宏大轴线、连续叙事带与深层空间；理想化比例、坚实体块与深浅浮雕；矿物土色、炭黑、石灰白与克制强调色；均匀正面光或擦边侧光，避免现代电影式光效；抛光大理石、铸铜、马赛克与彩绘灰泥。","influencedBy":"罗马共和国、希腊化艺术、伊特鲁里亚传统及各行省视觉文化","influenced":"晚期古代、拜占庭和欧洲后世的古典复兴传统","sources":[{"label":"The Met：Roman Art","url":"https://www.metmuseum.org/toah/hd/roar/hd_roar.htm"},{"label":"The Met：Roman Portrait Sculpture: The Stylistic Cycle","url":"https://www.metmuseum.org/toah/hd/ropo/hd_ropo.htm"}]},"roman-republican-art":{"summary":"罗马共和国艺术的可辨材料主要集中于前3世纪至前27年，并综合伊特鲁里亚、意大利本土和希腊化传统。维里主义尤见于晚期共和国精英肖像，不宜用它概括共和国数百年间的建筑、神庙装饰、壁画和全部雕塑。","recognition":"稳定正面或三分之四视点与清楚中心；具体表面转折、坚实比例与清晰轮廓；矿物土色、炭黑、石灰白与克制强调色；方向明确的自然侧光；大理石、青铜、灰泥与湿壁画。","influencedBy":"伊特鲁里亚与意大利本土传统、希腊及希腊化艺术","influenced":"罗马帝国肖像、纪念建筑和公共叙事","sources":[{"label":"The Met：Roman Art","url":"https://www.metmuseum.org/toah/hd/roar/hd_roar.htm"},{"label":"The Met：Roman Portrait Sculpture: The Stylistic Cycle","url":"https://www.metmuseum.org/toah/hd/ropo/hd_ropo.htm"}]},"romanesque-art":{"summary":"罗马式艺术是约1000至1150年西欧多地区建筑、石雕、壁画、手抄本和金工的广义标签。半圆拱和厚重墙体主要属于建筑，等级比例、强轮廓和程式化褶线则常见于具象图像；两者不能互相代替。","recognition":"建筑可用半圆框景，图像常用横向分栏与等级比例；厚重轮廓、拉长几何体积与程式化衣褶线；石材白、赭黄、深红、蓝绿、黑与克制金色；正面均匀图像光，或以擦边光显示建筑浮雕；石雕、壁画、羊皮纸蛋彩、木雕与金工。","influencedBy":"晚期古代、加洛林与奥托艺术、拜占庭交流，以及修道院改革和朝圣网络","influenced":"哥特建筑与雕塑，并延续于西欧手抄本、壁画和教堂装饰","sources":[{"label":"The Met：Romanesque Art","url":"https://www.metmuseum.org/toah/hd/rmsq/hd_rmsq.htm"},{"label":"Encyclopaedia Britannica：Romanesque art","url":"https://www.britannica.com/art/Romanesque-art"}]},"mycenaean-art":{"summary":"迈锡尼艺术约形成于前1600至前1100年的希腊大陆，涵盖城堡建筑、墓葬金工、陶器与宫殿壁画。厚重城墙和礼仪金器体现部分重要面貌，但“防御性”不是所有器物的形式属性；其图像与技术同时承接并改造了米诺斯传统。","recognition":"中心轴、环形边带与紧凑对称；厚重剪影、螺旋波带与直接轮廓；暗金、青铜、赤陶红、黑与石灰白；均匀正面光或擦边侧光，避免现代电影式光效；锤揲金片、青铜、巨石与陶面线绘。","influencedBy":"希腊大陆中青铜时代传统与米诺斯克里特的宫殿、壁画和工艺交流","influenced":"后宫殿期爱琴视觉，并为后世希腊人保存关于青铜时代的物质记忆","sources":[{"label":"The Met：Minoan Crete","url":"https://www.metmuseum.org/toah/hd/mnoc/hd_mnoc.htm"},{"label":"The Met：Mycenaean Civilization","url":"https://www.metmuseum.org/toah/hd/myce/hd_myce.htm"}]},"minoan-art":{"summary":"米诺斯艺术主要指约前2000至前1450年克里特宫殿文化中的建筑、彩绘灰泥、陶器、印章和金属工艺。流动曲线、开放场域与综合色轮廓在宫殿壁画中突出，但不应被推广为全部米诺斯媒介的统一形式。","recognition":"开放场域、环绕曲线与非对称节奏；弹性轮廓、收放曲线与轻盈动态；赤陶红、埃及蓝、黑、白与暖黄；均匀壁画光，体积服从轮廓与色块节奏；彩绘灰泥、湿壁画与干壁画并用、细线陶绘和抛光表面。","influencedBy":"克里特新石器与早期青铜时代传统，以及埃及和近东的海上交流","influenced":"迈锡尼宫殿艺术，并进入后世对爱琴青铜时代的现代想象","sources":[{"label":"The Met：Minoan Crete","url":"https://www.metmuseum.org/toah/hd/mnoc/hd_mnoc.htm"},{"label":"The Met：Mycenaean Civilization","url":"https://www.metmuseum.org/toah/hd/myce/hd_myce.htm"}]},"early-netherlandish-painting":{"summary":"尼德兰早期绘画特指约1420至1550年低地国家的木板画传统，以油性媒介的透明层、精密材质、连续空间和细致自然光著称。油画并非由凡·艾克“发明”，而是被这一代工坊显著扩展和完善。","recognition":"封闭室内或紧凑祭坛空间、稳定轴线与连续前后景；极细轮廓、微型材质细节、调子体积与精确反射；宝石红蓝、深绿、综合色肤色、金与冷灰；单向窗光、透明有色阴影与可追踪镜面反射；细木板底、多层油性透明层、抛光颜料与极少可见笔触。","influencedBy":"国际哥特、低地国家手抄本与雕塑传统、宗教赞助及既有油性绘画技术","influenced":"北方文艺复兴绘画，并通过作品与艺术家流动影响意大利、西班牙和德语区","sources":[{"label":"The Met：Low Countries, 1400–1600 A.D.","url":"https://www.metmuseum.org/toah/ht/08/euwl.html"},{"label":"Wikipedia：Early Netherlandish painting","url":"https://en.wikipedia.org/wiki/Early_Netherlandish_painting"}]},"parthian-art":{"summary":"帕提亚时期艺术约从前247年至公元224年横跨伊朗与西亚，包含希腊化、伊朗和地方传统的多中心实践。正面性在哈特拉、杜拉欧罗普斯等地尤为突出，是重要但并非普遍适用于所有媒介与地区的识别线索。","recognition":"正面中心、近似对称与浅层空间；正面性、硬边轮廓与较少透视缩短；矿物土色、炭黑、石灰白与克制强调色；均匀正面光或擦边侧光，避免现代电影式光效；石材、灰泥、陶土或金属的哑光手工表面。","influencedBy":"阿契美尼德遗产、希腊化艺术与伊朗—美索不达米亚地方传统","influenced":"萨珊王权图像，以及西亚晚期古代的正面式构图","sources":[{"label":"The Met：The Achaemenid Persian Empire","url":"https://www.metmuseum.org/toah/hd/acha/hd_acha.htm"},{"label":"Encyclopaedia Iranica：Art in Iran","url":"https://www.iranicaonline.org/articles/art-in-iran"}]},"pompeian-second-style":{"summary":"庞贝第二风格约流行于前80至前20年，以透视建筑、虚构开口和远景打破实体墙面的封闭感。它是奥古斯特·毛提出的罗马壁画分类之一，年代与特征会因遗址和学者而略有差异，不应被当作同期全部罗马绘画。","recognition":"中心透视、虚构开口与坚实的前景建筑框架；细密建筑线、透视缩短平面与厚重框景构件；朱红、深黑、赭黄、蓝绿与石材白；绘制的幻觉光线与透视开口保持一致；平滑湿壁画、仿石材与精确建筑线描。","influencedBy":"庞贝第一风格的墙面分区，以及希腊化舞台、宫殿和住宅的建筑幻景","influenced":"庞贝第三风格对墙面与幻景关系的反向调整，并为第四风格保留透视片段","sources":[{"label":"The Met：Roman Painting","url":"https://www.metmuseum.org/toah/hd/ropt/hd_ropt.htm"},{"label":"Wikipedia：Pompeian Styles","url":"https://en.wikipedia.org/wiki/Pompeian_Styles"}]},"pompeian-third-style":{"summary":"庞贝第三风格约流行于前20年至公元50年，重新强调墙面的平整性：单色面板、纤细烛台式建筑、对称轴和小型中心画取代第二风格的大尺度纵深。其装饰仍可包含幻想性建筑，不能简单称为完全拒绝空间。","recognition":"大面积单色面板、纤细轴线与极小的悬浮中心画；极细线性框架、轻巧对称与近乎失重的小型形体；朱红、黑、白、赭黄与克制蓝绿；平面化室内图像光保持墙面连续性；平滑湿壁画、哑光色域与极细彩绘线。","influencedBy":"庞贝第二风格，以及奥古斯都时期偏好纤细、平面化和精致装饰的室内审美","influenced":"庞贝第四风格对平面面板、中心画与建筑幻景的综合","sources":[{"label":"The Met：Roman Painting","url":"https://www.metmuseum.org/toah/hd/ropt/hd_ropt.htm"},{"label":"Wikipedia：Pompeian Styles","url":"https://en.wikipedia.org/wiki/Pompeian_Styles"}]},"pompeian-fourth-style":{"summary":"庞贝第四风格约从公元50年延续至79年维苏威火山喷发，以多层框架、透视片段、中心神话画和繁密装饰综合前几种语言。所谓“综合”不等于无规则堆叠，其上下分区、轴线与框景仍有明确组织。","recognition":"多重嵌套框架、上下分区与片段化幻觉纵深；厚薄结构对比、透视片段与密集装饰节点；朱红、黑、金黄、蓝绿与石材白；平面光与幻觉光在多层框景中协调并置；湿壁画、塑形灰泥、仿石材与精细装饰线描。","influencedBy":"庞贝第二风格的透视幻景与第三风格的单色面板、纤细框架和中心画","influenced":"公元1世纪后期罗马室内装饰中的复杂框景、神话画和幻想建筑","sources":[{"label":"The Met：Roman Painting","url":"https://www.metmuseum.org/toah/hd/ropt/hd_ropt.htm"},{"label":"Wikipedia：Pompeian Styles","url":"https://en.wikipedia.org/wiki/Pompeian_Styles"}]},"pompeian-first-style":{"summary":"庞贝第一风格（又称砌筑风格）约流行于前200至前80年的坎帕尼亚室内墙饰，以彩绘和凸起灰泥模拟彩色石材砌块。它属于罗马壁画的现代分类体系，不能代表同期全部罗马绘画。","recognition":"仿石矩形墙面分区与粗细水平带；凸起灰泥板、清楚接缝与石材式几何；深红、赭黄、黑、绿与仿大理石杂色；均匀正面光或擦边侧光，避免现代电影式光效；彩绘灰泥、仿石纹与浅浮雕板块。","influencedBy":"希腊化宫殿和住宅的石材墙面装饰传统","influenced":"庞贝第二风格对墙体和空间幻觉的进一步改造","sources":[{"label":"The Met：Roman Painting","url":"https://www.metmuseum.org/toah/hd/ropt/hd_ropt.htm"},{"label":"Wikipedia：Pompeian Styles","url":"https://en.wikipedia.org/wiki/Pompeian_Styles"}]},"sasanian-art":{"summary":"萨珊艺术形成于224至651年的伊朗帝国，以岩壁浮雕、金银器、灰泥装饰和纺织纹样塑造王权视觉。圆形徽章与成对重复常见于银器和织物，但并非建筑、雕刻等全部媒介的统一构图。","recognition":"中心轴或圆形徽章与成对重复；饱满体块、连续弧线与纹章式轮廓；银白、暗金、深红、钴蓝与墨绿；均匀正面光或擦边侧光，避免现代电影式光效；银器锤揲、鎏金与岩壁浮雕。","influencedBy":"阿契美尼德王权记忆、帕提亚艺术与罗马—西亚跨区域交流","influenced":"伊斯兰早期宫廷艺术、中亚与欧亚纺织装饰、拜占庭和东亚输入纹样","sources":[{"label":"The Met：The Achaemenid Persian Empire","url":"https://www.metmuseum.org/toah/hd/acha/hd_acha.htm"},{"label":"Encyclopaedia Iranica：Art in Iran","url":"https://www.iranicaonline.org/articles/art-in-iran"}]},"sumerian-art":{"summary":"苏美尔艺术是约前3500至前2000年南部美索不达米亚多个城邦的视觉传统总称。神庙建筑、礼仪器物、圆筒印章与奉献像常以分层叙事、等级比例和复合视点组织图像；镶嵌只是其中一种重要媒介，并非全部苏美尔艺术的共同材料。","recognition":"横向分层、基线秩序与等级比例；正侧复合视点、紧凑轮廓与几何体块；石灰白、沥青黑、赭红与青金石蓝；均匀正面光或擦边侧光，避免现代电影式光效；石灰岩、雪花石膏与镶嵌颗粒。","influencedBy":"乌拜德与乌鲁克时期的城市化、神庙制度、书写及跨区域材料贸易","influenced":"阿卡德王权图像、两河流域的叙事浮雕与印章传统","sources":[{"label":"The Met：Mesopotamia, 8000–2000 B.C.","url":"https://www.metmuseum.org/toah/ht/02/wam.html"},{"label":"Wikipedia：Art of Mesopotamia","url":"https://en.wikipedia.org/wiki/Art_of_Mesopotamia"}]},"venetian-school":{"summary":"威尼斯画派是对文艺复兴时期威尼斯及其领地画家传统的宽泛称呼，综合色、油画层染、光与空气感重要，但贝利尼、乔尔乔内、提香、丁托列托和委罗内塞的构图与笔触差异显著。它也涵盖祭坛画、肖像、神话和公共装饰。","recognition":"宽阔三角或对角组织与色光连接；柔边体块、综合色面与少量轮廓线；暖金、深红、群青、橄榄绿与粉灰；温暖漫射光、空气透视与柔和反射；多层油画罩染与柔润表面。","influencedBy":"拜占庭和威尼斯综合色传统、尼德兰油画技术、文艺复兴人文主义、海上贸易与共和国委托","influenced":"欧洲巴洛克综合色与油画、鲁本斯、委拉斯开兹及后续综合色主义绘画","sources":[{"label":"The Met：Art in Renaissance Venice","url":"https://www.metmuseum.org/essays/art-in-renaissance-venice"},{"label":"National Gallery：Venetian Renaissance","url":"https://www.nationalgallery.org.uk/paintings/learn-about-art/venetian-renaissance"}]},"spanish-golden-age-painting":{"summary":"西班牙黄金时代绘画涵盖马德里宫廷、塞维利亚与其他地区的宗教画、肖像、静物和风俗题材，Velazquez、Zurbaran、Murillo等人的光线、色彩和委托差异显著。深色背景和强侧光不能覆盖该时期，帝国、天主教改革与殖民财富也需说明。","recognition":"单一焦点、深色大背景与稳定结构；具体比例、坚实轮廓与克制笔触；矿物土色、炭黑、石灰白与克制强调色；强定向侧光穿出深暗空间；吸光油层、粗织画布与局部厚涂。","influencedBy":"意大利文艺复兴与Caravaggism、尼德兰油画、天主教改革、哈布斯堡宫廷与西班牙帝国经济","influenced":"欧洲宫廷肖像、宗教绘画、现代现实主义、Manet及后续对Velazquez的重评","sources":[{"label":"The Met：Heilbrunn Timeline of Art History","url":"https://www.metmuseum.org/toah/"},{"label":"National Gallery：Art history","url":"https://www.nationalgallery.org.uk/paintings/learn-about-art"}]},"greek-orientalizing-style":{"summary":"希腊东方化时期约在前700至前600年通过贸易、迁徙和工匠交流吸收近东与埃及母题。连续饰带、莲花、棕榈叶和综合色动物在陶器与金工中常见；“东方化”是现代艺术史术语，不表示对某个单一“东方”风格的被动复制。","recognition":"连续饰带、中心徽章与疏密填充；卷曲轮廓、莲瓣式几何与刻线；陶土红、黑、乳白与暗紫红；均匀正面光或擦边侧光，避免现代电影式光效；陶土、黑釉、附加彩与刻划细节。","influencedBy":"希腊几何传统，以及腓尼基、北叙利亚、亚述和埃及的贸易与工艺交流","influenced":"希腊古风时期的陶器、雕塑和装饰词汇","sources":[{"label":"The Met：Geometric Art in Ancient Greece","url":"https://www.metmuseum.org/toah/hd/grge/hd_grge.htm"},{"label":"The Met：The Art of the Archaic Period","url":"https://www.metmuseum.org/toah/hd/argk/hd_argk.htm"}]},"archaic-greek-art":{"summary":"希腊古风艺术约从前700延续至前480年，涵盖石雕、神庙、陶绘与奉献物。正面性、程式化轮廓和逐步增强的自然观察并存；将整个时期概括为“尚未自然平衡”会掩盖晚期古风对动作、解剖和空间的持续探索。","recognition":"正面中心、稳定轴线与对称平衡；几何化比例、连续轮廓与模式化转折；矿物土色、炭黑、石灰白与克制强调色；均匀正面光或擦边侧光，避免现代电影式光效；哑光石材、陶绘黑釉与克制彩绘。","influencedBy":"几何与东方化时期传统，以及埃及和近东雕塑、建筑知识","influenced":"古希腊古典艺术的比例、建筑柱式和具象表现","sources":[{"label":"The Met：Geometric Art in Ancient Greece","url":"https://www.metmuseum.org/toah/hd/grge/hd_grge.htm"},{"label":"The Met：The Art of the Archaic Period","url":"https://www.metmuseum.org/toah/hd/argk/hd_argk.htm"}]},"hellenistic-art":{"summary":"希腊化艺术约从前323延续至前31年，产生于跨越地中海与西亚的多王国环境。强情感、旋转动势、对角线和深层空间是重要方向，但同时存在古典化、私密化和地域混合等多种路线，不能以戏剧性概括全部作品。","recognition":"对角线、旋转动势与深浅交错；扭转体块、深褶线与强透视缩短；矿物土色、炭黑、石灰白与克制强调色；强侧光形成深阴影与明亮边缘；高低浮雕、大理石凿痕与青铜表面。","influencedBy":"古希腊古典艺术、亚历山大帝国扩张及埃及和西亚地方传统","influenced":"罗马共和国与帝国艺术，并长期影响欧洲古典传统","sources":[{"label":"The Met：The Art of Classical Greece","url":"https://www.metmuseum.org/toah/hd/tacg/hd_tacg.htm"},{"label":"The Met：The Art of the Hellenistic Age","url":"https://www.metmuseum.org/toah/hd/haht/hd_haht.htm"}]},"greek-geometric-style":{"summary":"希腊几何风格约在前900至前700年的陶器装饰中成熟，以水平分带、回纹、三角和轮廓化图形形成密集节律。该名称首先是陶器史分期，不应直接套用于同时期全部建筑、雕塑和工艺。","recognition":"严格横向分带、环形连续与满幅节奏；折线、回纹、三角与概括黑色剪影；陶土红、炭黑与少量米白；均匀正面光或擦边侧光，避免现代电影式光效；哑光陶土、黑釉与细密手绘线。","influencedBy":"希腊原几何陶器、爱琴后青铜时代遗产与区域陶工传统","influenced":"希腊东方化陶器和古风时期的图像叙事","sources":[{"label":"The Met：Geometric Art in Ancient Greece","url":"https://www.metmuseum.org/toah/hd/grge/hd_grge.htm"},{"label":"The Met：The Art of the Archaic Period","url":"https://www.metmuseum.org/toah/hd/argk/hd_argk.htm"}]},"sienese-school":{"summary":"锡耶纳画派在13世纪后期至15世纪发展，杜乔、洛伦采蒂兄弟、马尔蒂尼等人将拜占庭传统、哥特线性、金地和城市叙事结合。修长曲线和金箔重要，但空间、情感和世俗题材逐渐变化，不能统一为无透视圣像。","recognition":"浅层叠置、中心轴与节奏化群组；修长比例、连续曲线与图案化褶线；矿物土色、炭黑、石灰白与克制强调色；均匀正面光或擦边侧光，避免现代电影式光效；木板蛋彩、金箔压纹与精刻线。","influencedBy":"拜占庭绘画、托斯卡纳板画、哥特艺术、方济各会文化和锡耶纳城市委托","influenced":"国际哥特、意大利早期文艺复兴和欧洲金地板画传统","sources":[{"label":"The Met：Sienese Painting","url":"https://www.metmuseum.org/essays/sienese-painting"},{"label":"National Gallery：Sienese school","url":"https://www.nationalgallery.org.uk/artists/sienese"}]},"assyrian-art":{"summary":"本页所称“亚述艺术”主要指前911至前609年的新亚述宫廷艺术。宫殿正壁石板以连续战争、狩猎和仪式叙事著称，常见平行基线、侧面轮廓与密集刻线；这一限定不能替代更早的古亚述、中亚述艺术。","recognition":"连续长幅叙事、平行基线与横向推进；侧面轮廓、浅浮雕与精密刻线；矿物土色、炭黑、石灰白与克制强调色；均匀正面光或擦边侧光，避免现代电影式光效；石灰石板、细密凿刻与哑光石面。","influencedBy":"两河北部传统、巴比伦图像与新亚述帝国宫廷制度","influenced":"阿契美尼德宫廷浮雕、后世帝国纪念叙事与考古复兴视觉","sources":[{"label":"The Met：Mesopotamia, 1000 B.C.–1 A.D.","url":"https://www.metmuseum.org/toah/ht/04/wam.html"},{"label":"Wikipedia：Art of Mesopotamia","url":"https://en.wikipedia.org/wiki/Art_of_Mesopotamia"}]},"etruscan-art":{"summary":"伊特鲁里亚艺术是约前8至前3世纪意大利中部多个城邦的视觉传统，涵盖墓室壁画、陶塑、青铜器、金工与神庙装饰。宴饮、舞蹈和葬仪场景在墓画中突出，但不能以墓画的平面轮廓概括全部伊特鲁里亚媒介。","recognition":"墓画常用横向场景、稳定基线与活跃的不对称群组；强侧面轮廓、概括体积与直接而有节奏的动作；赤陶红、赭黄、黑、白与低饱和蓝绿；墓室壁画采用均匀图像光，较少自然投影；彩绘灰泥、陶塑、錾刻青铜、金工与颗粒状土质颜料。","influencedBy":"意大利维拉诺瓦传统，以及希腊、腓尼基和地中海贸易中的图像与工艺交流","influenced":"罗马共和国早期的神庙、宗教图像、陶塑和部分葬仪传统","sources":[{"label":"The Met：Italian Peninsula, 1000 B.C.–1 A.D.","url":"https://www.metmuseum.org/toah/ht/04/eust.html"},{"label":"Wikipedia：Etruscan art","url":"https://en.wikipedia.org/wiki/Etruscan_art"}]},"italian-proto-renaissance":{"summary":"“意大利原始文艺复兴”是现代艺术史对约1250至1400年部分意大利艺术转向的概括，并非当时统一自称的运动。乔托、杜乔等人的实践在拜占庭与哥特传统中增强体积、浅层空间和情感叙事，但不同城市和艺术家的路径并不一致。","recognition":"稳定中心、浅层建筑空间与清楚叙事层级；较坚实体积、柔化衣褶线与连续轮廓；群青、朱红、土色、金与暖灰泥白；均匀图像光中出现早期方向塑形和克制投影；湿壁画、木板蛋彩、金箔与冲压金地。","influencedBy":"拜占庭圣像与意大利拜占庭式传统、哥特艺术、古典遗存和托钵修会赞助","influenced":"15世纪意大利文艺复兴对自然观察、叙事空间和纪念性人物的探索","sources":[{"label":"Encyclopaedia Britannica：Western painting, Proto-Renaissance","url":"https://www.britannica.com/art/Western-painting/Proto-Renaissance-in-Italy-1280-1400"},{"label":"Wikipedia：Proto-Renaissance","url":"https://en.wikipedia.org/wiki/Proto-Renaissance"}]},"indus-valley-art":{"summary":"印度河文明视觉文化的成熟期约为前2600至前1900年，遗存包括皂石印章、陶器、金属与小型雕塑。方形印章和短符号列辨识度很高，但只代表遗存的一部分；印度河文字尚未释读，不应为装饰目的杜撰或解释其含义。","recognition":"小尺度方形框、中心图形与信息带；简练侧面轮廓、凹刻线与紧密比例；矿物土色、炭黑、石灰白与克制强调色；均匀正面光或擦边侧光，避免现代电影式光效；烧制皂石、陶土、铜与印压颗粒。","influencedBy":"南亚西北部早期农业聚落、城市工艺网络及与伊朗高原和两河的贸易","influenced":"其后续影响缺乏可直接证明的连续谱系，应与后期南亚艺术分开论证","sources":[{"label":"Encyclopaedia Britannica：Indus civilization","url":"https://www.britannica.com/topic/Indus-civilization"},{"label":"Wikipedia：Indus Valley Civilisation","url":"https://en.wikipedia.org/wiki/Indus_Valley_Civilisation"}]},"early-christian-art":{"summary":"早期基督教艺术约在2至6世纪的晚期罗马世界中形成，借用并改造罗马墓葬、住宅、帝国和犹太视觉传统，用于地下墓室、石棺、教堂、马赛克与小型器物。正面性和简化体积是部分晚期作品的趋势，并非从一开始就取代古典自然主义。","recognition":"中心式或横向叙事、等级比例与清楚分区；古典体积与晚期正面化、概括轮廓并存；斑岩红、金、深蓝、绿与浅色灰泥；均匀正面图像光，可保留晚期罗马式柔和塑形；湿壁画、石棺浮雕、玻璃马赛克、手抄本颜料与灰泥。","influencedBy":"晚期罗马艺术、犹太图像传统、古典叙事方式与新形成的基督教礼仪","influenced":"拜占庭、科普特及西欧中世纪基督教建筑与图像传统","sources":[{"label":"Encyclopaedia Britannica：Early Christian art","url":"https://www.britannica.com/art/Early-Christian-art"},{"label":"Wikipedia：Early Christian art and architecture","url":"https://en.wikipedia.org/wiki/Early_Christian_art_and_architecture"}]},"amsterdam-school":{"summary":"阿姆斯特丹学派是20世纪初荷兰建筑表现主义的重要网络，尤与阿姆斯特丹公共住宅、城市街区、室内和家具设计相关。表现性砖砌、雕塑化转角和整合工艺常见，但曲面、塔冠和深红砖不能成为每位建筑师或每栋建筑的固定公式。","recognition":"按街区、转角、入口和公共住宅单元组织连续立面，不强制每栋建筑都作波浪轮廓；砖墙、门窗、屋顶和雕塑细部可形成表现性整体，同时保持真实结构与使用尺度；砖、瓦、木、石和金属本色为主，综合色随项目与保存状态变化；真实城市日光显示砖缝、开口深度和体量转折，不添加舞台式内部辉光；手工或机制砖、砂浆、木石雕饰、陶瓦、金属构件及真实风化。","influencedBy":"荷兰传统砖建筑、H. P. Berlage的理性砖作、工艺美术思想、城市住房改革与表现主义","influenced":"荷兰公共住宅、装饰性现代建筑、室内与家具设计，以及后世对砖砌表现主义的保护研究","sources":[{"label":"Museum Het Schip：Amsterdam School","url":"https://www.hetschip.nl/en/amsterdam-school"},{"label":"Wikipedia：Amsterdam School","url":"https://en.wikipedia.org/wiki/Amsterdam_School"}]},"queen-anne-style":{"summary":"“安妮女王风格”是19世纪后期复兴式建筑的后设名称，并非安妮女王在位时期建筑的原样复刻。英国路线常联系红砖、白色窗框和本土传统，北美住宅则发展出不对称体量、门廊、塔楼及多材料表面；两者不可混成一种维多利亚豪宅模板。","recognition":"英国或北美分支分别处理；可采用不对称住宅体量、门廊、凸窗和复合屋顶，但不要求塔楼齐全；山墙、烟囱、窗格、木构或砖石细部按地区建造体系组合；红砖、木瓦、彩绘木构、灰泥和玻璃本色随地区与年代变化；住宅环境中的自然日光显示屋面层次、门廊深度和材料差异；砖、木构、木瓦、灰泥、板岩、纹样玻璃和使用风化。","influencedBy":"英国本土建筑复兴、工艺美术思想、理查德·诺曼·肖等人的实践，以及北美木构技术和样式书传播","influenced":"英国和北美住宅、美国Shingle Style及20世纪历史复兴住宅","sources":[{"label":"Encyclopaedia Britannica：Queen Anne style","url":"https://www.britannica.com/art/Queen-Anne-style"},{"label":"Wikipedia：Queen Anne style architecture","url":"https://en.wikipedia.org/wiki/Queen_Anne_style_architecture"}]},"expressionist-architecture":{"summary":"表现主义建筑主要指第一次世界大战前后德国、荷兰及中欧的多种实验，既有砖砌塑性，也有玻璃乌托邦、晶体想象和有机混凝土形体。大量方案停留在图纸、模型或展览层面，因此不能用少数建成的洞穴式或船体式建筑概括整个倾向。","recognition":"建成项目、图纸或模型按各自媒介组织动态轴线、集中体量或乌托邦场景；晶体、弧形砖体、锐角或有机壳体仅按具体建筑师和项目选用；砖石、玻璃、混凝土及图纸综合色来自对象，不固定深褐和内部橙光；建成建筑使用真实日光；纸上方案保留绘图明暗与媒介，不统一电影式强反差；砖、玻璃、混凝土、钢、石膏模型、纸本综合色和可见施工接缝。","influencedBy":"欧洲表现主义艺术、新艺术、工业化材料、战争经验、乌托邦社团及哥特建筑的现代重释","influenced":"阿姆斯特丹学派、砖表现主义、电影布景、有机建筑及后来的雕塑性建筑","sources":[{"label":"Encyclopaedia Britannica：Expressionism in architecture","url":"https://www.britannica.com/art/Expressionism/Expressionism-in-architecture"},{"label":"Wikipedia：Expressionist architecture","url":"https://en.wikipedia.org/wiki/Expressionist_architecture"}]},"beaux-arts-architecture":{"summary":"布杂艺术建筑源于巴黎美术学院的设计教育与竞图体系，强调轴线规划、空间序列、构图层级和古典语汇的适配，而非单一豪华立面。它经国际学生和机构传播到公共建筑、校园、车站与城市规划，但不同国家并不共享同一装饰密度。","recognition":"以主次轴线、入口—大厅—楼梯—核心空间的仪式序列组织平面和体量；古典柱式、拱券、穹顶与雕塑按构图等级配置，不要求每处满布装饰；石材、灰泥、金属、马赛克和室内综合色依地区、预算与用途变化；真实日光和室内环境光显示轴线、穹顶与材料层级，不用统一金色辉光；切石、灰泥、砖、钢铁结构、铜、玻璃、雕塑和精细工艺接点。","influencedBy":"法国学院传统、古典与文艺复兴建筑研究、考古测绘、设计竞图和19世纪公共机构建设","influenced":"欧美及其他地区的公共建筑、城市美化运动、学院建筑教育和纪念性规划","sources":[{"label":"The Met：The Architecture of the Ecole des Beaux-Arts","url":"https://www.metmuseum.org/essays/the-architecture-of-the-ecole-des-beaux-arts"},{"label":"Wikipedia：Beaux-Arts architecture","url":"https://en.wikipedia.org/wiki/Beaux-Arts_architecture"}]},"parametricism":{"summary":"参数化设计以变量和规则之间的关联生成、分析和调整形态，早于“参数主义”这一带有宣言性的风格名称。连续场、梯度和曲面是部分建筑实践的结果，并非参数方法的必然外观；规则、性能、制造和结构关系应可追踪。","recognition":"以变量、场地、性能和构件关系组织系统，可连续也可离散，不强制无硬分区流线；曲面、网格、孔洞和节点须显示可追踪规则，不以随机复杂度冒充参数逻辑；综合色来自材料、性能分区或数据编码，不固定白银黑渐变；真实光照揭示几何、遮阳和表皮性能；分析图可用清楚数据综合色；复合板、金属、玻璃、木、混凝土、数字加工接缝和装配公差。","influencedBy":"计算机辅助设计、样条与算法几何、系统论、数字制造、结构和环境模拟","influenced":"当代建筑、产品、景观、工程优化与大规模定制，也引发对形式主义和资源成本的批评","sources":[{"label":"RIBA Journal：Parametric design","url":"https://www.ribaj.com/intelligence/parametric-design-a-brief-history"},{"label":"Wikipedia：Parametricism","url":"https://en.wikipedia.org/wiki/Parametricism"}]},"prairie-school":{"summary":"草原学派是美国中西部一批建筑师在19世纪末至20世纪初发展出的住宅与公共建筑倾向，强调水平延展、开放平面、整体家具和场地关系。弗兰克·劳埃德·赖特最著名，但低坡屋顶、长窗带和土色材料并非所有成员或项目的必备清单。","recognition":"以场地、入口路径、壁炉核心和开放相连空间组织住宅，不只复制水平外立面；悬挑屋檐、平台、窗带、砖墙和整体家具按具体建筑师与项目变化；砖石木材本色、灰泥和艺术玻璃综合色来自真实项目；自然日光经深檐和窗带进入，保留实际阴影与室内外亮度差；砖、木、灰泥、石、铅条艺术玻璃、整体家具和清楚施工接点。","influencedBy":"芝加哥建筑环境、工艺美术运动、日本艺术与空间观念、中西部景观和新住宅技术","influenced":"美国现代住宅、有机建筑、欧洲现代主义对开放平面的接受，以及整体室内设计","sources":[{"label":"Frank Lloyd Wright Foundation：Prairie Style","url":"https://franklloydwright.org/prairie-style/"},{"label":"Encyclopaedia Britannica：Prairie style","url":"https://www.britannica.com/art/Prairie-style"}]},"second-empire-style":{"summary":"第二帝国建筑首先关联拿破仑三世时期法国的国家工程、巴黎改造和折衷古典主义，随后传播至欧洲与北美。孟莎屋顶是高识别元素，但并非所有法国第二帝国建筑都有同一种屋顶，北美住宅式用法也不能反向代表法国城市与公共建筑。","recognition":"城市街区、公共建筑或住宅按地域分别组织轴线、中央段、屋顶和街道关系；孟莎屋顶、老虎窗、古典柱饰和雕塑仅在具体项目存在时使用；石材、砖、板岩、金属和室内综合色服从真实材料，不固定暖灰金绿；真实城市日光显示檐口、屋顶和立面层次，室内按实际环境光处理；切石、砖、板岩、铸铁、锌或铜屋面、灰泥和雕刻装饰。","influencedBy":"法国古典主义、文艺复兴与巴洛克复兴、奥斯曼巴黎改造、国家机构和新型城市基础设施","influenced":"19世纪后期欧洲与北美公共建筑、商业建筑、住宅和城市天际线","sources":[{"label":"Encyclopaedia Britannica：Second Empire style","url":"https://www.britannica.com/art/Second-Empire-style"},{"label":"Wikipedia：Second Empire architecture","url":"https://en.wikipedia.org/wiki/Second_Empire_architecture"}]},"high-tech-architecture":{"summary":"高技派建筑在20世纪后期把结构、设备、交通和装配逻辑转化为可读的建筑表达，常联系蓬皮杜中心、劳埃德大厦等不同方案。它不等于把彩色管线贴在玻璃盒上；外露服务、长跨结构、轻质表皮或构件可替换性在各项目中权重不同。","recognition":"以结构跨格、服务分区、交通路径和装配顺序组织空间，不把外置管线当装饰贴图；桁架、拉索、节点、管道、轻质表皮和模块按真实受力与功能关系呈现；钢铝玻璃本色与功能标识色随项目变化，不固定红黄蓝编码；真实日光和室内工作光显示透明、反射、结构深度与设备位置；钢、铝、玻璃、膜材、预制板、螺栓焊缝和可维护连接。","influencedBy":"现代主义、工程建筑、预制与系统设计、阿基格拉姆等技术乌托邦，以及航空航天和工业构造","influenced":"机场与展览建筑、可持续系统表达、当代结构表现主义和数字制造建筑","sources":[{"label":"Centre Pompidou：Our building","url":"https://www.centrepompidou.fr/en/collection/our-building"},{"label":"Wikipedia：High-tech architecture","url":"https://en.wikipedia.org/wiki/High-tech_architecture"}]},"gothic-revival-architecture":{"summary":"哥特复兴建筑从18世纪英国的古物兴趣和园林建筑发展为19世纪跨宗教、政治、教育与住宅领域的国际现象。它包含考古式复原、画意混合和结构理性等不同立场，尖拱、彩窗与垂直性不能替代对国家、宗派、年代和功能的说明。","recognition":"教堂、议会、校园或住宅按功能和地区组织轴线、塔楼、厅堂与附属体量；尖拱、肋架、扶壁、花窗和木构细部仅按具体复兴路线与结构选用；石材、砖、木、彩色玻璃和室内综合色依地区与项目变化；真实日光和彩窗透射光显示空间与材料，不用普遍黑暗神秘滤镜；石砌、砖、木构、铸铁、彩色玻璃、灰泥和手工雕刻。","influencedBy":"中世纪哥特遗存研究、浪漫主义、宗教复兴、民族国家建构、古物学与工艺改革","influenced":"19世纪教堂、议会、大学与住宅建筑、工艺美术运动及现代保护观念","sources":[{"label":"V&A：Gothic Revival","url":"https://www.vam.ac.uk/articles/gothic-revival"},{"label":"Encyclopaedia Britannica：Gothic Revival","url":"https://www.britannica.com/art/Gothic-Revival"}]},"constructivist-architecture":{"summary":"构成主义建筑是革命后苏联围绕新社会类型、工业生产和空间组织展开的多种实验，涵盖工人俱乐部、公共住宅、办公、竞赛方案和城市构想。互穿几何与外露交通常见，但红色点缀、圆筒和悬挑并非每栋建筑的必备造型。","recognition":"按工人俱乐部、公共住宅或办公功能组织互锁体量、交通和公共空间；圆筒、盒体、悬挑、楼梯与结构网格依据具体项目使用，不拼成先锋造型合集；灰泥白、砖、混凝土、钢玻璃和有限标识色随项目与现状变化；真实日光显示体量、交通和结构；历史照片保留黑白综合色而非强制红色；砖、灰泥、混凝土、钢、玻璃、木和早期工业施工痕迹。","influencedBy":"俄国先锋、构成主义艺术、革命后的社会计划、工业化、工程技术和新型集体生活方案","influenced":"现代公共建筑、建筑摄影与平面传播、后来的粗野主义、高技派及构成主义复兴","sources":[{"label":"MoMA：Russian Constructivist Architecture","url":"https://www.moma.org/calendar/exhibitions/1767"},{"label":"Wikipedia：Constructivist architecture","url":"https://en.wikipedia.org/wiki/Constructivist_architecture"}]},"classical-revival-architecture":{"summary":"古典复兴建筑是对希腊、罗马及文艺复兴古典传统的多次再解释，范围可涵盖新古典主义、Greek Revival等相交但不等同的路线。柱式、山花和对称不是充分定义；考古知识、政治功能、地区材料与现代建造技术会改变古典语汇。","recognition":"按具体复兴路线组织轴线、门廊、庭院和公共空间，不以一座神庙立面代表全部；柱式、山花、拱券、穹顶和基座须符合项目尺度与构造，不混搭无依据构件；石、砖、灰泥、综合色饰面和金属本色随地区与项目变化，古代建筑不默认纯白；真实日光显示柱列、墙体和室内序列，避免把硬投影当作古典性的必要条件；切石、砖、灰泥、木、铁钢结构、综合色装饰和真实接缝。","influencedBy":"古希腊罗马建筑、文艺复兴古典主义、启蒙时代考古、学院教育和国家公共建筑需求","influenced":"19至20世纪政府、博物馆、银行、校园与纪念建筑，以及后续新古典设计","sources":[{"label":"Encyclopaedia Britannica：Classical Revival","url":"https://www.britannica.com/art/Classical-Revival"},{"label":"Wikipedia：Neoclassical architecture","url":"https://en.wikipedia.org/wiki/Neoclassical_architecture"}]},"googie-architecture":{"summary":"Googie是美国战后路边商业建筑的非正式名称，尤与南加州咖啡馆、汽车旅馆、加油站和招牌文化相关。上扬屋顶、星爆、回旋镖和霓虹体现汽车时代与太空时代的吸引策略，但并非每栋建筑同时具备全部符号，也不等于所有中世纪现代建筑。","recognition":"从道路和停车场的移动视点组织屋顶、招牌、入口与夜间识别，不拼贴所有太空符号；上扬屋顶、飞翼、星爆、回旋镖、细柱和大玻璃面按具体商业项目选用；结构与招牌综合色随品牌和遗存变化，不固定青绿珊瑚红黄白套色；真实日光或原有霓虹和灯箱夜光显示轮廓；不添加不存在的发光构件；钢、玻璃、混凝土、灰泥、塑料、霓虹管、灯箱和真实老化。","influencedBy":"Streamline Moderne、战后汽车文化、路边商业、霓虹招牌、航空航天和原子时代大众视觉","influenced":"主题商业建筑、拉斯维加斯与路边招牌、复古未来主义及战后建筑保护","sources":[{"label":"Getty：What Is Googie Architecture?","url":"https://www.getty.edu/news/what-is-googie-architecture/"},{"label":"Los Angeles Conservancy：Googie","url":"https://www.laconservancy.org/learn/historic-places/googie-style/"}]},"international-style-architecture":{"summary":"“国际风格”由1932年纽约现代艺术博物馆展览及其著作推广，用于概括若干现代建筑的体量而非实体、规则性和去装饰倾向。它不是覆盖全球现代主义的中性名称，也不能抹去包豪斯、勒·柯布西耶、各地气候回应和战后企业建筑之间的差异。","recognition":"按具体项目组织自由或规则平面、框架跨格、体量和场地，不固定白盒加水平窗带；直角板片、柱网、幕墙、架空体量或曲面元素依建筑师与时期选择；白色灰泥、混凝土、钢、玻璃、砖和材料本色均可出现，不限定黑白灰；真实自然光显示透明、遮阳、室内外关系与气候差异，不用无阴影产品图光；钢筋混凝土、钢框架、玻璃、灰泥、砖、幕墙接点和真实使用痕迹。","influencedBy":"欧洲现代主义、钢筋混凝土与钢框架、包豪斯、De Stijl、功能主义和新住房实践","influenced":"战后办公楼、住宅与公共建筑、企业现代主义，以及对普遍主义和地方适应的批评","sources":[{"label":"Encyclopaedia Britannica：International Style","url":"https://www.britannica.com/art/International-Style-architecture"},{"label":"MoMA：Modern Architecture: International Exhibition","url":"https://www.moma.org/calendar/exhibitions/2044"}]},"hollywood-regency":{"summary":"好莱坞摄政是与电影工业、明星住宅、摄影棚布景和装饰师文化相关的美国室内风格标签，融合古典、摄政、Art Deco、亚洲和现代元素以追求镜头中的戏剧效果。镜面、黑白、金色和丝绒常见但不是每个室内的固定清单。","recognition":"按房间功能建立清楚焦点、对称或舞台式陈设和摄影视线，不堆满镜面家具；古典曲线、细腿家具、屏风和现代几何依设计师项目混合；黑白、宝石色、粉彩、金属和漆色可变，不固定黑金综合色；柔和室内环境光和局部灯具高光显示材质，保留真实镜面反射；漆面、镜、黄铜、丝绒、玻璃、木和图案织物。","influencedBy":"好莱坞电影布景、Regency与新古典复兴、Art Deco、Chinoiserie、现代家具和明星消费文化","influenced":"战后美国高端室内、酒店、时尚摄影和当代装饰主义复兴","sources":[{"label":"Architectural Digest：Hollywood Regency","url":"https://www.architecturaldigest.com/story/hollywood-regency-style"},{"label":"Wikipedia：Hollywood Regency","url":"https://en.wikipedia.org/wiki/Hollywood_Regency"}]},"postmodern-architecture":{"summary":"后现代建筑是20世纪后期对现代主义普遍性、功能决定论和传播失语的多重回应，涉及历史引用、地方符号、类型学、综合色、装饰与大众文化。文丘里、格雷夫斯、摩尔、矶崎新等人的路径差异显著，断裂山花和粉彩不能成为统一语法。","recognition":"按具体建筑师组织正面、轴线、拼贴、场所叙事或复杂平面，不强制符号化入口；历史构件、地方原型、几何体和商业表皮可被引用、抽象或夸张，但须说明来源；综合色从石材与砖到高纯度饰面不等，不把粉彩当作整个后现代建筑的标志；真实日光和室内环境光显示材料、立面厚度及引用构件，不用舞台式综合色光泛化；石、砖、灰泥、瓷砖、预制混凝土、金属玻璃和商业饰面。","influencedBy":"现代主义及其批评、历史建筑、商业街景、大众文化、符号学、城市类型学和地方传统","influenced":"后现代城市与室内、解构主义辩论、新传统建筑，以及当代对图像和符号的再利用","sources":[{"label":"V&A：Postmodern architecture","url":"https://www.vam.ac.uk/articles/postmodern-architecture"},{"label":"Wikipedia：Postmodern architecture","url":"https://en.wikipedia.org/wiki/Postmodern_architecture"}]},"deconstructivist-architecture":{"summary":"解构主义建筑是1988年纽约现代艺术博物馆展览推广的争议性集合标签，参展建筑师并未组成统一运动。非正交轴线、碎片和表皮错动在部分作品中重要，但受控的不稳定来自不同设计过程、结构与场地，不能简化为随机扭曲或破碎金属外壳。","recognition":"按具体项目组织轴线冲突、位移、折叠、空隙与场地路径，不制造随机碎片；板片、楔体、扭曲网格或曲面来自设计与结构逻辑，不要求锐角和金属表皮；混凝土、砖、玻璃、石材、金属和综合色饰面随建筑师项目变化；真实日光显示折面、缝隙和内部空间；复杂阴影必须来自实际几何；钢、混凝土、玻璃、砖石、金属板及定制节点，保留可建造关系。","influencedBy":"俄国构成主义再发现、后现代建筑争论、哲学解构的选择性关联、计算与工程能力发展","influenced":"1990年代以来的地标建筑、数字几何、复杂表皮与当代建筑展览文化","sources":[{"label":"MoMA：Deconstructivist Architecture","url":"https://www.moma.org/calendar/exhibitions/1813"},{"label":"Encyclopaedia Britannica：Deconstructivism","url":"https://www.britannica.com/art/Deconstructivism"}]},"miami-modernism":{"summary":"Miami Modern（MiMo）是战后南佛罗里达酒店、公寓和商业建筑对现代主义、汽车文化、旅游和热带气候的地区性改造。曲面雨棚、阳台、遮阳花格与活泼标识多样并存，粉彩Art Deco立面不能替代MiMo本身。","recognition":"按酒店、公寓、汽车入口、泳池和街道组织阳台、雨棚和标识，不复制南海滩Art Deco立面；薄板、曲面、花格、外廊和装饰构件依具体项目与气候功能使用；白、综合色灰泥、玻璃铝材和项目特定强调色，不固定粉薄荷珊瑚套色；强热带日光形成遮阳投影，夜间只呈现真实招牌和室外灯光；灰泥、混凝土、玻璃、铝、马赛克、水磨石和海滨风化。","influencedBy":"国际现代主义、Streamline Moderne、战后汽车与旅游文化、空调技术、热带气候和度假商业","influenced":"南佛罗里达酒店住宅、度假建筑、热带现代设计及当代MiMo保护","sources":[{"label":"Miami Design Preservation League：MiMo","url":"https://mdpl.org/about/miami-modern/"},{"label":"Wikipedia：Miami Modern architecture","url":"https://en.wikipedia.org/wiki/Miami_Modern_architecture"}]},"critical-regionalism":{"summary":"批判地域主义是亚历山大·楚尼斯、莉亚娜·勒费夫尔和肯尼斯·弗兰姆普顿等人提出的建筑批评框架，主张以地形、气候、触觉和地方建造抵抗无差别全球化，同时避免怀旧民俗复制。它不是可凭石木土色识别的统一风格。","recognition":"从地形、朝向、步行体验和公共生活生成空间，不套用地方屋顶或纹样；现代抽象体量通过墙、檐、庭院和开口回应气候与建造，不追求统一外观；综合色来自地方材料、光和使用，不把土色当地域性的充分证据；自然光、阴影、风和热环境是空间机制，而非表面滤镜；地方石砖木土、混凝土、金属、手工与现代连接按项目整合。","influencedBy":"现代主义、现象学、地方建造与气候知识、后殖民语境，以及对国际风格普遍主义的批评","influenced":"当代场所性建筑、气候响应、材料实践和全球南方现代主义研究","sources":[{"label":"MoMA Magazine：Critical Regionalism","url":"https://www.moma.org/magazine/articles/885"},{"label":"Wikipedia：Critical regionalism","url":"https://en.wikipedia.org/wiki/Critical_regionalism"}]},"tropical-modernism":{"summary":"热带现代主义将现代建筑的结构与规划用于炎热湿润地区，通过遮阳、通风、雨水和室内外过渡回应气候；它同时牵涉殖民机构、独立国家和本地建筑师的复杂历史。花格、架空和深檐重要，但不能抹去国家、作者和政治背景。","recognition":"按风向、雨季、遮阳、公共流线和室内外过渡组织建筑，而非附加棕榈植物；架空、深檐、百叶、花格、庭院和薄屋顶依据具体气候与项目选用；混凝土、砖、木、灰泥与地方材料本色为主，综合色不等于热带高饱和；强日光经遮阳构件过滤，保留真实风雨、阴影与室内亮度；混凝土、砖花格、木、金属、玻璃、地方工艺和气候老化。","influencedBy":"现代主义、殖民热带建筑研究、本地建造与气候知识、公共机构建设及独立后的国家项目","influenced":"非洲、南亚、东南亚与加勒比现代建筑、气候设计和当代低能耗建筑","sources":[{"label":"V&A：Tropical Modernism","url":"https://www.vam.ac.uk/exhibitions/tropical-modernism-architecture-and-independence"},{"label":"Wikipedia：Tropical Modernism","url":"https://en.wikipedia.org/wiki/Tropical_Modernism"}]},"desert-modernism":{"summary":"沙漠现代主义常指美国西南部、尤其棕榈泉一带的战后现代建筑，以场地视野、遮阳、室内外生活和轻型建造回应干旱环境。它是地区性历史标签，不等于全球所有沙漠建筑，也不能只靠玻璃盒、棕榈和砂色综合色识别。","recognition":"从山景、朝向、泳池或庭院和汽车到达组织低矮空间，不把空旷沙漠当装饰背景；薄屋顶、深檐、玻璃面、石墙和模块结构按具体项目与热环境使用；石、木、钢、玻璃和灰泥本色随建筑变化，不固定沙色暖白黑绿；强日光、深檐阴影和室内外亮度差须符合真实朝向与气候；地方石、木、钢、玻璃、混凝土砌块、灰泥和干旱风化。","influencedBy":"中世纪现代建筑、好莱坞与度假文化、汽车生活、钢木结构、沙漠气候和山地景观","influenced":"加州住宅、度假建筑、室内外生活方式及棕榈泉现代主义保护","sources":[{"label":"Palm Springs Art Museum：Architecture and Design Center","url":"https://www.psmuseum.org/architecture-design-center"},{"label":"Wikipedia：Desert Modernism","url":"https://en.wikipedia.org/wiki/Desert_Modernism"}]},"blobitecture":{"summary":"团块建筑是对数字建模推动的连续、软性和拓扑形体的非正式标签，常带有批评或戏称意味，并非统一运动。曲面可能来自充气、壳体、网格或分片建造；圆润外观本身不足以证明结构、空间和制造具有连续逻辑。","recognition":"从场地、入口、内部空间和结构组织单体或相连体量，不把任意圆角建筑称为团块；膨胀曲面、滴状轮廓、壳体或网格必须对应具体几何与建造方法；综合色来自表皮、玻璃、金属、混凝土或膜材，不固定白银半透明；真实光照显示曲率、接缝和内部深度，连续高光须来自实际表面；混凝土壳、钢网格、玻璃、复合板、膜材、分片和数字制造接点。","influencedBy":"数字样条与动画软件、拓扑研究、生物形态设计、复合材料和计算制造","influenced":"21世纪地标建筑、参数化表皮、数字制造与产品设计中的连续形体","sources":[{"label":"Encyclopaedia Britannica：Blob architecture","url":"https://www.britannica.com/art/blob-architecture"},{"label":"Wikipedia：Blobitecture","url":"https://en.wikipedia.org/wiki/Blobitecture"}]},"metabolism":{"summary":"日本新陈代谢派由1960年世界设计会议前后发表宣言的一批建筑师和设计师推动，以城市和建筑作为可生长、更新的系统。巨构、核心筒、胶囊和海上城市多为不同成员的方案或少数建成实例，不能把中银胶囊塔的外观推广为整个运动。","recognition":"按宣言、城市方案、巨构或建成建筑分别组织核心、基础设施和可变单元；胶囊、塔核、桥接框架、海上平台和重复模块仅按具体方案使用；混凝土、钢、玻璃、预制面板及综合色标记来自项目，不固定工业原色；建成项目使用真实日光；模型与图纸保留媒介光线，不把未来辉光当史实；现浇或预制混凝土、钢、玻璃、螺栓节点、模型材料和绘图纸。","influencedBy":"战后日本重建、现代主义、城市人口增长、预制工业、海洋与基础设施构想，以及传统更新观念的现代解释","influenced":"巨构建筑、模块化与可变建筑、未来城市想象及全球战后建筑讨论","sources":[{"label":"MoMA：Metabolism in Architecture","url":"https://www.moma.org/collection/works/1102"},{"label":"Wikipedia：Metabolism architecture","url":"https://en.wikipedia.org/wiki/Metabolism_(architecture)"}]},"romanesque-revival-architecture":{"summary":"新罗马式建筑是19世纪对11至12世纪罗马式建筑的多种复兴，涵盖教堂、公共建筑、校园和北美Richardsonian Romanesque等分支。半圆拱和厚重石作常见，但对称、堡垒感和粗琢石并非所有地区与用途的统一规则。","recognition":"按教堂、校园或公共功能组织塔、拱廊、入口和体量，不固定对称堡垒轮廓；半圆拱、厚墙、粗短柱和雕刻按具体地区与分支使用；石、砖、瓦、木和室内综合色来自材料与项目，不固定暖褐砖红；真实日光显示开口深度和砌体重量，室内保留窗洞造成的明暗关系；粗细不同的石砌、砖、木屋架、瓦、金属和雕刻接点。","influencedBy":"中世纪罗马式遗存、浪漫主义与民族建筑研究、教会复兴、19世纪材料和工程","influenced":"欧美教堂、大学与公共建筑、Richardsonian Romanesque及后续重型石作传统","sources":[{"label":"Encyclopaedia Britannica：Romanesque Revival","url":"https://www.britannica.com/art/Romanesque-Revival"},{"label":"Wikipedia：Romanesque Revival architecture","url":"https://en.wikipedia.org/wiki/Romanesque_Revival_architecture"}]},"neo-vernacular-architecture":{"summary":"新乡土建筑泛指当代建筑对地方空间、材料、气候和工艺的再解释，术语边界并不稳定，也不等同于新古典主义。可识别屋顶或院落只是部分路线；关键是说明谁的乡土传统、如何转译，以及现代结构和社区需求如何介入。","recognition":"从具体地区的院落、屋顶、街巷、家庭或公共活动生成空间，不拼贴泛乡村符号；坡顶、厚墙、木架、砖拱或地方构件须对应真实传统与现代功能；土砖木瓦、石、混凝土和现代材料本色依地区变化，不统一米色；自然光、通风、雨雪和檐下阴影符合当地气候，不用怀旧暖光滤镜；夯土、地方砖瓦、石木、灰泥、再生材料和可辨现代加固节点。","influencedBy":"地方民居与工艺、气候知识、后现代地方主义、社区建筑、现代工程与遗产讨论","influenced":"当代住宅、乡村公共建筑、文化旅游、低碳材料实践及对地方身份的争论","sources":[{"label":"ArchDaily：Vernacular architecture","url":"https://www.archdaily.com/tag/vernacular-architecture"},{"label":"Wikipedia：New Classical architecture","url":"https://en.wikipedia.org/wiki/New_Classical_architecture"}]},"italian-radical-design":{"summary":"意大利激进设计是1960年代中期至1970年代多组建筑师与设计师对功能主义、消费社会和职业制度的批判实践，涵盖家具、室内、摄影拼贴、展览、行为和反乌托邦城市方案。鲜艳塑料和尺度错置只是部分成果，不能把后来孟菲斯的综合色语言反投射到全部激进设计。","recognition":"家具、室内、拼贴、装置或城市方案按具体团体和媒介组织一个批判命题；超大几何、软体、连续网格、日常物和反建筑元素只按Superstudio、Archizoom等具体实践选用；综合色可高饱和、单色、黑白或材料本色，不预设荧光原色和镜面；展览与室内保留真实环境光；拼贴、摄影和图纸按其媒介表现；塑料、泡沫、层压板、织物、照片、印刷纸、模型和临时装置材料。","influencedBy":"意大利战后设计、波普艺术、Arte Povera、政治抗议、消费社会批评和实验建筑出版","influenced":"1972年MoMA意大利设计展、Studio Alchimia、Memphis、概念设计与批判性设计","sources":[{"label":"MoMA：Italy: The New Domestic Landscape","url":"https://www.moma.org/calendar/exhibitions/1783"},{"label":"Wikipedia：Radical period (design)","url":"https://en.wikipedia.org/wiki/Radical_period_(design)"}]},"organic-architecture":{"summary":"有机建筑是一组强调建筑、场地、材料、结构和生活形成整体的设计立场，最常联系弗兰克·劳埃德·赖特，但也有不同建筑师与地区解释。它不等同于模仿植物曲线；直线、几何模块、地方石材和技术系统同样可能服务于整体关系。","recognition":"从地形、朝向、入口、连续空间和生活方式生成平面体量，不把建筑做成仿生物外壳；水平板片、几何网格、曲面、悬挑或厚墙随场地和建筑师变化；地方石木砖土、混凝土和玻璃本色为主，综合色由项目决定而非固定土色综合色；自然光随朝向、檐口、开口和空间路径变化，保留真实气候响应；地方石、木、砖、混凝土、玻璃、整体家具和连续施工细部。","influencedBy":"工艺美术、浪漫主义自然观、草原学派、场地与材料实践，以及现代结构技术","influenced":"20世纪住宅和公共建筑、生态与生物气候设计、批判地域主义及雕塑性建筑","sources":[{"label":"Frank Lloyd Wright Foundation：Organic Architecture","url":"https://franklloydwright.org/organic-architecture-and-design/"},{"label":"Encyclopaedia Britannica：Organic architecture","url":"https://www.britannica.com/art/organic-architecture"}]},"chicago-school":{"summary":"芝加哥学派是后世对19世纪末至20世纪初芝加哥商业建筑创新的概括，重点包括金属骨架、防火技术、电梯、深基础和大窗洞，而非一个成员固定的正式组织。“三段式立面”和Chicago window是重要路线，但装饰、墙体表达和高度因建筑师及法规不同。","recognition":"按地块、结构跨格、采光和商业交通组织高层平面与立面，不强制底中顶三段式；金属骨架、大窗洞、凸窗、陶土包覆和竖向或水平表达依具体建筑变化；砖石、陶土、铁钢和玻璃本色为主，不把所有作品统一为暖褐与灰蓝；真实城市日光显示窗洞深度、街墙关系和结构跨格，室内保留采光限制；铸铁或钢骨架、砖石、防火陶土、玻璃、铆接构件和历史修缮痕迹。","influencedBy":"芝加哥大火后重建、商业地产、电梯与金属骨架、防火和地基工程，以及Romanesque与古典设计传统","influenced":"现代高层办公楼、钢框架与幕墙发展、草原学派和20世纪城市商业建筑","sources":[{"label":"Chicago Architecture Center：Chicago School","url":"https://www.architecture.org/learn/resources/architecture-dictionary/entry/chicago-school/"},{"label":"Encyclopaedia Britannica：Chicago school","url":"https://www.britannica.com/art/Chicago-school-architecture"}]},"aztec-art":{"summary":"通常称阿兹特克艺术的对象主要来自墨西加及其帝国网络，涵盖石雕、羽毛工艺、金工、陶器、建筑和写本。纪念性、历法与神祇图像不能化为通用阶梯几何；“Aztec”与Mexica的使用范围也应说明。","recognition":"纪念雕塑、建筑轴线、圆形石盘、贡赋写本或羽毛物件按功能组织；深刻石雕、复合神像、自然观察动物和图像文字需按对象区分；玄武岩、综合色羽毛、绿松石、金和写本综合色依材料变化；石雕以真实侧光，羽毛金属与写本分别处理反射和平面光；火山石、羽毛马赛克、绿松石、金属、陶器、amatl纸和残色。","influencedBy":"墨西哥中部早期传统、托尔特克和特奥蒂瓦坎遗产、贡赋网络与墨西加宗教政治","influenced":"殖民时期墨西哥图像、现代国家身份和全球前哥伦布艺术接受","sources":[{"label":"The Met：Aztec art","url":"https://www.metmuseum.org/essays/aztec-art"},{"label":"British Museum：Aztec","url":"https://www.britishmuseum.org/collection/galleries/mexico"}]},"olmec-art":{"summary":"奥尔梅克艺术形成于墨西哥湾岸多个中心，以巨石头像、玉石小像、祭坛和洞穴—山岳图像著称。它不是整个中部美洲的单一“母文化”，所谓婴儿脸和美洲豹特征也不能覆盖全部对象。","recognition":"巨石独立像、祭坛、石碑或小型玉器按真实尺度和观看关系陈列；厚重体量、浅刻符号和个体面貌依对象类型，不套用婴儿脸或美洲豹；玄武岩灰黑、玉石绿、陶土和残存综合色来自材料；擦边侧光显示凿刻和圆雕体积，保留真实投影；玄武岩、玉石、陶土、凿磨痕、抛光、风化和断损。","influencedBy":"墨西哥湾岸早期聚落、王权和仪式、石材运输及区域交流","influenced":"后续中部美洲纪念雕塑和图像传统，但具体传播关系需谨慎表述","sources":[{"label":"The Met：Olmec art","url":"https://www.metmuseum.org/essays/olmec-art"},{"label":"Wikipedia：Olmecs","url":"https://en.wikipedia.org/wiki/Olmecs"}]},"brazilian-concretism":{"summary":"巴西具体主义在1950年代围绕圣保罗Grupo Ruptura、里约Grupo Frente和1956年全国具体艺术展发展，将国际具体艺术与巴西工业化、设计和诗歌相连。两地艺术家并非完全一致，理性网格和工业表面不能覆盖全部实践。","recognition":"严格网格、数学序列和非再现几何模块；直线、方形、圆与精确硬边；黑白、红黄蓝与系统化纯色；完全平面化；平滑工业颜料、印刷或硬质板面。","influencedBy":"国际具体艺术、Max Bill、De Stijl、构成主义、巴西工业化、现代设计与具体诗","influenced":"巴西新具体主义、视觉诗、现代设计和拉丁美洲几何抽象","sources":[{"label":"MoMA：Concrete and Neo-Concrete Art in Brazil","url":"https://www.moma.org/calendar/exhibitions/1455"},{"label":"Tate：Concrete art","url":"https://www.tate.org.uk/art/art-terms/c/concrete-art"}]},"maya-art":{"summary":"玛雅艺术跨多个城邦、语言和前古典至后古典阶段，涵盖建筑、石碑、灰泥、陶器、壁画、玉器和折页书。文字、历法和王权图像高度重要，但流动轮廓、玛雅蓝或密集文字块不适用于所有时期媒介。","recognition":"建筑纪念轴线、石碑中心、陶器环带、壁画叙事或折页书按媒介组织；浮雕体积、流动线、灰泥塑形和象形文字区依城市时期变化；石灰白、赤铁红、玛雅蓝、黄、黑和玉石色依据对象；建筑与石雕使用真实日光，壁画陶器保持文物阅读光；石灰岩、灰泥、陶器、矿物综合色、玉石、树皮纸和风化。","influencedBy":"玛雅城市政治、宗教历法、文字传统、区域贸易和中部美洲交流","influenced":"后古典和殖民时期玛雅文化、现代玛雅艺术与考古图像研究","sources":[{"label":"The Met：Maya art","url":"https://www.metmuseum.org/essays/maya-art"},{"label":"British Museum：Maya","url":"https://www.britishmuseum.org/collection/galleries/mexico"}]},"mixtec-art":{"summary":"米斯特克艺术来自今墨西哥瓦哈卡等地多个ñuu dzahui政治体，涵盖折页书、金工、绿松石马赛克、陶器和墓葬。清楚侧面图形和谱系叙事主要对应部分写本，不能代表全部材料，也应优先承认社群自称。","recognition":"折页格段、谱系路径、墓葬陈列或独立金工按媒介用途组织；侧面图形、日期名、金属压纹和马赛克轮廓分别处理；鹿皮暖白、赭红、黄、绿松石、黑和金来自具体对象；写本平面光，金属和马赛克使用真实小反射；鹿皮折页、矿物综合色、金工、绿松石马赛克、陶器和磨损。","influencedBy":"瓦哈卡地区早期传统、后古典政治谱系、跨中部美洲贸易与工匠网络","influenced":"殖民时期本地写本和历史记忆、墨西哥金工与现代Ñuu Dzahui文化","sources":[{"label":"The Met：Mixtec art","url":"https://www.metmuseum.org/essays/mixtec-art"},{"label":"Wikipedia：Mixtec","url":"https://en.wikipedia.org/wiki/Mixtec"}]},"moche-art":{"summary":"莫切艺术来自秘鲁北海岸多个政治中心，以肖像陶器、模制器皿、壁画、金属和复杂仪式叙事著称。所谓武士祭司图像只是部分题材；不同河谷和早晚阶段并非单一国家风格。","recognition":"肖像器皿独立陈列、陶器环带、壁画分区或金属服饰按对象组织；写实面貌、模制体积、细线叙事和金属压纹依媒介阶段变化；陶土红白黑、壁画综合色、铜金银和绿锈来自对象；陶器金属用真实侧光，壁画保持文物阅读光；模制陶器、滑浆、壁画灰泥、铜金银合金、锤揲和腐蚀。","influencedBy":"北海岸早期文化、灌溉城市、仪式政治、陶器和金属技术","influenced":"后续北海岸西坎与奇穆传统及现代安第斯考古图像","sources":[{"label":"The Met：Moche","url":"https://www.metmuseum.org/essays/moche"},{"label":"Wikipedia：Moche culture","url":"https://en.wikipedia.org/wiki/Moche_culture"}]},"nazca-art":{"summary":"纳斯卡艺术来自秘鲁南海岸，以多色陶器、纺织、头饰和地景线条著称。地画不是从空中观看而设计的现代图形，陶器多色和神话复合体也不能统一成一套满版图案。","recognition":"陶器环带、纺织重复或地表长线按实际尺度和观看路径分开；多色具象、复合神灵、几何织纹和地画轮廓各自保留媒介逻辑；红、橙、黄、黑白、紫和灰等多色陶器依对象变化；陶器织物使用文物光，地景使用真实沙漠日光与地表阴影；细陶、多色滑浆、纤维、刺绣、石砾地表和风化。","influencedBy":"帕拉卡斯传统、南海岸环境、仪式和纺织陶器技术","influenced":"瓦里时期南海岸艺术及现代秘鲁遗产和地景艺术讨论","sources":[{"label":"The Met：Nazca","url":"https://www.metmuseum.org/essays/nasca"},{"label":"Wikipedia：Nazca culture","url":"https://en.wikipedia.org/wiki/Nazca_culture"}]},"tropicalia":{"summary":"Tropicalia/Tropicalismo是1960年代末巴西跨音乐、视觉艺术、诗歌、戏剧和电视的文化运动，以‘文化食人’策略并置本土和国际大众文化，并处于军事独裁与审查语境。综合色热带符号和媒体拼贴是手段，不是无政治内容的欢乐综合色风格。","recognition":"流行媒体、热带图像、政治文字与综合色舞台的杂交拼贴；摄影剪贴、手绘曲线、广告图形和装置模块；高饱和绿黄红蓝、黑白与综合色冲突；舞台综合色光、平面印刷光和现场日光混合；丝网、拼贴、塑料、织物、电视图像和廉价消费材料。","influencedBy":"巴西现代主义食人主义、Bossa Nova、具体诗、Pop Art、电视大众文化、Oiticica和军事独裁政治","influenced":"巴西流行音乐、当代艺术、时尚和全球混杂文化理论","sources":[{"label":"Tate：Tropicalia","url":"https://www.tate.org.uk/art/art-terms/t/tropicalia"},{"label":"MoMA：Tropicalia","url":"https://www.moma.org/collection/terms/tropicalia"}]},"teotihuacan-art":{"summary":"特奥蒂瓦坎艺术围绕大型规划城市、公寓壁画、石雕、陶器和羽蛇神建筑展开，政治和语言身份仍有研究争议。正面神像、重复模块与平面壁画是部分机制，不应把后世阿兹特克命名倒推为确定自称。","recognition":"城市网格、金字塔轴线、公寓壁面分区或器物重复带按载体组织；建筑模块、正面面具、羽蛇与抽象水火符号只按具体遗址使用；赤铁红、黄、绿、黑、白和矿物蓝依据壁画与器物残色；建筑真实高原日光与壁画均匀文物光分开；火山石、灰泥、壁画综合色、黑曜石、陶器和修复接缝。","influencedBy":"墨西哥中部城市化、宗教和贸易网络、早期中部美洲建筑绘画","influenced":"古典期玛雅及中部墨西哥诸文化，并被后世阿兹特克重新命名和敬仰","sources":[{"label":"The Met：Teotihuacan","url":"https://www.metmuseum.org/essays/teotihuacan"},{"label":"UNESCO：Pre-Hispanic City of Teotihuacan","url":"https://whc.unesco.org/en/list/414/"}]},"northwest-coast-formline-art":{"summary":"Formline是对北美西北海岸多个原住民艺术传统中以主形线、卵形、U形与分裂形组织动物、祖先和家族权利图像的形式分析术语。Tlingit、Haida、Tsimshian等社群并不共享无差别规则；家族徽章、名称、故事和复制权属于具体社群与艺术家。","recognition":"面具、箱柜、图腾柱、纺织物、版画或珠宝的结构应按民族、家族权利和媒介区分；主形线、卵形、U形、分裂形和正负形嵌套必须尊重具体设计体系，不随机拼动物；黑、赤红、蓝绿、木色与贝壳或金属色按地区、时期和材料变化；平面绘饰使用均匀光，雕刻与珠宝使用柔和擦边光显示深度与真实反射；雪松、榤木、天然与现代颜料、羊毛纺织、贝壳、银铜与真实工具痕。","influencedBy":"西北海岸原住民亲属与礼物经济、雕刻、绘饰、纺织与铜器传统、土地物种知识和家族权利","influenced":"20世纪原住民文化复振、当代雕刻、珠宝、版画与数字设计，以及原住民知识与版权讨论","sources":[{"label":"Burke Museum：Formline design","url":"https://www.burkemuseum.org/collections-and-research/culture/contemporary-culture/formline-design"},{"label":"The Met：Art of the Northwest Coast","url":"https://www.metmuseum.org/essays/native-north-american-art"}]},"inuit-printmaking":{"summary":"因纽特版画在20世纪中期由Kinngait等加拿大北极社区的合作社、艺术家与印刷者发展，包含石刻版、模板、铜版、石版和数字方法。Kinngait并不代表所有因纽特地区，动物、变形和负空间也不是统一“北极风格”。","recognition":"独立主体、叙事群组、满幅变形或开阔纸面按艺术家和社区选择；石刻版硬边、模板色、细线或自然主义形体依印刷者与技术变化；黑白、有限综合色和鲜明多色均存在，不固定冰蓝白色；平面印刷明度与纸面留白为主，不添加极光和雪景光效；石刻版、模板、铜版或石版油墨、纸、压印、版号和合作社印记。","influencedBy":"因纽特绘画雕刻和口述知识、社区合作社、南方市场及多种版画技术","influenced":"加拿大原住民现代艺术、国际版画、社区经济和因纽特艺术史","sources":[{"label":"National Gallery of Canada：Inuit art","url":"https://www.gallery.ca/collection/indigenous-art/inuit-art"},{"label":"Inuit Art Foundation","url":"https://www.inuitartfoundation.org/"}]},"inca-art":{"summary":"印加艺术以精密石作、道路与行政建筑、库姆比织物、托卡普图案、金属和木制qero等服务帝国和礼仪。托卡普是否构成书写系统仍有争议，不能生成伪文字；巨石砌筑也不代表全部印加工艺。","recognition":"建筑轴线、梯田道路、织物网格、qero器面或金属物按功能组织；精密多边石、矩形托卡普、织造模块和金属锤揲分别处理；石材、黑白赭红黄、纤维染色和金属本色依对象；高原自然日光显示砌筑，织物与器物使用文物记录光；无灰缝石作、羊驼纤维、木、陶器、金银铜和接缝磨损。","influencedBy":"安第斯早期帝国和地方传统、蒂亚瓦纳科与瓦里遗产、国家劳动和贡赋体系","influenced":"殖民安第斯视觉、现代秘鲁玻利维亚国家遗产和全球石作研究","sources":[{"label":"The Met：Inca art","url":"https://www.metmuseum.org/essays/inca-art"},{"label":"Smarthistory：Inka art","url":"https://smarthistory.org/inka-an-introduction/"}]},"traditional-balinese-painting":{"summary":"该条更准确指巴厘卡马桑式绘画：以村落工坊为核心，在寺庙、宫廷和仪式布画中表现印度教史诗与地方叙事。密集分层、程式人物和天然综合色重要，但不能代表全部“巴厘传统绘画”，也不应脱离宗教题材随意拼造神灵。","recognition":"横向叙事层、等级群组和连续满幅按仪式布、寺庙或宫廷位置组织；程式侧面、手势、服饰和尺度等级源自卡马桑图像规范，不生成混合神像；土黄、赭红、黑白和有限靛蓝等传统综合色，也允许有据可查的现代材料变化；综合色分区和线密度建立层次，实际展示保留织物或墙面的环境光；棉布、传统综合色、墨线、工坊笔触、装裱和真实使用磨损。","influencedBy":"爪哇—巴厘宫廷传统、印度教史诗、寺庙仪式、哇扬图像和地方工坊传承","influenced":"巴厘其他绘画中心、20世纪旅游艺术和当代卡马桑复兴","sources":[{"label":"The Met：Bali, Indonesia","url":"https://www.metmuseum.org/essays/bali-indonesia"},{"label":"Wikipedia：Balinese art","url":"https://en.wikipedia.org/wiki/Balinese_art"}]},"ubud-school-painting":{"summary":"乌布绘画在20世纪30年代巴厘艺术家、宫廷赞助与Pita Maha等网络中发展，并与Walter Spies、Rudolf Bonnet等外来艺术家互动。纸本、日常题材、综合色明暗和个体风格扩展了早期传统，但这种变化不能被写成欧洲人单向“现代化”巴厘艺术。","recognition":"高密度日常场景、弯曲路径、多点观察或较集中主体按艺术家选择；细密流线、人物植物节奏、个体比例和综合色阴影不再服从单一仪式程式；墨褐、灰绿、土色和更宽现代综合色域随纸张与艺术家变化；漫射日光、综合色明暗和线密度形成浅层体积，不套用统一热带滤镜；纸或布、墨、水彩或综合色层染、细密手绘和真实老化。","influencedBy":"巴厘寺庙宫廷绘画、当地艺术家网络、Pita Maha、旅游市场和跨文化交流","influenced":"巴厘现代绘画、国际收藏和乌布旅游视觉经济","sources":[{"label":"National Gallery of Australia：Balinese painting","url":"https://searchthecollection.nga.gov.au/search?keyword=Balinese%20painting"},{"label":"Wikipedia：Ubud","url":"https://en.wikipedia.org/wiki/Ubud"}]},"deccani-painting":{"summary":"德干绘画形成于艾哈迈德讷格尔、比贾布尔、戈尔康达等宫廷，后续亦受海得拉巴环境影响。拉长人物、浓郁综合色、奇异尺度和幻想空间是部分特征，但各苏丹国、时期及与莫卧儿交流存在差别，不能一律写成夜色珠宝光。","recognition":"高视点宫廷、偏心肖像、建筑庭园或大面积空地按具体苏丹国选择；拉长比例、精细轮廓、综合色体积和不寻常尺度不是每个中心的共同规则；深群青、孔雀绿、紫红、金、粉和综合色背景依工坊变化，不强制夜色；综合色层、金属细节和局部柔化形成空间，不添加奇幻光晕；纸本不透明水彩、金、精线、抛光表面、边框和题记。","influencedBy":"波斯和南亚绘画、德干苏丹国宫廷、区域纺织金工和莫卧儿交流","influenced":"海得拉巴绘画、拉贾斯坦和南印度宫廷艺术，以及现代德干艺术史","sources":[{"label":"The Met：The art of the Deccan sultanates","url":"https://www.metmuseum.org/essays/the-art-of-the-deccan-sultanates"},{"label":"Wikipedia：Deccan painting","url":"https://en.wikipedia.org/wiki/Deccan_painting"}]},"company-painting":{"summary":"所谓“公司画”是殖民时期欧洲雇主和东印度公司相关市场委托印度艺术家制作的一组跨地区作品，名称具有殖民史视角。它涵盖人物、建筑、植物动物、职业和风俗记录，制作中心与艺术家策略多样，不能只写成白底单标本自然史图。","recognition":"单体标本、成组人物、建筑全景、职业图谱或相册页按地区委托选择；精确观察、地方细密线、透明水彩和欧洲阴影机制以不同程度结合；透明水彩、纸白、植物综合色、服饰色和土色按主题与画师变化；自然史可用轻投影，建筑人物可有更复杂环境光，不统一档案柔光；欧洲或印度纸、水彩和不透明综合色、云母、精笔、题记和装帧。","influencedBy":"莫卧儿及地方宫廷画师、欧洲殖民委托、自然史分类、地图测绘和水彩纸张","influenced":"殖民档案图像、印度现代绘画、博物馆分类和后殖民视觉研究","sources":[{"label":"Victoria and Albert Museum：Company painting","url":"https://www.vam.ac.uk/articles/company-painting-in-india"},{"label":"Wikipedia：Company style","url":"https://en.wikipedia.org/wiki/Company_style"}]},"gond-painting":{"summary":"当代贡德绘画并非不变的古老纸本风格，而是在1980年代后由Jangarh Singh Shyam等来自印度中部贡德社群的艺术家，把地方叙事、墙面记忆和个体想象转化到纸与画布。点线填充很常见，但艺术家、氏族和世代语言并不统一。","recognition":"轮廓内纹理、满幅分叉、独立主体或复杂叙事按具体艺术家组织；点、线、鳞片、网格和分叉结构是可选个体语汇，不生成通用“贡德纹”；高饱和多色、黑白和有限综合色均可，综合色方案依艺术家与媒介；平面综合色与纹样密度建立明暗，画布作品保留真实展场光；纸或画布、墨水、丙烯、细笔点线、版画和可见手工节奏。","influencedBy":"贡德社群叙事、房屋装饰和自然观、博帕尔艺术机构及个体艺术家创新","influenced":"印度当代原住民艺术、国际展览和后续贡德艺术家世代","sources":[{"label":"Sahapedia：Gond painting","url":"https://www.sahapedia.org/gond-painting"},{"label":"Wikipedia：Gond painting","url":"https://en.wikipedia.org/wiki/Gond_painting"}]},"gandhara-art":{"summary":"犍陀罗艺术形成于今巴基斯坦北部和阿富汗东部等地的佛教文化网络，吸收希腊化、罗马、伊朗和南亚多重资源。灰色片岩佛像和深衣褶最著名，但灰泥、陶塑、叙事浮雕与后期阶段同样重要，不能简单称为“希腊罗马造型加佛教题材”。","recognition":"正面像、浅龛、连续佛传浮雕或建筑构件按原物用途组织；自然主义体积、深褶、波浪发束和地域化图像特征须按时期材料选择；片岩灰、灰泥白、陶土和残存综合色来自原物，不统一为灰石单色；擦边或柔侧光揭示真实雕刻和灰泥体积，不制造电影式神圣光；灰色片岩、灰泥、陶塑、石刻凿痕、残色和风化边缘。","influencedBy":"南亚佛教、希腊化与罗马视觉传统、贵霜政治、伊朗和中亚交流","influenced":"中亚、中国和东亚佛教图像，以及南亚西北部雕塑传统","sources":[{"label":"The Met：Gandhara","url":"https://www.metmuseum.org/essays/gandhara"},{"label":"Wikipedia：Greco-Buddhist art","url":"https://en.wikipedia.org/wiki/Greco-Buddhist_art"}]},"kalighat-painting":{"summary":"卡利卡特画（Kalighat painting）由加尔各答卡利神庙周边市场的画工面向朝圣者和城市消费者制作，题材从神祇扩展到巴布文化、社会讽刺和都市事件。快速刷线和素底单体是典型，但版画竞争、作坊复制和综合色变化也属于其历史。","recognition":"单一放大主体、成对人物或少量互动场景置于素纸，保持快速市场图像的直接性；粗黑连续轮廓、扫刷体积和概括姿态按神祇、都市或讽刺题材调整；墨黑、纸白、有限鲜明综合色和局部金属色，不固定单一综合色组；平面画面光与宽笔综合色提示体积，不添加油画式投影；纸本水彩或不透明色、松鼠毛刷线、平滑综合色、作坊复制差异和老化。","influencedBy":"孟加拉卷轴画师传统、加尔各答城市市场、神庙朝圣、殖民现代生活和印刷竞争","influenced":"印度大众艺术、民族主义和现代主义对民间图像的重估、讽刺漫画","sources":[{"label":"Victoria and Albert Museum：Kalighat painting","url":"https://www.vam.ac.uk/articles/kalighat-painting"},{"label":"Wikipedia：Kalighat painting","url":"https://en.wikipedia.org/wiki/Kalighat_painting"}]},"rajasthani-miniature":{"summary":"拉贾斯坦绘画是梅瓦尔、马尔瓦、布恩迪—科塔、斋浦尔、比卡内尔等多个宫廷传统的总称，题材与综合色、空间和莫卧儿影响程度差异很大。强烈平涂和侧面人物常见，但不能统一为红黄蓝绿的单焦点矩形画。","recognition":"宫廷、狩猎、宗教诗歌、季节图或风景按具体中心使用平面分区、连续叙事或纵深；硬边侧面、精细肖像、动物和建筑形式随梅瓦尔、科塔、比卡内尔等中心变化；朱红、黄、蓝绿、黑、金和淡色综合色按宫廷工坊选择，不设综合色定式；平面综合色、重叠、局部渐层和环境表现均可，不能一律无投影；纸本不透明水彩、矿物综合色、金、精线、边框和抛光。","influencedBy":"西印度写本、地方宫廷和宗教诗歌、莫卧儿绘画及区域工坊交流","influenced":"帕哈里绘画、地方宫廷图像和现代印度细密画复兴","sources":[{"label":"Britannica：Rajasthani painting","url":"https://www.britannica.com/art/Rajasthani-painting"},{"label":"Wikipedia：Rajput painting","url":"https://en.wikipedia.org/wiki/Rajput_painting"}]},"bengal-school":{"summary":"孟加拉画派形成于英属印度民族主义、殖民美术教育和亚洲主义讨论中，以阿巴宁德拉纳特·泰戈尔等人为核心，但成员和立场并不统一。洗染和诗性淡色是部分重要路线，不能覆盖其历史画、宗教图像、日中交流及后续分歧。","recognition":"疏朗中心、历史叙事、人物组像或装饰画面按艺术家与题材选择；柔线洗染、细密画引用、写生或更坚实轮廓并存，不统一雾化；淡褐、灰绿、靛蓝和低饱和暖色常见，也有更强综合色与墨线；薄洗低对比或明确叙事明暗按作品处理，不以朦胧等同民族性；吸水纸、水彩洗染、蛋彩、墨、日式材料影响和手工底层。","influencedBy":"印度民族主义、莫卧儿和拉其普特绘画、日本画交流、殖民美术学校与东方主义思想","influenced":"印度现代美术教育、圣蒂尼克坦、亚洲主义和反学院绘画讨论","sources":[{"label":"Victoria Memorial Hall：Bengal School","url":"https://victoriamemorial-cal.org/"},{"label":"Wikipedia：Bengal School of Art","url":"https://en.wikipedia.org/wiki/Bengal_School_of_Art"}]},"nanyang-style":{"summary":"南洋画派是对新加坡和马来亚若干华人艺术家现代实践的后设称谓，成员来自不同教育与媒介背景，以东南亚现场、移民经验、水墨、巴黎现代主义和地方文化相遇为重要议题。它不是综合色赭黄加“热带光”的统一风格，且“南洋”一词本身具有历史地域视角。","recognition":"现场速写、人物群像、村落河景、静物或现代主义分区按艺术家与媒介选择；书写线、简化综合色块、立体主义分解或观察性形体不混成一种南洋笔法；综合色从水墨淡彩到高纯度油彩，赭黄、热带绿蓝只是部分作品选择；赤道日光、室内观察光或画面综合色关系按作品处理，不套用暖湿滤镜；油彩、纸本水墨、水彩、粉彩、画布或纸纹和可见个体笔触。","influencedBy":"中国水墨与上海美术教育、巴黎现代主义、移民网络、英属马来亚和东南亚现场","influenced":"新加坡马来西亚现代艺术、区域艺术史和后殖民身份讨论","sources":[{"label":"National Gallery Singapore：Nanyang artists","url":"https://www.nationalgallery.sg/sg/en/learn-about-art/art-stories/nanyang-artists.html"},{"label":"Wikipedia：Nanyang style","url":"https://en.wikipedia.org/wiki/Nanyang_style"}]},"pahari-painting":{"summary":"帕哈里绘画涵盖巴索利、古勒尔、康格拉、昌巴等山地宫廷，综合色和造型从巴索利的强烈几何与浓色到古勒尔—康格拉的抒情自然主义差异显著。把整个传统写成柔绿薄雾和细腻恋爱情境，会把康格拉路线泛化。","recognition":"巴索利式强中心、康格拉式层叠风景或宫廷叙事按具体山地中心选择；从硬朗几何脸型到柔和人物和细密叶簇均存在，不设统一圆润线；浓黄红、深绿和金可与嫩绿、天蓝、淡粉等不同中心综合色并存；平面强综合色或柔和自然光和薄雾层次按学校与作品选择；纸本不透明水彩、透明层染、矿物综合色、金、精线和抛光。","influencedBy":"西喜马拉雅地方宫廷、宗教诗歌、拉贾斯坦和莫卧儿画师交流","influenced":"北印度宗教图像、现代细密画收藏和喜马拉雅区域艺术史","sources":[{"label":"Britannica：Pahari painting","url":"https://www.britannica.com/art/Pahari-painting"},{"label":"Wikipedia：Pahari painting","url":"https://en.wikipedia.org/wiki/Pahari_painting"}]},"pattachitra":{"summary":"pattachitra 字面指布画，但常涉及奥迪沙围绕贾格纳特信仰的布本绘画，也与孟加拉卷轴pata传统在中文中混称。两者的叙事、表演、材料和图像体系不同；密集边框、满幅平涂只适合部分奥迪沙作品，不能覆盖所有pata绘画。","recognition":"奥迪沙单幅或连环布画与孟加拉长卷叙事须分别组织，不统一为无空白边框画；均匀轮廓、装饰节点、神像或连续故事按地区工坊和表演用途选择；朱红、黄、绿、黑、白、蓝和布底按天然或现代材料变化；综合色块对比建立层级，卷轴表演在真实环境光下展开，不添加金色辉光；处理布或纸、天然与商业综合色、胶、精细线、卷折、使用和修复痕迹。","influencedBy":"奥迪沙贾格纳特寺院和画工传统、孟加拉卷轴歌唱传统、地方宗教与手工材料","influenced":"印度民间绘画、旅游工艺、当代卷轴叙事和公共文化","sources":[{"label":"Google Arts & Culture：Pattachitra","url":"https://artsandculture.google.com/entity/pattachitra/m04d6tv"},{"label":"Wikipedia：Pattachitra","url":"https://en.wikipedia.org/wiki/Pattachitra"}]},"warli-painting":{"summary":"瓦尔利绘画源于印度马哈拉施特拉瓦尔利社群的仪式墙面与女性绘画传统，1970年代后Jivya Soma Mashe等艺术家推动纸本个人创作。红褐墙与稻米白几何是仪式语境的重要机制，但当代作品的综合色、叙事和作者身份已扩展。","recognition":"中心环舞、婚礼方框、基线叙事或当代满幅场景按仪式与艺术家选择；圆、三角、短线组成的人物和动物须保留动作逻辑，不当作任意图标库；仪式墙画以稻米白和红褐泥底为主，当代纸布可有其他综合色；传统墙面完全平面，当代材料保留真实纸布光，不添加体积投影；泥墙、稻米浆、竹笔、纸或画布、商业综合色和手工不均。","influencedBy":"瓦尔利社群仪式、婚礼墙画、农耕生活、泥墙与稻米浆材料","influenced":"印度原住民当代艺术、纸本市场、公共设计和社群文化表达","sources":[{"label":"Google Arts & Culture：Warli painting","url":"https://artsandculture.google.com/entity/warli-painting/m02qv8mm"},{"label":"Wikipedia：Warli painting","url":"https://en.wikipedia.org/wiki/Warli_painting"}]},"orphism":{"summary":"奥费主义是阿波利奈尔1912年前后用于德劳内夫妇、库普卡等综合色导向作品的术语，而非成员稳定的正式团体。综合色同时对比、光感和节奏推动立体主义走向抽象，但同心圆盘只是高识别个案，不能覆盖所有相关艺术家。","recognition":"同心圆弧、交叠色盘与旋转节奏；分割圆形、棱面与透明综合色片；高纯度互补色与光谱式渐变；色彩自身明度制造发光与运动；平面油彩、综合色叠层与清楚几何边缘。","influencedBy":"立体主义、分色与同时对比综合色理论、现代城市和电光经验","influenced":"综合色抽象、同步主义、包豪斯综合色教学与欧洲几何抽象","sources":[{"label":"Tate：Orphism","url":"https://www.tate.org.uk/art/art-terms/o/orphism"},{"label":"MoMA：Orphism","url":"https://www.moma.org/collection/terms/orphism"}]},"barbizon-school":{"summary":"巴比松画派是19世纪中叶在枫丹白露森林周边工作的一批法国风景画家的宽泛称呼，成员和风格边界并不固定。直接写生、乡村劳动和低调土色重要，但许多作品仍在画室完成；它既非统一宣言团体，也不等同后来印象派的户外即时综合色。","recognition":"低地平线、林地近景与自然观察式平衡；松动自然轮廓、综合色块与直接地貌结构；土褐、橄榄绿、灰蓝与低饱和综合色；阴天或黄昏的自然综合色光；可见油画笔触、薄厚交替与画布颗粒。","influencedBy":"17世纪荷兰风景、英国风景画、浪漫主义自然观、学院风景传统及法国乡村社会变化","influenced":"法国现实主义风景、印象主义的户外实践、欧洲与美国的自然主义画家群体","sources":[{"label":"The Met：The Barbizon School","url":"https://www.metmuseum.org/essays/the-barbizon-school-french-painters-of-nature"},{"label":"National Gallery：The Barbizon school","url":"https://www.nationalgallery.org.uk/artists/barbizon-school"}]},"art-informel":{"summary":"不定形艺术是评论家米歇尔·塔皮耶等人在战后用于欧洲多种非几何抽象的宽泛术语，强调手势、材料、偶发和非预设形体。它不是正式团体，也不等于塔希主义、物质绘画或所有欧洲抽象表现。","recognition":"无中心满幅、即兴扩散与不稳定密度；不规则斑块、手势线与未封闭形；土色、黑白与局部高纯度综合色；平面画面光，以颜料厚薄产生阴影；厚涂、刮擦、滴洒与砂质粗糙表面。","influencedBy":"超现实主义自动技法、战前抽象、战争创伤、存在主义及对学院和几何秩序的反拨","influenced":"塔希主义、物质绘画、欧洲抒情抽象和战后跨大西洋抽象讨论","sources":[{"label":"Tate：Art informel","url":"https://www.tate.org.uk/art/art-terms/a/art-informel"},{"label":"Guggenheim：Art Informel","url":"https://www.guggenheim.org/artwork/movement/art-informel"}]},"purism":{"summary":"纯粹主义由奥赞方和勒·柯布西耶在一战后法国提出，以标准化日用品、稳定比例和清楚综合色关系批评他们所理解的晚期立体主义装饰化。它包含绘画、杂志和建筑理论，不等于所有机械对象都被画成无痕白灰几何。","recognition":"稳定正交网格、重叠轮廓与清楚比例秩序；净化几何体、精确曲线与机械对象式轮廓；白、灰、赭、蓝与低饱和综合色；均匀冷静光与简化体积阴影；平滑薄油层、清楚硬边与少见笔触。","influencedBy":"立体主义、战后秩序诉求、工业标准化、古典比例和现代机械文化","influenced":"勒·柯布西耶建筑与出版、法国现代主义、精确主义及现代静物设计","sources":[{"label":"Tate：Purism","url":"https://www.tate.org.uk/art/art-terms/p/purism"},{"label":"MoMA：Purism","url":"https://www.moma.org/collection/terms/purism"}]},"pointillism":{"summary":"点彩主义是以细小综合色点并置实现观看距离上光学混合的绘画技法，常与修拉、希涅克及新印象主义相关。它是Divisionism的一种较规则点触实践，而非二者完全同义；点的大小、密度和底色随艺术家变化。","recognition":"稳定整体轮廓与均匀点触覆盖；规则小圆点在观看距离中合成清楚体积；高纯度互补色点与光学综合色；以点色明度而非连续灰阶表现日光；细小规则油彩点、干燥表面与可见画布。","influencedBy":"综合色科学与光学理论、印象主义、新印象主义及修拉的系统实验","influenced":"新印象主义、意大利分色主义、现代印刷与数字综合色采样的类比接受","sources":[{"label":"Tate：Pointillism","url":"https://www.tate.org.uk/art/art-terms/p/pointillism"},{"label":"The Met：Georges Seurat","url":"https://www.metmuseum.org/essays/georges-seurat-1859-1891-and-neo-impressionism"}]},"orientalist-painting":{"summary":"东方主义绘画是欧洲艺术家对北非、西亚及所谓‘东方’的再现类别，而非当地艺术风格。旅行观察、学院想象、殖民权力和性别凝视交织其中；精密织物、戏剧光和异域场景必须被标为欧洲建构，不能当作中立地域记录。","recognition":"按具体作品区分旅行观察、历史想象、室内或风景构图，不把殖民凝视当地域模板；学院写实、装饰细节和人物姿态须说明作者与再现关系，避免类型化匿名人物；综合色来自具体作品和欧洲画家选择，不设宝石色与土金色的‘东方’公式；日光、室内光和戏剧光按作品处理，不把综合色反差声称为地区自然属性；油画、纸本、摄影参照、织物与建筑细节作为欧洲再现媒介而非民族真实性证明。","influencedBy":"欧洲殖民扩张、旅行与考古、学院历史画、浪漫主义、摄影及对伊斯兰世界的想象","influenced":"欧洲大众对北非西亚的刻板图像、殖民展览与旅游传播，并成为后殖民视觉批评的重要对象","sources":[{"label":"Tate：Orientalism","url":"https://www.tate.org.uk/art/art-terms/o/orientalism"},{"label":"The Met：Orientalism","url":"https://www.metmuseum.org/essays/orientalism-in-nineteenth-century-art"}]},"kinetic-art":{"summary":"动力艺术把真实运动、机械驱动、空气作用、光变化或观众参与作为作品结构；其先例可追溯到20世纪早期，1950至1960年代集中发展。它不同于未来主义在静态图像中描绘速度，也不限于悬挂式活动雕塑。","recognition":"真实运动、观看路径、悬置平衡或光序列共同形成时间结构；可动杆件、旋转模块、机械装置、空气驱动部件或变化光形；材料本色、黑白和有限强调色，也可由光产生综合色变化；环境光、移动投影、反射和装置自发光随时间改变；金属、塑料、线材、电机、灯具与清楚可见的活动连接。","influencedBy":"构成主义和达达的机械实验、莫霍利—纳吉、考尔德等先例，以及战后技术和参与式艺术","influenced":"欧普艺术、光与空间、互动装置、机械与电子艺术","sources":[{"label":"Tate：Kinetic art","url":"https://www.tate.org.uk/art/art-terms/k/kinetic-art"},{"label":"Wikipedia：Kinetic art","url":"https://en.wikipedia.org/wiki/Kinetic_art"}]},"secessionism":{"summary":"分离派是19世纪末欧洲多地脱离官方学院体系的运动总称，其共同视觉倾向是平面化、装饰性边框和艺术门类整合，但维也纳、慕尼黑、柏林等分支并无单一固定样式。","recognition":"非对称或轴线式装饰框架、图文整合与清楚平面分区；自然曲线与几何简化并存，轮廓平整且装饰节点受控；低至中饱和综合色、黑白、金与少量深色强调；平面综合色光，不使用写实电影式投影；平涂印刷、壁面综合色、金属或综合工艺的清楚边缘。","influencedBy":"官方沙龙与学院体制争议、国际展览、自然主义、印象主义、象征主义和艺术门类改革","influenced":"欧洲现代展览制度、维也纳现代主义、新艺术与多种先锋团体的组织模式","sources":[{"label":"Tate：Secession","url":"https://www.tate.org.uk/art/art-terms/s/secession"},{"label":"Wikipedia：Secession (art)","url":"https://en.wikipedia.org/wiki/Secession_(art)"}]},"divisionism":{"summary":"分色主义指将综合色分离为点、短线或方向性笔触，使其在观看中混合的理论与方法；法国新印象主义和意大利Divisionismo并不相同。意大利艺术家常把分色笔触用于象征、社会和政治题材，因此不能仅写成更自由的点彩。","recognition":"象征或社会场景的稳定结构与方向性分色笔触；由短线或点划组成的轮廓和体积；分离的高纯度综合色与互补色；以方向性分色笔触建立发光感；细短油彩线点、画布纹理与综合色振动。","influencedBy":"19世纪综合色与光学理论、法国新印象主义、意大利社会象征主题及印象主义实验","influenced":"意大利未来主义的综合色与运动研究、象征主义及欧洲现代综合色绘画","sources":[{"label":"National Gallery：Divisionism","url":"https://www.nationalgallery.org.uk/paintings/glossary/divisionism"},{"label":"Wikipedia：Divisionism","url":"https://en.wikipedia.org/wiki/Divisionism"}]},"flemish-baroque":{"summary":"佛兰德巴洛克涵盖17世纪南尼德兰的宗教、宫廷、肖像、风景、静物和风俗画。鲁本斯的旋转群组和丰厚体积极具代表性，却不能覆盖凡·戴克、约尔丹斯、斯奈德斯等人的专门类型与工作室协作。","recognition":"旋转群组、强对角线与饱满画面边缘；丰厚体积、连续曲线与强烈动作联结；深红、金、综合色肉色、深绿与黑；温暖聚光、深暗背景与明亮反射；多层油画罩染、厚亮笔触与丝绒金属质感。","influencedBy":"意大利文艺复兴与巴洛克、天主教改革、哈布斯堡宫廷、安特卫普市场和尼德兰油画技术","influenced":"欧洲宫廷肖像、巴洛克宗教与历史画、英国和法国绘画","sources":[{"label":"The Met：Peter Paul Rubens","url":"https://www.metmuseum.org/essays/peter-paul-rubens-1577-1640-and-anthony-van-dyck-1599-1641"},{"label":"National Gallery：Flemish Baroque","url":"https://www.nationalgallery.org.uk/paintings/explore-the-paintings/flemish"}]},"rayonism":{"summary":"辐射主义由拉里奥诺夫和冈察洛娃在1910年代初发展，以物体之间反射和交叉的‘光线’分解形体，并在宣言中走向非再现。它的射线并非物理光学记录，也不能把所有俄罗斯先锋斜线抽象都归为辐射主义。","recognition":"多方向光束交叉、中心爆发与棱面碎裂；锐利射线、细长三角与交错直线；高纯度红蓝黄绿与综合色交叠；光束本身成为结构并切割形体；油彩硬边、短线笔触与透明综合色叠压。","influencedBy":"立体主义、未来主义、综合色分割、俄罗斯新原始主义和现代光学想象","influenced":"俄罗斯非客观绘画、未来主义舞台与更广泛的先锋抽象","sources":[{"label":"Tate：Rayonism","url":"https://www.tate.org.uk/art/art-terms/r/rayonism"},{"label":"Guggenheim：Rayonism","url":"https://www.guggenheim.org/artwork/movement/rayonism"}]},"glasgow-style":{"summary":"格拉斯哥风格约在1890至1915年由麦金托什及格拉斯哥四人组等发展，以高挑矩形网格、紧绷直线、抽象玫瑰和受控柔曲线形成冷静而纤细的装饰体系。","recognition":"高挑矩形框架、严格竖向节奏、轴线平衡与局部偏心；细长直线、方格、抽象玫瑰与极少柔曲线的对照；黑白、银灰、浅紫、综合色绿与克制粉色；均匀平面光，强调线框和色面边界；平涂纸面、铅条玻璃、细木作与金属线性节点。","influencedBy":"Arts and Crafts、Celtic Revival、日本艺术的现代主义接受、Art Nouveau和格拉斯哥工业城市","influenced":"维也纳分离派、Art Nouveau、现代室内与家具设计及英国艺术教育","sources":[{"label":"The Met：Heilbrunn Timeline of Art History","url":"https://www.metmuseum.org/toah/"},{"label":"National Gallery：Art history","url":"https://www.nationalgallery.org.uk/paintings/learn-about-art"}]},"hudson-river-school":{"summary":"哈德逊河画派是后世对19世纪美国风景画家网络的称呼，题材从哈德逊河谷扩展到新英格兰、美国西部与南美。精细全景和崇高光线常与国家扩张、旅游和保护意识并存，也必须说明原住民族土地被写成‘荒野’的殖民视角。","recognition":"宽阔全景、层层大气远景与稳定地平线；精确地貌轮廓、微小细节与宏大尺度关系；综合色绿褐、天空蓝与日落金；清澈空气光、远景雾化与集中日光；细腻油画罩染、平滑表面与少量细笔纹理。","influencedBy":"欧洲浪漫主义风景、如画与崇高理论、美国地理考察、旅游和定居扩张","influenced":"美国风景画、Luminism、国家公园视觉与环境保护图像，同时受到去殖民批评","sources":[{"label":"The Met：The Hudson River School","url":"https://www.metmuseum.org/essays/the-hudson-river-school"},{"label":"National Gallery of Art：Hudson River School","url":"https://www.nga.gov/collection/paintings/hudson-river-school.html"}]},"dutch-golden-age-painting":{"summary":"17世纪荷兰共和国绘画在城市市场中形成肖像、风景、海景、风俗、静物和历史画的高度分化。窗侧光、综合色克制和精细材质是部分路线，伦勃朗、维米尔、哈尔斯及众多专门画家的笔触和光线并不统一；‘黄金时代’名称也需面对殖民贸易背景。","recognition":"稳定室内或风景空间、精密日常焦点与清楚尺度；具体轮廓、细腻材质差异与克制动作；土褐、灰蓝、综合色黑白与局部高纯度色；窗侧自然光、柔和暗部与可追踪反射；细腻油画罩染、木板或画布和精确表面描绘。","influencedBy":"尼德兰绘画传统、宗教与市场结构变化、城市财富、科学观察、全球贸易和殖民体系","influenced":"欧洲风俗、风景、肖像和静物画，现代现实主义与摄影式观看","sources":[{"label":"The Met：Dutch Golden Age","url":"https://www.metmuseum.org/essays/dutch-painting-in-the-age-of-rembrandt-and-vermeer"},{"label":"Rijksmuseum：17th-century painting","url":"https://www.rijksmuseum.nl/en/rijksstudio/timeline-dutch-history/1600-1700-the-dutch-golden-age"}]},"precisionism":{"summary":"精确主义是后世对两次世界大战之间美国一批以清晰几何、锐利裁切和压低笔触描绘工业、城市与乡村建筑的艺术家所用名称。它没有正式组织或宣言，查尔斯·希勒、德穆斯、奥基夫等人的主题和抽象程度也不同。","recognition":"工业垂直水平轴、近距裁切与寂静留空；锐利轮廓、圆筒与直角机械体积；冷灰、砖红、米白与克制蓝；清澈硬光与精确投影；平滑油层、喷绘般渐变与无痕表面。","influencedBy":"摄影、立体主义、纯粹主义、美国工业化、摩天楼和广告视觉","influenced":"美国现代绘画与摄影、工业图像、硬边和波普对商品建筑的再认识","sources":[{"label":"The Met：Precisionism","url":"https://www.metmuseum.org/essays/precisionism"},{"label":"Whitney Museum：Precisionism","url":"https://whitney.org/collection/works?q%5Bclassification_cont%5D=Precisionism"}]},"spatialism":{"summary":"空间主义由卢齐奥·丰塔纳等人在1947年后的一系列宣言中推动，主张将真实空间、时间、运动和新技术带入艺术。切割和穿孔画布是丰塔纳的重要实践，但霓虹、环境和陶瓷实验说明运动不等于单色画布上的一道切口。","recognition":"单色场、单一切口或穿孔与大面积负空间；锋利切缝、圆孔与真实画布开口；白、红、蓝、黑或金属单色；真实环境光在切口内产生阴影；被切割或穿孔的画布、单色涂层与裸露边缘。","influencedBy":"意大利未来主义、现代科学与航空航天、战后材料实验、雕塑和环境艺术","influenced":"极简、观念艺术、环境与装置艺术，以及对绘画支持体的后续研究","sources":[{"label":"Tate：Spatialism","url":"https://www.tate.org.uk/art/art-terms/s/spatialism"},{"label":"Guggenheim：Spatialism","url":"https://www.guggenheim.org/artwork/movement/spatialism"}]},"der-blaue-reiter":{"summary":"蓝骑士是康定斯基、弗兰茨·马克等人围绕展览和1912年《蓝骑士年鉴》形成的短期网络，并非样式统一的画派。精神性、音乐类比和综合色自主性重要，但成员从具象综合色到抽象的路径差异很大。","recognition":"斜向节奏、色块交错与趋向抽象的开放空间；简化轮廓、弧线动势与分解体积；高纯度蓝黄红绿与主观综合色；综合色明度而非自然光塑形；可见油画笔触、透明与不透明色层并置。","influencedBy":"表现主义、野兽派、民间与儿童艺术、音乐、神智学，以及当时对非欧洲艺术的选择性接受","influenced":"抽象艺术、包豪斯、欧洲表现主义和现代综合色理论","sources":[{"label":"Tate：Der Blaue Reiter","url":"https://www.tate.org.uk/art/art-terms/d/der-blaue-reiter"},{"label":"Lenbachhaus：The Blue Rider","url":"https://www.lenbachhaus.de/en/discover/the-blue-rider"}]},"zero-group":{"summary":"ZERO由海因茨·马克、奥托·皮内和君特·于克尔1957年在杜塞尔多夫发起，并迅速连接欧洲多地艺术家。单色、光、反射、运动、火和重复是不同实践，不应把银白点阵当作统一样式；‘归零’也与战后重启语境相关。","recognition":"重复序列、单色场、光学振动与开放空间；规则点阵、浮起模块与反光小单元；白、银、黑与极少纯色；定向光、反射和真实阴影参与构图；铝、镜面、单色涂层与工业网面。","influencedBy":"战后重建、技术材料、单色绘画、动力艺术、空间主义和对主观手势的反拨","influenced":"光与空间、动力艺术、极简、环境和媒介装置","sources":[{"label":"Guggenheim：ZERO","url":"https://www.guggenheim.org/exhibition/zero-countdown-to-tomorrow-1950s-60s"},{"label":"ZERO Foundation","url":"https://zerofoundation.de/en/zero/"}]},"magic-realism-painting":{"summary":"视觉艺术中的‘魔幻现实主义’由弗朗茨·罗1925年提出，用于描述表现主义之后重新关注物体世界而又显得陌生的绘画，历史含义不同于后来拉丁美洲文学魔幻现实主义。它与新客观主义部分重叠，不能泛指任何写实画中的超自然事件。","recognition":"稳定日常空间、异常静止与清楚物体间隔；精确轮廓、略带陌生化的坚实体积；低饱和自然色配冷暖不协调节点；清晰均匀且略显不自然的定向光；平滑油层、细密表面与压低笔触。","influencedBy":"表现主义反拨、形而上绘画、旧大师技法、摄影般清晰度和魏玛时期具象转向","influenced":"新客观主义接受、20世纪谜样具象绘画，以及后来同名文学术语造成的跨媒介混用","sources":[{"label":"Tate：Magic realism","url":"https://www.tate.org.uk/art/art-terms/m/magic-realism"},{"label":"Wikipedia：Magic realism (visual art)","url":"https://en.wikipedia.org/wiki/Magic_realism_(visual_art)"}]},"nazarene-movement":{"summary":"拿撒勒派由1809年成立的圣路加兄弟会及罗马艺术家社群发展，希望以虔敬共同生活和对佩鲁吉诺、拉斐尔等早期文艺复兴的学习改革学院艺术。清晰轮廓和纯净色彩是部分倾向，但壁画委托、宗教理想和德国民族主义更是历史核心。","recognition":"清楚叙事中心、稳定群组与浅层古典空间；清晰轮廓、克制理想比例与简洁衣褶；清澈矿物色、暖肤色与综合色背景；均匀纯净光，抑制戏剧性阴影；湿壁画或平滑油层、细线和少见笔触。","influencedBy":"Durer、Perugino与拉斐尔早期作品、德国浪漫主义、宗教复兴和对学院制度的反拨","influenced":"Pre-Raphaelites、19世纪宗教壁画、德国历史画和中世纪复兴运动","sources":[{"label":"The Met：Heilbrunn Timeline of Art History","url":"https://www.metmuseum.org/toah/"},{"label":"National Gallery：Art history","url":"https://www.nationalgallery.org.uk/paintings/learn-about-art"}]},"les-nabis":{"summary":"纳比派是1888年前后在巴黎形成的松散艺术家团体，成员在绘画、版画、海报、屏风、壁画和舞台设计中强调画面平面、主观综合色与装饰整体。浅空间和硬边色面重要，但博纳尔、维亚尔、德尼等人的题材与笔触差异明显。","recognition":"浅空间、装饰性裁切与大色面不对称平衡；简化硬边轮廓、平面色区与图案化形体；综合色黄绿、紫、赭红与深色轮廓；平面综合色关系取代写实光影；哑光平涂、纸板或画布与装饰性笔触。","influencedBy":"高更与Pont-Aven综合主义、日本版画、象征主义、装饰艺术和戏剧出版网络","influenced":"20世纪装饰绘画、平面设计、现代室内综合色和野兽派前史","sources":[{"label":"The Met：The Nabis and Decorative Painting","url":"https://www.metmuseum.org/essays/the-nabis-and-decorative-painting"},{"label":"Tate：Nabis","url":"https://www.tate.org.uk/art/art-terms/n/nabis"}]},"arte-povera":{"summary":"贫穷艺术由热尔马诺·切兰特1967年命名，涵盖意大利艺术家以日常、工业、有机和能量过程质疑商品、制度与技术现代化的不同实践。‘贫穷’指策略而非只用天然廉价材料，作品也可使用钢、霓虹和复杂装置。","recognition":"开放组合、重力关系与非纪念尺度；简单堆叠、张力、折叠与材料原形；土色、中性色与材料本色；自然展示光和真实接触阴影；石、木、布、土与非贵重工业材料。","influencedBy":"意大利战后工业化、政治抗议、达达、Fontana、物质与行为艺术及剧场理论","influenced":"装置、过程、生态和观念艺术，以及意大利当代艺术国际化","sources":[{"label":"Tate：Arte Povera","url":"https://www.tate.org.uk/art/art-terms/a/arte-povera"},{"label":"Guggenheim：Arte Povera","url":"https://www.guggenheim.org/artwork/movement/arte-povera"}]},"die-bruecke":{"summary":"桥社于1905年在德累斯顿成立，1911年前后转向柏林，1913年解散。成员通过绘画、木刻和共同工作追求直接表现，但城市、人体、风景和版画差异显著；酸性综合色、尖角人体和木刻粗线不能成为每件作品的固定配方。","recognition":"近距压缩、强对角线与不稳定画面边缘；尖锐粗轮廓、木刻式硬折与拉长比例；酸性黄绿、朱红、蓝与黑色轮廓；高反差平面色而非连续自然明暗；粗砺油彩、木刻刀痕与裸露底材。","influencedBy":"凡高、高更、蒙克、德国版画、Jugendstil，以及对非洲和大洋洲艺术的现代主义挪用","influenced":"德国表现主义、现代版画、新表现主义及20世纪反学院人物画","sources":[{"label":"Tate：Die Bruecke","url":"https://www.tate.org.uk/art/art-terms/d/die-brucke"},{"label":"Bruecke Museum：The artists","url":"https://www.bruecke-museum.de/en/collection/artists/"}]},"social-realism":{"summary":"社会现实主义是20世纪尤其两次世界大战之间在多国出现的广义倾向，以劳动、贫困、不平等和政治冲突为题，并非风格统一的正式组织。它可采用绘画、壁画、版画、摄影与插图，也必须与国家规定、强调理想化社会主义建设的社会主义现实主义区分。","recognition":"群体行动、直接视点与社会环境形成可读叙事，也可采用孤立人物或纪实片段；未经理想化的身体、具体劳动姿态和从写实到概括的轮廓；综合色服从地点和媒介，土红、灰蓝、褐与有限强调色只是常见选择；自然光、硬侧光或公共壁画明度分区保持情境信息可读；油画、壁画、木刻或石版、摄影颗粒和廉价印刷纸。","influencedBy":"19世纪现实主义、工人运动、经济危机、新闻与纪实文化、墨西哥壁画及不同国家的左翼艺术网络","influenced":"美国新政艺术、政治版画、纪实传统和后续社会介入艺术","sources":[{"label":"Tate：Social realism","url":"https://www.tate.org.uk/art/art-terms/s/social-realism"},{"label":"Wikipedia：Social realism","url":"https://en.wikipedia.org/wiki/Social_realism"}]},"socialist-realism":{"summary":"社会主义现实主义在苏联1932年艺术团体重组后逐步成为官方方法，并于1934年作家大会获得规范表述，随后在不同社会主义国家产生各异实践。积极英雄、劳动建设和清楚叙事常见，但媒介、国家、时期和政治压力不能被统一成仰视红金宣传画。","recognition":"公共壁画、绘画、雕塑、电影或海报按国家、机构和任务组织叙事，不固定上升对角线；人物可理想化、类型化或观察性表现，服饰、劳动和身份必须具体准确；红金蓝、自然综合色、黑白或地方综合色随国家、时期和媒介变化；纪念光、自然光、舞台光或印刷明度按作品处理，不统一轮廓辉光；油画、壁画、青铜、石、摄影电影和印刷材料及真实制作痕迹。","influencedBy":"19世纪现实主义、革命艺术、苏联文化政策、国家委托和大众传播","influenced":"苏联及相关国家的绘画、雕塑、建筑、电影和海报，同时成为非官方艺术反应与历史批评对象","sources":[{"label":"Tate：Socialist realism","url":"https://www.tate.org.uk/art/art-terms/s/socialist-realism"},{"label":"MoMA：Socialist Realism","url":"https://www.moma.org/collection/terms/socialist-realism"}]},"lyrical-abstraction":{"summary":"抒情抽象是跨时期且语境不一的术语：战后法国用法常指与几何抽象相对的自由抽象，1960年代末美国同名展览则回应极简和形式主义。流动线条、透明色层和留白只是部分路线，不能写成一个连续国际运动。","recognition":"开放流动场、长线联结与呼吸式留空；书写性弧线、柔边色块与透明叠层；高纯度综合色配大面积中性底；综合色透明度形成内发光层次；稀释油彩或丙烯、泼洒与柔化边缘。","influencedBy":"超现实主义自动技法、康定斯基、战后抽象、Art Informel，以及美国对极简和后绘画性抽象的反应","influenced":"欧洲和美国的自由抽象、综合色场与后续当代抽象绘画","sources":[{"label":"Tate：Lyrical abstraction","url":"https://www.tate.org.uk/art/art-terms/l/lyrical-abstraction"},{"label":"Guggenheim：Lyrical Abstraction","url":"https://www.guggenheim.org/artwork/movement/lyrical-abstraction"}]},"tachisme":{"summary":"塔希主义名称来自法语tache（斑点），用于战后法国及欧洲以色斑、滴洒和自发笔触形成的抽象倾向。它通常被置于Art Informel之内，而非与不定形艺术并列的完整同义词；不同艺术家的材料厚度和空间感并不一致。","recognition":"色斑快速分布、非中心平衡与开放边缘；自发斑点、短促手势与液态边界；综合色斑、黑线与纸布底色；平面光，以综合色浓度和叠压建层；泼洒、滴染、擦涂与吸收边缘。","influencedBy":"超现实主义自动技法、战前抽象、书写性线条和战后对预设构图的反拨","influenced":"欧洲自由抽象、抒情抽象和战后手势绘画","sources":[{"label":"Tate：Tachisme","url":"https://www.tate.org.uk/art/art-terms/t/tachisme"},{"label":"Wikipedia：Tachisme","url":"https://en.wikipedia.org/wiki/Tachisme"}]},"aesthetic-movement":{"summary":"唯美主义运动约在1860至1900年的英国强调“为艺术而艺术”，视觉上偏好和谐综合色、非对称日式布局、孔雀综合色与精致室内表面，而非单一绘画技法。","recognition":"非对称日式平衡、装饰边框、扁平图案与精心陈列的留空；细长轮廓、扇面或格架结构、精致植物曲线与克制体积；孔雀蓝绿、金、橄榄绿、综合色黄与深色木质综合色；柔和室内光、金属微光与低反差综合色层；壁纸、陶瓷、漆面木作、织物与精细印刷表面。","influencedBy":"Pre-Raphaelites、Japonisme、Whistler、古典与文艺复兴艺术、工业时代室内消费和艺术自治论","influenced":"Art Nouveau、Arts and Crafts、dandyism、现代室内设计和对风格与生活的整合","sources":[{"label":"The Met：Heilbrunn Timeline of Art History","url":"https://www.metmuseum.org/toah/"},{"label":"National Gallery：Art history","url":"https://www.nationalgallery.org.uk/paintings/learn-about-art"}]},"vienna-secession":{"summary":"维也纳分离派约在1897至1914年以几何化装饰、黄金综合色、方格与圆形模块、宽阔留白和艺术整体观区别于鞭状曲线主导的新艺术。","recognition":"严格轴线或方格分区、宽阔留白、连续边带与徽章式焦点；圆、方格、棋盘模块、几何化植物形与精确硬边；黑白、金、深蓝、综合色绿与少量红；均匀平面光与局部金色反射，不使用自然主义塑形；平版印刷、金箔、马赛克、陶瓷与精密工艺表面。","influencedBy":"维也纳学院体制争议、英国工艺美术、象征主义、国际新艺术与现代展览设计","influenced":"维也纳工坊、奥地利现代建筑与平面设计、欧洲总体艺术观念","sources":[{"label":"Leopold Museum：Vienna 1900","url":"https://www.leopoldmuseum.org/en/collection/vienna-1900"},{"label":"Wikipedia：Vienna Secession","url":"https://en.wikipedia.org/wiki/Vienna_Secession"}]},"utrecht-caravaggism":{"summary":"乌得勒支卡拉瓦乔主义指一批曾在罗马工作的荷兰画家将Caravaggio及追随者的近距离人物、现场光源和平民类型带回乌得勒支的地区网络。烛光半身音乐家只是高识别题材，宗教委托、日光与各画家色彩差异同样重要。","recognition":"近距离半身群组、单一烛光焦点与深暗背景；强烈手势、具体体积与硬边明暗转折；黑、暖褐、暗红与烛光金黄；可见光源式强明暗对照和深阴影；吸光油层、局部厚亮与粗织画布。","influencedBy":"Caravaggio与罗马追随者、荷兰历史画、城市市场、宗教委托和意大利旅行","influenced":"荷兰黄金时代绘画、人工光源场景、风俗画和北方巴洛克","sources":[{"label":"The Met：Heilbrunn Timeline of Art History","url":"https://www.metmuseum.org/toah/"},{"label":"National Gallery：Art history","url":"https://www.nationalgallery.org.uk/paintings/learn-about-art"}]},"matter-painting":{"summary":"物质绘画是战后欧洲将砂、灰泥、焦油、布和厚颜料纳入画面的材料性实践，常与Art Informel相交。核心是支持体、裂缝、孔洞和堆积的真实物质作用，而非任何厚涂绘画；塔皮埃斯、布里等人的方法也不可统一。","recognition":"厚重表面场、裂缝方向与材料堆积形成结构；凸起团块、刮槽、孔洞与不规则边缘；土褐、灰黑、白与材料本色；擦边侧光强化高低起伏和阴影；砂、灰泥、厚颜料、布与物质性裂纹。","influencedBy":"拼贴与综合材料、达达、战争废墟经验、Art Informel和对传统画面平整性的反拨","influenced":"欧洲材料艺术、Arte Povera、装置和当代绘画对支持体与损耗的研究","sources":[{"label":"Tate：Matter painting","url":"https://www.tate.org.uk/art/art-terms/m/matter-painting"},{"label":"Wikipedia：Matter painting","url":"https://en.wikipedia.org/wiki/Matter_painting"}]},"neo-geo":{"summary":"Neo-Geo是对1980年代一批重新使用几何抽象、现成品与企业图形的艺术家的评论和市场标签，也常与模拟主义讨论相连。它不是每位艺术家认同的正式团体，光滑网格与靶形须结合消费、价值与符号循环的批判。","recognition":"大尺度规则网格、靶形或重复企业符号；硬边圆环、方格与工业化抽象单元；高纯度红黄蓝、黑白或光亮商业综合色；均匀画面光或商品展示式反光；光滑丙烯、金属、层压板与无手工痕迹表面。","influencedBy":"Minimalism、Op Art、Pop Art、概念艺术、后现代模拟理论和1980年代艺术市场","influenced":"当代挲用艺术、商品美学批评、数字几何图像和品牌符号研究","sources":[{"label":"Tate：Art terms","url":"https://www.tate.org.uk/art/art-terms"},{"label":"MoMA：Art terms","url":"https://www.moma.org/collection/terms"}]},"new-objectivity":{"summary":"新客观主义名称来自古斯塔夫·哈特劳布1925年展览，用于魏玛德国对表现主义作出反应的多种具象实践。尖锐社会讽刺与冷静古典化是两条常被区分的路线，因此疏离肖像、硬光和无痕表面不能概括全部艺术家。","recognition":"冷静正面或三分之四视点、清楚间隔与疏离空间；锐利具体轮廓、坚实体积与略带夸张的细节；低饱和冷暖分区、综合色灰与局部强色；冷硬均匀光或直接侧光；平滑薄油层、精确边缘与少见笔触。","influencedBy":"第一次世界大战、达达、表现主义反拨、摄影、社会政治危机和旧大师绘画","influenced":"20世纪具象绘画、社会批判图像、魔幻现实主义术语及现代摄影","sources":[{"label":"Tate：New Objectivity","url":"https://www.tate.org.uk/art/art-terms/n/new-objectivity"},{"label":"The Met：New Objectivity","url":"https://www.metmuseum.org/essays/new-objectivity"}]},"nouveau-realisme":{"summary":"新现实主义是1960年前后法国形成的艺术运动，以挪用消费物、压缩物、撕裂海报、积聚和行动痕迹直接处理现实材料；它不是19世纪自然主义或一般写实绘画。","recognition":"现成材料的积聚、切割或压缩构成非中心物质场；撕裂、堆积、包裹、压扁与机械重复形成直接轮廓；消费综合色、工业综合色、纸张褪色与材料本色并置；展厅方向光显示真实厚度、阴影和反射；撕裂海报、金属废料、塑料、包装与可见固定痕迹。","influencedBy":"达达现成品、城市消费与广告、工业废物、行为和对抽象绘画的反应","influenced":"欧洲物件艺术、行为与装置、消费文化批评，并与波普艺术形成跨大西洋对话","sources":[{"label":"Tate：Nouveau realisme","url":"https://www.tate.org.uk/art/art-terms/n/nouveau-realisme"},{"label":"Centre Pompidou：Nouveau Realisme","url":"https://www.centrepompidou.fr/en/ressources/personne/cKx4XX"}]},"metaphysical-painting":{"summary":"形而上绘画由德·基里科、卡拉等人在一战前后发展，以空旷广场、雕像、人体模型和不合逻辑并置制造谜样静止。长阴影和拱廊很有辨识度，但室内静物与不同画家阶段同样重要，不能只生成一种黄昏城市。","recognition":"空旷广场、深透视、孤立形体与不合逻辑的尺度关系；硬边古典体块、实体模型式轮廓与长直阴影；赭黄、砖红、墨绿、深蓝与灰白；低角度硬光制造超长阴影和寂静感；平滑油层、石膏木质般哑光表面。","influencedBy":"古典建筑与雕塑、象征主义、尼采思想、意大利城市空间和现代商品物件","influenced":"超现实主义、新客观主义部分路线和20世纪谜样具象绘画","sources":[{"label":"Tate：Metaphysical art","url":"https://www.tate.org.uk/art/art-terms/m/metaphysical-art"},{"label":"MoMA：Metaphysical Art","url":"https://www.moma.org/collection/terms/metaphysical-art"}]},"vorticism":{"summary":"漩涡主义是温德姆·刘易斯等人围绕《BLAST》杂志形成的英国先锋团体，以机器时代的角状结构综合立体主义与未来主义。战争中断了活动，绘画、雕塑、文字和排版并不共享一种漩涡中心构图。","recognition":"旋涡式中心、强斜线与机械块面压缩；锐角折线、楔形与硬边机械几何；黑、白、赭、深蓝与克制强色；硬边明度块切分，不使用柔和综合色；平涂油彩、墨线与粗糙印刷表面。","influencedBy":"立体主义、未来主义、英国工业都市、现代雕塑和先锋杂志文化","influenced":"英国现代主义、战争艺术、实验排版和后续几何机械图像","sources":[{"label":"Tate：Vorticism","url":"https://www.tate.org.uk/art/art-terms/v/vorticism"},{"label":"The Met：Vorticism","url":"https://www.metmuseum.org/essays/vorticism"}]},"academic-art":{"summary":"学院艺术指欧洲及其殖民和国际学院体系通过素描、历史题材等级、古典范本、竞赛与沙龙建立的教学和评价规范，而非一种无痕写实画风。不同学院、国家和世纪对综合色、题材和技法要求并不一致。","recognition":"金字塔或轴线结构、清楚叙事高潮与完整空间层级；理想化解剖、平滑体积与受控姿态；综合色肉色、土色、深红蓝与克制金色；工作室式定向光与连续明暗塑形；多层油画罩染、无痕平滑表面与精细素描底。","influencedBy":"文艺复兴艺术理论、法国与其他国家学院、古典艺术、宫廷和国家文化制度","influenced":"19世纪沙龙、历史画与美术教育，也成为现实主义、印象主义和现代主义反拨对象","sources":[{"label":"Tate：Academic art","url":"https://www.tate.org.uk/art/art-terms/a/academic-art"},{"label":"The Met：The French Academy","url":"https://www.metmuseum.org/essays/the-french-academy-in-rome"}]},"supports-surfaces":{"summary":"Supports/Surfaces是1960年代末法国艺术家围绕画布、木框、染色和展示方式展开的松散网络，名称强调‘支持体/表面’的拆解。成员政治立场与形式不同，未绷画布和重复印染只是部分实践，不应写成统一反绘画风格。","recognition":"画布、边框与悬挂方式被拆分后形成开放结构；未绷画布、折叠条带与重复染色单元；未经调和的综合色、布本色与简单重复色；均匀展示光显示折叠和悬挂阴影；未处理画布、染料、绳、木框与裁切边缘。","influencedBy":"马蒂斯与综合色传统、美国综合色场、结构主义、1968年前后政治和对画架绘画制度的批评","influenced":"法国当代绘画、解构支持体的装置与后续过程性抽象","sources":[{"label":"Tate：Supports/Surfaces","url":"https://www.tate.org.uk/art/art-terms/s/supportssurfaces"},{"label":"Centre Pompidou：Supports-Surfaces","url":"https://www.centrepompidou.fr/en/ressources/personne/cb6XqE"}]},"naturalism":{"summary":"视觉艺术中的自然主义强调可观察环境、身体和社会条件的可信再现，19世纪后半叶常与现实主义相交，并受文学自然主义和科学观影响。它不是一个成员固定的国际画派，也不比现实主义天然更‘照片化’。","recognition":"现场观察式视点、稳定环境关系与非理想化叙事；具体自然比例、可读重量与真实表面差异；低至中饱和自然综合色；连续自然光和可信局部阴影；直接油画笔触、真实织物木石与皮肤表面。","influencedBy":"现实主义、户外写生、摄影、科学与社会观察、左拉等文学自然主义","influenced":"欧洲和美国乡村与社会题材绘画、学院改革和20世纪观察性写实","sources":[{"label":"Tate：Naturalism","url":"https://www.tate.org.uk/art/art-terms/n/naturalism"},{"label":"National Gallery：Naturalism","url":"https://www.nationalgallery.org.uk/paintings/glossary/naturalism"}]},"cobra":{"summary":"CoBrA由1948年宣言与哥本哈根、布鲁塞尔、阿姆斯特丹艺术家网络构成，通过集体实验、自发绘画、出版和对儿童与民间艺术的理想化接受反拨学院与理性抽象。粗黑线、高饱和和怪异生物常见，却不能把成年艺术家的选择说成无技巧儿童画。","recognition":"非中心、即兴扩散与满幅笔势；不规则斑块、手势线与未封闭形；综合色、黑线与局部高纯度对比；平面画面光，以颜料厚薄形成层次；擦涂、滴洒、刮痕与粗糙颜料表面。","influencedBy":"超现实主义自动性、Expressionism、北欧民间与史前图像、儿童艺术的现代主义接受和战后国际主义","influenced":"欧洲战后绘画、Art Informel、集体工作、艺术家出版和新表现主义","sources":[{"label":"Tate：Art terms","url":"https://www.tate.org.uk/art/art-terms"},{"label":"MoMA：Art terms","url":"https://www.moma.org/collection/terms"}]},"polish-poster-school":{"summary":"‘波兰海报学派’是对战后波兰电影、戏剧、马戏与文化海报作者网络的宽泛称呼，在国家委托、印刷限制和相对作者空间中发展隐喻、手绘和个性字体。它不是1945–1989年间所有波兰海报的单一画派，也不等于粗糙纸上的超现实头像。","recognition":"单一隐喻主图、不对称留白与手工标题形成直接焦点；手绘变形、剪贴轮廓、象征替代与不完整边缘；综合色红黑、土色与有限高纯度对比；平面图像光，依靠色块与绘画笔触建层；石版、丝网、拼贴与粗糙纸面。","influencedBy":"波兰战前平面设计、现代绘画与拼贴、国家文化委托、有限印刷资源和学院艺术教育","influenced":"国际文化海报、电影海报、作者平面设计和当代插画式视觉隐喻","sources":[{"label":"Poster Museum Warsaw：Collection","url":"https://postermuseum.pl/en/"},{"label":"MoMA：Polish posters","url":"https://www.moma.org/collection/terms/polish-poster"}]},"plakatstil":{"summary":"Plakatstil（海报风格）又常称Sachplakat（物件海报），在20世纪初德语商业广告中以Lucian Bernhard等人的放大商品、简化形体、纯色底和精简品牌文字取得即时识别。这是特定的广告策略，不覆盖当时所有德国海报，也不必永远只有一个物件和四种颜色。","recognition":"单一放大物形、纯色背景与极少文字的直接层级；粗黑轮廓、平面剪影与无细节的商品式几何；两至四色高对比平涂与纸张底色；平面印刷光，最多保留单级体积色块；石版平涂、纸纹与清楚印刷边缘。","influencedBy":"Jugendstil、日本木版画的平面化接受、彩色石印、现代品牌竞争和街头快速阅读","influenced":"现代广告、品牌海报、Art Deco平面、物件摄影和20世纪视觉识别","sources":[{"label":"Cooper Hewitt：Object poster","url":"https://www.cooperhewitt.org/"},{"label":"Poster House：Plakatstil","url":"https://posterhouse.org/"}]},"dutch-modern-typography":{"summary":"荷兰现代排版是对Piet Zwart、Paul Schuitema、Gerrit Kiljan等设计师将活字、摄影、照片拼贴、斜线和功能信息结合的宽泛描述。它与De Stijl、构成主义和新印刷术交叉，但作者并不共用一种红黑白正交网格。","recognition":"非对称网格、强水平垂直轴与照片文字功能分区；基本几何、粗细线条和直接图形符号；红、黑、白与有限蓝黄；平面印刷光；活字、照片网点、胶印纸与清楚裁切。","influencedBy":"De Stijl、构成主义、新印刷术、摄影蒙版、现代工业委托和活字印刷","influenced":"荷兰与国际信息设计、企业出版、摄影排版、瑞士国际主义与当代编辑设计","sources":[{"label":"Stedelijk Museum：Graphic design","url":"https://www.stedelijk.nl/en/collection/graphic-design"},{"label":"MoMA：Modern typography","url":"https://www.moma.org/collection/terms/typography"}]},"postmodern-swiss-design":{"summary":"后现代瑞士设计指Wolfgang Weingart及其巴塞尔教学圈等从瑞士国际主义内部松动网格、字距、层级和印刷工艺的多种实验。它不是将斜排、多字体和色彩冲突任意堆叠，许多作品仍有严格结构与印刷约束。","recognition":"打破单一网格、斜排、层叠和尺度冲突但保留信息层级；几何碎片、装饰线框与引用式图形；高对比多色、黑白与意外综合色组合；平面印刷光；胶印、照片拼贴、粗细网点与清楚纸面。","influencedBy":"瑞士国际主义、巴塞尔教学、铅字与照相排版实验、punk与new wave文化","influenced":"美国New Wave排版、克兰布鲁克设计、数字编辑设计与当代表现性网格","sources":[{"label":"Cooper Hewitt：Swiss graphic design","url":"https://www.cooperhewitt.org/"},{"label":"Museum fur Gestaltung Zurich：Graphic collection","url":"https://museum-gestaltung.ch/en/collection/graphic-design/"}]},"deconstructivist-graphic-design":{"summary":"解构主义平面设计把阅读顺序、文本权威和稳定网格本身作为拆解对象，以错位基线、碎片化语义、多重入口和不连续层级制造主动阅读。","recognition":"断裂网格、漂移边注、互相遮挡的文本层与多入口阅读；字形切片、尺度突变、透明叠层与不连续线框；黑白灰、复印综合色与少量高饱和冲突色；完全平面化，以透明度和综合色值分开信息层；复印颗粒、胶片叠字、扫描错位与粗细纸张对比。","influencedBy":"后结构主义理论、后现代瑞士排版、克兰布鲁克学院实验、桌面出版和实验杂志","influenced":"1990年代编辑与音乐设计、数字排版、网页视觉和对可读性与作者权威的讨论","sources":[{"label":"Cooper Hewitt：Deconstructivist graphic design","url":"https://www.cooperhewitt.org/"},{"label":"MoMA：Graphic design collection","url":"https://www.moma.org/collection/works?classifications=any&department=Architecture%20and%20Design"}]},"cranbrook-design":{"summary":"克兰布鲁克设计特指1970年代末至1990年代学院语境中的后结构主义平面实验，强调文本解释、多声部版面、透明语义层和理论性阅读，不等同于所有解构排版。","recognition":"页内多声部文本、注释层、图文互释与可追踪但非线性的阅读路径；细线框、透明文字层、尺度对话与受控的密集信息纹理；黑白、低饱和印刷色与少量综合色强调；平面复制光，以透明叠层保持各语义层可辨；半透明纸、胶片、扫描印刷、细网点与学院出版物质感。","influencedBy":"克兰布鲁克教学、后结构主义、后现代瑞士排版、美国New Wave和早期数字工具","influenced":"实验编辑设计、解构主义排版、设计教育和关于作者与读者的讨论","sources":[{"label":"MoMA：Architecture and Design collection","url":"https://www.moma.org/collection/about/curatorial-departments/architecture-design"},{"label":"Cooper Hewitt：Design collection","url":"https://collection.cooperhewitt.org/"}]},"wiener-werkstatte-graphics":{"summary":"维也纳工坊平面是该工艺与设计合作社整体作品的一部分，通过明信片、书籍、广告和包装与家具、纺织品和建筑建立统一品牌。方格和几何花纹常见，但不能代替作者、工艺和客户差异。","recognition":"方形网格、边框与图文一体的全表面秩序；棋盘、重复小几何、细线主体与装饰硬边；黑白配金、朱红或有限综合色；完全平面化；木版、石版、手工纸与清楚套色。","influencedBy":"维也纳分离派、Arts and Crafts、日本版画、几何装饰和整体艺术观","influenced":"Art Deco、现代品牌、平面与产品系统设计及维也纳现代主义","sources":[{"label":"MoMA：Architecture and Design collection","url":"https://www.moma.org/collection/about/curatorial-departments/architecture-design"},{"label":"Cooper Hewitt：Design collection","url":"https://collection.cooperhewitt.org/"}]},"new-typography":{"summary":"新印刷术由Jan Tschichold等人在1920年代系统化，以非对称、功能层级、无衬线体、标准纸张和摄影回应现代传播。它既是历史设计立场也含内部变化，不等于左对齐、红黑和对角线的模板。","recognition":"非对称网格、强左对齐、对角线和照片文字的功能层级；直线、圆、色块与摄影裁切的基本几何；黑白配红或少量原色；平面印刷光；无衬线活字、照片网点与胶印纸。","influencedBy":"构成主义、Bauhaus、De Stijl、摄影蒙版、工业标准化和现代广告","influenced":"瑞士国际主义、现代信息设计、企业出版、导视和数字界面排版","sources":[{"label":"MoMA：Architecture and Design collection","url":"https://www.moma.org/collection/about/curatorial-departments/architecture-design"},{"label":"Cooper Hewitt：Design collection","url":"https://collection.cooperhewitt.org/"}]},"surrealist-photography":{"summary":"超现实主义摄影是超现实主义跨媒介实践的一部分，通过无相机成像、太阳化、双重曝光、拼贴、身体裁切和纪实照片的语境转换，质疑摄影的透明记录性。它既有暗房实验，也有冷静清晰的发现物，不等于模糊梦境照。","recognition":"不合逻辑尺度、物体替换、多重空间和梦境式并置；双重曝光轮廓、剪贴边缘、负片反转与身体碎片化；银灰黑白、棕褐或受控综合色；暗房曝光、太阳化边缘与不一致光源；银盐相纸、剪贴、再拍摄、颗粒和暗房接缝。","influencedBy":"超现实主义、达达拼贴、精神分析、自动性、现代广告与暗房技术","influenced":"实验摄影、时尚与广告摄影、艺术家电影、拼贴及观念图像","sources":[{"label":"The Met：Photography and Surrealism","url":"https://www.metmuseum.org/essays/photography-and-surrealism"},{"label":"Tate：Surrealism","url":"https://www.tate.org.uk/art/art-terms/s/surrealism"}]},"german-expressionist-cinema":{"summary":"德国表现主义电影是魏玛电影的一条重要但并非唯一的路线，常以造型化布景、绘制阴影、夸张表演和明暗关系把心理与社会压力外化。但《卡里加里博士的小屋》式歪斜棚景只是高识别个案，《大都会》《诺斯费拉图》等作品的建筑、外景和光线并不相同。","recognition":"造型化棚景、纪念性建筑、实景或巨大机械可分别组织空间，不强制歪斜布景；尖角轮廓、弧形建筑、群体节奏或夸张表演按具体作品选择；黑白灰阶及历史染色版本，不使用现代随意电子色；绘制阴影、硬侧光、逆光、外景日光或微妙低调光按影片布置；无声胶片颗粒、木工灰泥棚景、模型、服化道与历史印片磨损。","influencedBy":"德国表现主义舞台与绘画、第一次世界大战后的社会危机、魏玛制片工业、哥特与浪漫主义传统","influenced":"黑色电影、恐怖与科幻电影、惊悚片布光、舞台美术和动画","sources":[{"label":"BFI：10 great German expressionist films","url":"https://www.bfi.org.uk/lists/10-great-german-expressionist-films"},{"label":"MoMA：Weimar Cinema","url":"https://www.moma.org/calendar/film/1486"}]},"new-german-cinema":{"summary":"新德国电影在1962年《奥伯豪森宣言》后依托资助、电视合作和作者制作发展，对纳粹过去、战后经济、家庭、性别、移民和政治暴力展开差异很大的反思。长镜头与疏离表演不能覆盖法斯宾德、赫佐格、文德斯、冯·特洛塔等人的形式差异。","recognition":"连续长镜头、通俗剧式正反打、手持旅行或纪念性景观按导演与题材变化；表演可疏离、夸张、即兴或自然，身体与社会空间关系应服务叙事；黑白、低饱和彩色、舞台化高纯度色或纪录式色彩均可；现场光、精确棚光、过曝日光和舞台化色光按具体影片使用；16mm或35mm胶片、电视制作质感、棚景或实景表面与时代同步声。","influencedBy":"奥伯豪森宣言、法国新浪潮与意大利新现实主义、战后德国历史、电视资助和作者电影","influenced":"德国与欧洲作者电影、女性主义电影、历史记忆电影及后续独立制作制度","sources":[{"label":"BFI：New German Cinema","url":"https://www.bfi.org.uk/features/new-german-cinema-where-begin"},{"label":"Goethe-Institut：New German Cinema","url":"https://www.goethe.de/en/kul/flm/20867544.html"}]},"dusseldorf-school-photography":{"summary":"杜塞尔多夫摄影学派指贝恩德与希拉·贝歇在杜塞尔多夫艺术学院的教学谱系及学生网络，不是共享单一宣言的风格团体。贝歇夫妇的工业类型学是重要基础，但格尔斯基、斯特鲁特、霍夫、鲁夫等人在尺度、题材、彩色、数字处理和作者性上显著不同。","recognition":"系列类型学、单幅巨幅景观、建筑室内或人物正面可按摄影家分别组织；精密轮廓、重复结构、中性尺度或细节夸大依作品变化，不强制正中心对称；中性黑白、低饱和或精密校准的彩色，不设单一学派色谱；阴天散射光、室内均匀光、晨暮大气或可控棚光按系列使用；大画幅胶片、精细彩色印相、数字后期、博物馆级装裱和物体表面细节。","influencedBy":"贝歇夫妇的工业类型学、新客观摄影、新地形摄影、观念艺术和大画幅摄影","influenced":"当代艺术摄影、博物馆尺度彩色印相、建筑和风景摄影及数字图像讨论","sources":[{"label":"Tate：Dusseldorf School of Photography","url":"https://www.tate.org.uk/art/art-terms/d/dusseldorf-school-photography"},{"label":"The Met：Bernd and Hilla Becher","url":"https://www.metmuseum.org/art/collection/search/artist/443614"}]},"french-new-wave-cinema":{"summary":"法国新浪潮由《电影手册》评论网络、左岸派及一批低成本制作在1950年代末推动，通过实景、轻便设备、声画自反、类型重写和非连续剪辑改变作者与制片方式。跳切和手持只是部分导演的手段，不能覆盖特吕弗、戈达尔、瓦尔达、雷乃等人的差异。","recognition":"实景游移、稳定精密构图、跳切或长镜头均可，应区分导演与左岸派等路线；即兴、古典表演、直接凝视、文字中断或非线性时间按作品选择；高反差黑白、柔和胶片色、强烈原色或克制彩色均有历史实例；现场光、窗光、精确棚光或刻意的过曝与暗部按影片处理；16mm或35mm胶片、同步录音、实景表面、档案影像和可见剪辑断点。","influencedBy":"意大利新现实主义、好莱坞类型片、让·鲁什、《电影手册》作者政策、轻便摄影与录音技术","influenced":"世界各地新浪潮、新好莱坞、作者电影、独立制作和当代非连续剪辑","sources":[{"label":"BFI：French New Wave","url":"https://www.bfi.org.uk/features/where-begin-french-new-wave"},{"label":"Encyclopaedia Britannica：New Wave","url":"https://www.britannica.com/art/New-Wave-film"}]},"pictorialism":{"summary":"画意摄影是19世纪末至20世纪初的国际艺术摄影倾向，通过对构图、镜头成像、印相工艺和手工修整的控制，为摄影争取美术地位。它横跨欧美、日本等地，题材和技法多样；软焦、棕褐与雾景常见但不是定义全部。","recognition":"稳定绘画式、日本主义裁切、城市大气或肖像构图随地区与作者变化；软化轮廓、局部锐利结构、手工印相色块或精细细节均可并存；棕褐、铂金灰、蓝调、炭黑或手工彩色按具体工艺选择；雾光、逆光、室内窗光、直射日光或印相明暗控制均有可能；树胶重铬酸盐、铂金、碳素、凹版或银盐印相的纸纤维与手工差异。","influencedBy":"绘画与版画构图、象征主义、自然主义、早期摄影印相工艺及摄影艺术地位争论","influenced":"摄影分离派、艺术摄影展览与出版，也促成直接摄影对手工操作的反拨","sources":[{"label":"The Met：Pictorialism in America","url":"https://www.metmuseum.org/essays/pictorialism-in-america"},{"label":"MoMA：Pictorialism","url":"https://www.moma.org/collection/terms/pictorialism"}]},"czechoslovak-new-wave":{"summary":"捷克斯洛伐克新浪潮是1960年代电影学院、国营制片厂与政治松动中形成的多样实践，常以日常观察、黑色幽默、寓言、非职业演员或形式实验回应官僚与历史。《雏菊》式拼贴与超现实并非普遍模板，1968年后的审查、禁片和流亡也是关键语境。","recognition":"日常实景、古典叙事、拼贴中断、荒诞寓言或历史景观按导演与影片区分；非职业表演、精密造型、超现实物件或动画形体并非同时必备；黑白、柔和彩色、强烈滤色或印刷式拼色均有作品依据；现场日光、棚内戏剧光、平面动画光或刻意过曝按段落使用；35mm胶片、实景表面、布景、拼贴动画和可见剪辑断裂。","influencedBy":"捷克斯洛伐克电影学院、本国文学与超现实主义、意大利新现实主义、法国新浪潮及1960年代政治松动","influenced":"中东欧电影、政治寓言、荒诞喜剧、女性主义电影和国际艺术电影","sources":[{"label":"BFI：Czechoslovak New Wave","url":"https://www.bfi.org.uk/features/where-begin-czechoslovak-new-wave"},{"label":"Criterion：Pearls of the Czech New Wave","url":"https://www.criterion.com/current/posts/1733-pearls-of-the-czech-new-wave"}]},"new-hollywood-cinema":{"summary":"新好莱坞是对1960年代末至1980年代初美国制片与导演转型的历史分期，其背景包括制片厂危机、分级制度、青年观众、欧洲作者电影和社会政治冲突。它涵盖道路片、犯罪片、恐怖、科幻和大制作，不是一种长焦、镜头耀光和暖色负片组成的固定摄影风格。","recognition":"宽银幕景观、街头实景、精密类型场面或主观镜头按影片组织；表演、服化、车辆、建筑和特效形体必须对应具体类型与年代；自然彩色负片、银残留质感、黑白或高饱和类型色按主创变化；可用光、低照度夜景、精确棚光、正午硬光或特效光均有历史实例；35mm胶片、实景表面、变焦和长焦镜头、实物特效与新兴同步录音。","influencedBy":"制片厂制度转型、美国电影分级制、法国新浪潮与意大利新现实主义、电视竞争、反文化与越战时代","influenced":"当代好莱坞类型片、作者制作、独立电影、大片经济和电影学院文化","sources":[{"label":"BFI：The New Hollywood","url":"https://www.bfi.org.uk/features/new-hollywood"},{"label":"Encyclopaedia Britannica：The New Hollywood","url":"https://www.britannica.com/art/history-of-the-motion-picture/The-New-Hollywood"}]},"humanist-photography":{"summary":"人文主义摄影是对20世纪中叶以人的日常、街道、劳动与社会关系为中心的纪实倾向的后设分类，尤其用于战后法国摄影。关注普通人不意味着画面必然温情、柔灰或抓取‘决定性瞬间’；贫困、劳动和公共生活的再现还需考察摄影者与被摄者的权力关系。","recognition":"街头近景、环境肖像、群体场景或较远的观察取景按主题组织；自然动作、被摄者回应、运动模糊或清晰细节均可，不制造贫穷类型化；宽灰阶、高反差黑白或有限时代彩色，不把温和灰调当作人文性；现场日光、室内窗光、夜间路灯或闪光灯按拍摄条件使用；35mm银盐胶片、报刊印刷网点、粗细颗粒和现场服饰建筑细节。","influencedBy":"社会纪实摄影、摄影新闻、35mm小型相机、左翼人民阵线文化和战后欧洲重建","influenced":"纪实与街头摄影、图片杂志、人道主义摄影展览和关于代表伦理的批评","sources":[{"label":"Fondation Henri Cartier-Bresson：Henri Cartier-Bresson","url":"https://www.henricartierbresson.org/en/hcb/"},{"label":"ICP：The Concerned Photographer","url":"https://www.icp.org/exhibitions/the-concerned-photographer"}]},"provoke-photography":{"summary":"Provoke首先是1968至1969年间出版三期的日本短命摄影杂志与思想网络，寻求在政治动荡和媒介危机中形成‘来临之语言’。粗糙、摇晃、失焦（are-bure-boke）是关键策略但不是所有成员、所有作品或整个日本摄影的通用配方。","recognition":"倾斜、近距离、断裂裁切、空旷场景或页面序列按摄影家与摄影书编辑组织；粗颗粒、失焦、摇晃、清晰边缘或图文并置可分别使用，不作无差别滤镜；高反差黑白、宽灰阶或印刷失真按原作变化，不随意添加数码色散；现场硬光、过曝、堵塞暗部或平淡天光均服务具体场景；35mm胶片、粗糙印相、杂志纸、网点、连续页面与可见复制损失。","influencedBy":"1960年代日本学生运动与社会冲突、摄影新闻批判、实验电影、威廉·克莱因等人的都市图像及杂志文化","influenced":"1970年代以后日本与国际实验摄影、摄影书、时尚摄影和对图像可读性的讨论","sources":[{"label":"MoMA：Provoke","url":"https://www.moma.org/calendar/exhibitions/5066"},{"label":"The Met：For a Language to Come","url":"https://www.metmuseum.org/art/collection/search/787085"}]},"japanese-new-wave-cinema":{"summary":"日本新浪潮是对1950年代末至1970年代初一批制片厂内外电影的回溯性称呼，涉及青年、性、阶级、战争记忆、少数群体和学生运动。大岛渚、篠田正浩、今村昌平、勅使河原宏等人的产业位置与形式差异明显，不能以倾斜机位、跳切和强色概括。","recognition":"制片厂精密场面、纪录式实景、舞台化长镜头、断裂剪辑或极端特写按作品区分；身体、群体、城市和仪式形体须对应具体社会与作者语境；黑白、强烈胶片彩色、克制自然色或舞台色均有，不固定高饱和；现场光、舞台聚光、过曝、暗部压缩或精确棚光按影片使用；16mm或35mm胶片、实景与棚景、可见剪辑、试验声画和时代性服化道。","influencedBy":"日本制片厂制度与独立电影、战后社会冲突、日美安保抗议、纪录片、戏剧与国际现代电影","influenced":"日本独立电影、粉红电影的艺术实验、当代亚洲作者电影和政治现代主义","sources":[{"label":"BFI：Japanese New Wave","url":"https://www.bfi.org.uk/features/where-begin-japanese-new-wave"},{"label":"Harvard Film Archive：The Japanese New Wave","url":"https://harvardfilmarchive.org/programs/the-japanese-new-wave"}]},"photo-secession":{"summary":"摄影分离派是阿尔弗雷德·斯蒂格利茨1902年组织的美国艺术摄影团体与展览、《Camera Work》及291画廊网络，不是画意摄影的同义词。早期成员多支持画意印相，但后期斯蒂格利茨等人逐步转向更直接的现代城市与机器观看。","recognition":"画意构图、现代城市裁切、肖像或展览与杂志页面应按成员和年代区分；软化色调团块、精确边缘、手工印相或直接摄影细节在团体内并存；铂金灰、棕褐、炭黑、暖纸白或历史染色按作品与复制工艺选择；雾光、夜景、直射日光、室内光或印相色调控制不设固定模板；铂金、凹版、树胶或银盐印相、《Camera Work》纸张与精细复制层次。","influencedBy":"国际画意摄影、摄影俱乐部与沙龙展览、艺术摄影出版、新艺术和美国现代城市文化","influenced":"美国现代摄影、《Camera Work》的精细出版模式、291的现代艺术展览及直接摄影转向","sources":[{"label":"The Met：The Photo-Secession","url":"https://www.metmuseum.org/essays/the-photo-secession"},{"label":"Encyclopaedia Britannica：Photo-Secession","url":"https://www.britannica.com/art/Photo-Secession"}]},"poetic-realism-cinema":{"summary":"诗意现实主义是后世对1930年代法国一批电影的批评分类，常将工人阶层或边缘人物、注定失败的爱情与精心营造的城市环境结合。卡尔内的编剧、景片设计和雷诺阿、卡内、杜维威等导演的差异同样重要；雾夜湿地只是常见造型，不是定义。","recognition":"棚景城市、港口、酒吧、工人社区或乡村景观围绕人物选择组织；人物、建筑、雾气和道具可柔化或清晰，情感节奏不必依靠固定遮挡；银灰黑白、宽灰阶或历史染色版本，不强制潮湿深调；现场光、棚内局部光、雾化逆光、日景或夜景反射按具体影片处理；35mm胶片、棚景工艺、实景细节、服化道、烟雾与有声片制作痕迹。","influencedBy":"法国文学与流行歌谣、舞台布景传统、社会现实主义、声音电影制作及人民阵线时代","influenced":"黑色电影、意大利新现实主义、法国新浪潮和战后都市情节剧","sources":[{"label":"BFI：Poetic realism","url":"https://www.bfi.org.uk/features/poetic-realism"},{"label":"Encyclopaedia Britannica：Poetic realism","url":"https://www.britannica.com/art/poetic-realism"}]},"japanese-i-photography":{"summary":"日本‘私摄影’借用私小说的自我暴露与日记结构，将亲密关系、家庭、性、疾病、旅行和日常时间编辑为主观序列。它是有争议的批评分类，不是所有日本日记摄影的统一运动；小型胶片、色偏和不完美裁切也不能代替摄影者与被摄者的同意和权力关系。","recognition":"日记序列、相册式跳接、近距离亲密场景或日常空景由关系与时间组织；失焦、锐利细节、运动模糊、遮挡和意外裁切均可，不设统一粗糙公式；黑白、小型彩色胶片偏色、快照高饱和或平淡数码色按作者变化；窗光、室内现场光、直接闪光、路灯或过曝日光均有可能；35mm、拍立得、小型数码、相册纸、摄影书装订和可见复制痕迹。","influencedBy":"日本私小说、战后摄影书文化、Provoke之后的主观图像、家庭相册和小型相机","influenced":"当代日记摄影、摄影书、青年与时尚摄影及亲密性和自我表述讨论","sources":[{"label":"Tokyo Photographic Art Museum：Japanese photography","url":"https://topmuseum.jp/e/contents/exhibition/index.html"},{"label":"Wikipedia：I-photography","url":"https://en.wikipedia.org/wiki/I-photography"}]},"soviet-montage-cinema":{"summary":"苏联蒙太奇电影是1920年代在国有制作、革命文化和电影理论中发展的多种剪辑实践，爱森斯坦的‘冲突’、库里肖夫实验、普杜夫金和维尔托夫的方法不应混成一种理论。其意义主要在镜头之间的并置、节奏与声画思考，单张高反差对角构图不能代替剪辑关系。","recognition":"以至少两个镜头的尺度、方向、运动或概念并置生成意义，不用孤立单帧代替蒙太奇；人脸、机器、群体、文字和环境形体在镜头序列中建立节奏与对立；黑白灰阶与历史染色版本，明暗差异应支持镜头衔接；自然硬光、舞台光、剪影或较平曝光在前后镜头中建立可读关系；无声胶片颗粒、新闻片、实景表面、连续剪辑点和历史印片磨损。","influencedBy":"十月革命后的国有电影制度、构成主义与未来主义、新闻片、美国连续性剪辑、戏剧和劳动运动理论","influenced":"世界电影剪辑、纪录片、广告、音乐录像、政治影像和当代数字剪辑语法","sources":[{"label":"BFI：Soviet montage","url":"https://www.bfi.org.uk/features/soviet-montage"},{"label":"Encyclopaedia Britannica：Soviet theory of montage","url":"https://www.britannica.com/art/history-of-the-motion-picture/Soviet-theory-of-montage"}]},"taiwan-new-cinema":{"summary":"台湾新电影在1982年《光阴的故事》前后形成，借国家制片改革、新一代导演和社会转型，重新处理城乡现代化、家庭、语言、戒严历史与身份。侯孝贤、杨德昌等人的长镜头与深景极具影响，却不是全部影片的唯一语法。","recognition":"固定长镜头、流动城市观察、门窗分层或类型场面按导演与作品选择；人物尺度、家庭调度、城乡建筑和时代服化道须服务具体历史；自然胶片色、低饱和、夜景混合色温或黑白依影片变化；现场日光、室内灯光、街道混合光或受控棚光并非统一自然光；16mm或35mm胶片、现场空间、同步或后期声音、时代建筑与档案素材。","influencedBy":"台湾社会现代化与解严过程、中影改革、本土文学、欧洲作者电影及日本电影","influenced":"台湾后新电影、东亚艺术电影、慢电影和历史记忆影像","sources":[{"label":"Taiwan Film and Audiovisual Institute：Taiwan New Cinema","url":"https://www.tfai.org.tw/en/"},{"label":"Harvard Film Archive：Taiwan New Cinema","url":"https://harvardfilmarchive.org/programs/taiwan-new-cinema"}]},"hong-kong-new-wave-cinema":{"summary":"香港新浪潮在1970年代末由电视训练、海外电影教育和本地制片工业交汇而成，通过犯罪、武侠、恐怖、社会剧和城市故事重写类型，并处理移民、身份和九七前景。高密度实景和灵活机位常见，但许鞍华、谭家明、徐克等人的形式与工业位置并不相同。","recognition":"高密度街景、狭小室内、精密类型场面、快速运动或安静家庭空间按作品组织；动作、时装、建筑、车辆和招牌的形体必须对应具体年代和类型；霓虹混合色温、日景自然色、低饱和或黑白并存，不强制霓虹夜景；可用光、街灯、荧光灯、精确棚光或强烈类型光按场景使用；16mm或35mm胶片、实景表面、手持与轨道运动、同步或后期声音及实物特效。","influencedBy":"香港电视工业、海外电影教育、本地粤语类型片、国际新浪潮、城市现代化与移民经验","influenced":"香港电影黄金时代、东亚类型电影、音乐录像、广告影像和全球动作电影","sources":[{"label":"M+ Cinema：Hong Kong cinema","url":"https://www.mplus.org.hk/en/cinema/"},{"label":"Hong Kong Film Archive：Hong Kong New Wave","url":"https://www.filmarchive.gov.hk/en_US/web/hkfa/home.html"}]},"new-topographics":{"summary":"‘新地形：人类改造的景观’来自1975年罗切斯特乔治·伊斯特曼博物馆展览，聚焦一批对郊区、工业、道路和土地改造采取克制描述的摄影。‘中性’是复杂的修辞姿态，并非没有环境判断；稳定地平线、阴天和无人景观也不是成员共用公式。","recognition":"正面、侧向、路线序列、高视点或松散取景按摄影家与地点变化；建筑、道路、标识、植被和地形以具体尺度关系呈现，不伪造‘无风格’；黑白、低饱和彩色或精确自然色均有，不限阴天灰调；平淡日光、正午硬光、晨暮、雪景或室内人工光按系列选择；大画幅或中画幅底片、精细印相、地图和档案信息及建成环境真实表面。","influencedBy":"直接摄影、Walker Evans式纪录、概念艺术、战后郊区化、土地使用与新客观摄影","influenced":"当代风景摄影、杜塞尔多夫摄影、环境艺术、建成环境研究和土地政治图像","sources":[{"label":"George Eastman Museum：New Topographics","url":"https://www.eastman.org/new-topographics"},{"label":"The Met：New Topographics","url":"https://www.metmuseum.org/art/collection/search?q=New%20Topographics"}]},"new-objectivity-photography":{"summary":"新客观摄影是魏玛德国现代摄影的一条路线，常以锐利对焦、近距离、精密表面和类型研究显示植物、工业品、建筑与人像。它与绘画中的新客观主义相关但不同义，也不等于任何锐利、白底的产品照。","recognition":"近距离孤立物、系列类型、建筑正面或精密肖像按作者与题材组织；锐利轮廓、微细纹理、几何截面和尺度放大，不强制对称与白背景；宽灰阶、银盐黑白与少量历史复制色调，不使用现代冷灰滤镜；散射光、硬侧光、室内棚光或日光按表面与结构需要选择；大画幅或中画幅底片、银盐相纸、精细暗房印相与具体物质细节。","influencedBy":"直接摄影、画意摄影反拨、魏玛新客观主义、科学植物图像、现代工业和出版","influenced":"类型学摄影、贝歇夫夫妇、广告与建筑摄影、现代摄影教育和新地形摄影","sources":[{"label":"The Met：New Objectivity","url":"https://www.metmuseum.org/essays/new-objectivity"},{"label":"Tate：New Objectivity","url":"https://www.tate.org.uk/art/art-terms/n/new-objectivity"}]},"new-vision-photography":{"summary":"新视觉（Neues Sehen/New Vision）是1920至1930年代与包豪斯、拉斯洛·莫霍利-纳吉和国际现代主义相关的摄影观念，通过俯仰角、近距离、对角线、摄影蒙版、复合曝光和光影实验重新训练现代观看。它是多作者的实验立场，不等于所有新奇俯拍或包豪斯平面设计。","recognition":"极端俯仰、近距离放大、对角裁切、序列或摄影蒙版按实验目标选择；透视缩短、锐利几何、透明重叠、机械细节或无相机轮廓；高反差黑白、宽灰阶、蓝晒色或少量历史彩色实验；硬光投影、无相机直接曝光、反射、多重曝光或普通日光均可；银盐胶片、摄影蒙版相纸、透明材料、印刷网点和现代出版纸面。","influencedBy":"包豪斯教学、构成主义、新客观摄影、现代城市与技术、摄影蒙版和光学实验","influenced":"现代广告与编辑摄影、实验电影、摄影教育、构成主义出版和当代抽象摄影","sources":[{"label":"The Met：The New Vision","url":"https://www.metmuseum.org/essays/the-new-vision-photography-between-the-world-wars"},{"label":"MoMA：New Vision photography","url":"https://www.moma.org/collection/terms/new-vision-photography"}]},"italian-neorealism":{"summary":"意大利新现实主义是法西斯政权末期与战后重建中形成的电影倾向，关注战争、贫困、失业、家庭和日常环境，并以实景、职业与非职业演员混用、外景后期配音等方式工作。它不是无剧本的纯纪录，很多影片同时使用棚拍、职业表演、精心布光和情节剧结构。","recognition":"实景街区、棚内空间、群体路线或人物中远景按制作条件与叙事组织；职业与非职业表演、自然动作与精确调度可并存，不假定所有镜头即兴；宽灰阶黑白为主，也须容纳后期彩色作品与修复版本的具体信息；可用日光、反光补光、棚内人工光或夜景布光按镜头使用，不假定纯自然光；35mm胶片、战后实景表面、棚景、后期配音、时代服化道与历史印片颗粒。","influencedBy":"意大利战前现实主义文学与电影杂志、法国诗意现实主义、战争破坏、反法西斯抵抗和战后社会","influenced":"法国新浪潮、英国自由电影、拉丁美洲新电影、印度平行电影、伊朗电影和全球社会现实主义","sources":[{"label":"BFI：Italian neorealism","url":"https://www.bfi.org.uk/features/where-begin-italian-neorealism"},{"label":"Encyclopaedia Britannica：Neorealism","url":"https://www.britannica.com/art/Neorealism-Italian-art"}]},"straight-photography":{"summary":"直接摄影是20世纪初对摄影媒介特性的一种方法与立场，倾向使用清晰成像、摄影式裁切和受控印相，与画意摄影的仿绘画操作拉开距离。它不是正常透视、全景深和‘完全未处理’的规则；斯蒂格利茨、斯特兰德、韦斯顿、亚当斯等人的题材、底片尺寸和印相观差异显著。","recognition":"直接裁切、大画幅精密构图、动态城市角度或近距离物体研究按作者与设备变化；锐利边缘、选择性景深、精细质理、动态模糊或几何抽象均可保持摄影性；宽灰阶或高反差黑白，后续彩色实践需按摄影家和工艺说明；可追踪的自然光、棚光、反射或长曝光按对象使用，不强制完整亮暗分离；银盐底片、铂金或银盐相纸、精细暗房局部控制与底片尺寸特征。","influencedBy":"早期现代主义、摄影分离派后期转向、新视觉与新客观摄影、精确主义及摄影媒介辩论","influenced":"Group f/64、美国现代风景与静物摄影、纪录摄影、摄影教育和后续媒介特性讨论","sources":[{"label":"The Met：Photography and the American Scene","url":"https://www.metmuseum.org/essays/photography-and-the-american-scene"},{"label":"MoMA：Straight photography","url":"https://www.moma.org/collection/terms/straight-photography"}]},"subjective-photography":{"summary":"主观摄影是奥托·斯坦内特1949年组织fotoform并通过‘subjektive fotografie’展览推广的战后国际摄影立场，在纪实功能之外重新肯定个人观看、抽象、光影和暗房实验。它不只是负片反转、光轨和纹理近摄的效果集。","recognition":"抽象近摄、极端视点、记录场景、序列或光影实验按作者与展览选择；纹理、剪影、运动模糊、锐利几何、负片或重叠轮廓不必同时使用；黑白宽灰阶、高反差或历史复制色调，不把反相色当作定义；自然光、投影、长曝光、暗房遮挡或无相机曝光均可；银盐胶片、暗房局部控制、摄影蒙版、粗细颗粒和展览印相。","influencedBy":"新视觉摄影、包豪斯、超现实主义摄影、战后文化重建和业余摄影俱乐部网络","influenced":"战后实验摄影、欧洲摄影展览、抽象摄影、主观纪实和摄影教育","sources":[{"label":"MoMA：Subjective Photography","url":"https://www.moma.org/calendar/exhibitions/"},{"label":"Wikipedia：Fotoform","url":"https://en.wikipedia.org/wiki/Fotoform"}]},"normcore":{"summary":"Normcore由K-HOLE的2013年趋势报告提出，原指一种适应性与‘拥抱普通’的社会态度，2014年媒体才将其广泛转译为白球鞋、抓绒衣和无标识基础款。它是特定时期的流行话语，不等于所有极简、休闲或无心穿着。","recognition":"普通街头、通勤、超市或非戏剧化全身造型，不用空影棚白底将日常高级化；标准T恤、抓绒衣、牛仔裤、卡其裤、风衣和常见运动鞋按地点与年代选择；中性色、基础原色、普通品牌配色或旧衣褪色，不固定灰白藏青；日常日光、商场荧光、通勤灯光或编辑闪光，避免奢侈品式戏剧光；普通棉、抓绒、丹宁、尼龙、网布运动鞋和真实穿着折痕。","influencedBy":"2010年代趋势预测、后网络身份疲劳、1990年代基础款、大众户外服与运动鞋文化","influenced":"时尚编辑、性别中性基础款、高端时尚对平价日常服的挲用与当代极简衣橱","sources":[{"label":"The Museum at FIT：Fashion and everyday dress","url":"https://www.fitnyc.edu/museum/"},{"label":"Wikipedia：Normcore","url":"https://en.wikipedia.org/wiki/Normcore"}]},"disco-aesthetic":{"summary":"迪斯科视觉与1970年代纽约、费城等地黑人、拉丁裔和酷儿舞池文化、DJ技术、唱片出版和时尚产业共同发展。镜球、金属面和连体衣很有识别度，但不能删去其社群、种族、性别解放与商业化反扑的历史。","recognition":"群体舞池、DJ台、表演舞台、亲密肖像或唱片封面按社群和媒介组织；流动身体、喇叭轮廓、连体衣、紧身舞服、厚底鞋和不同性别造型并存；金银、宝石色、黑白、柔和棕色或舞池多色均有，不设紫金固定配方；镜球反射、频闪、舞台聚光、彩色灯或直接闪光必须体现真实空间来源；亮片、金属织物、缎面、聚酯、镜面瓷片、黑胶唱片与时代印刷。","influencedBy":"黑人与拉丁裔音乐、酷儿夜生活、灵魂乐与funk、DJ与音响技术、1970年代时尚和城市俱乐部设计","influenced":"夜店与锐舞文化、流行音乐舞台、时尚、灯光设计、唱片封面和当代酷儿视觉","sources":[{"label":"V&A：Night Fever","url":"https://www.vam.ac.uk/exhibitions/night-fever-designing-club-culture"},{"label":"Museum of the City of New York：Disco","url":"https://www.mcny.org/exhibition/new-york-new-music"}]},"gothic-lolita":{"summary":"Gothic Lolita是日本Lolita时尚的一个子类，在1990年代乐队造型、街头杂志、品牌与粉丝社群中成熟，以结构严谨的钟形或A字廓形结合深色、宗教或哥特式建筑引用。Lolita在此指时尚类别，不应被性化或与西方小说人物混同。","recognition":"全身造型、街拍、社群聚会或品牌型录保持从头饰到鞋履的完整比例；钟形或A字裙撑、合体上身、及膝裙长、发饰与精细层搭，不做成暴露情趣服；黑白常见，但深红、藏蓝、紫、灰和主题印花均可，不等于纯黑；街头日光、室内柔光、型录棚光或活动场地光突出结构与做工；棉、尼龙、蕾丝、天鹅绒、缎带、金属饰件、裙撑和真实缝制细节。","influencedBy":"日本Lolita时尚、Visual Kei、维多利亚与洛可可服饰的当代重构、原宿街头杂志和日本品牌","influenced":"全球Lolita社群、日本街头时尚、音乐造型、洋装品牌与社群活动礼仪","sources":[{"label":"The Museum at FIT：Japan Fashion Now","url":"https://www.fitnyc.edu/museum/exhibitions/japan-fashion-now.php"},{"label":"V&A：Lolita fashion","url":"https://www.vam.ac.uk/articles/lolita-fashion-japanese-street-style"}]},"skinhead-aesthetic":{"summary":"Skinhead起源于1960年代末英国工人阶级青年文化，服饰与牙买加ska、rocksteady、英国mod及工装实用性紧密相关。后来场景出现反种族主义、无政治和极右等互相冲突的网络，因此短发、吊带和工靴不能自动推断政治立场。","recognition":"街头群体、音乐会场、足球周边或全身肖像应具体说明时代、地点和社群；极短发、飞行夹克或短外套、直筒牛仔裤、吊带和工靴按时期变化，不统一军事化；丹宁蓝、黑、白、橄榄绿、酒红与苏格兰格纹按真实服装组合；街头日光、俱乐部现场光、报刊闪光或录像带光线保持纪录性；丹宁、棉布、羊毛、尼龙、皮革工靴、徽章与真实磨损。","influencedBy":"英国mod与rude boy文化、牙买加ska与rocksteady、工人阶级工装、足球和青年俱乐部","influenced":"Oi!与punk分支、全球skinhead网络、反种族主义组织、极右挲用争议和时尚业重释","sources":[{"label":"Museum of Youth Culture：Skinheads","url":"https://www.museumofyouthculture.com/skinheads/"},{"label":"V&A：Subculture fashion","url":"https://www.vam.ac.uk/articles/an-introduction-to-subculture-fashion"}]},"black-metal-aesthetic":{"summary":"黑金属视觉跨越1980年代第一波乐队、1990年代挪威第二波及各地分支，由唱片、地下录音带交换、演出、尸妆和树枝式标志共同建立。寒冷黑白户外照只是部分场景；对宗教、政治与暴力事件必须准确区分乐队与地区，不能用通用撒旦符号概括。","recognition":"乐队群像、舞台、森林或历史场所、录音带与唱片封面按场景具体组织；尸妆、黑衣、皮革、尖刺、长发或其他地方廓形不必同时出现；高反差黑白常见，也有彩色舞台、棕褐复印、雪地蓝灰或火光色；直接闪光、低照度舞台光、阴天户外、火光或复印堵塞明暗按资料使用；复印纸、录音带封套、银盐或早期数码颗粒、皮革、金属与真实户外表面。","influencedBy":"heavy metal、thrash、punk DIY、恐怖与浪漫主义自然图像、地下录音带交换及地方宗教政治冲突","influenced":"极端金属子类、地下音乐封面与标志、时尚摄影、恐怖视觉和关于挲用的争论","sources":[{"label":"Rockheim：Norwegian black metal","url":"https://rockheim.no/en/"},{"label":"Wikipedia：Black metal","url":"https://en.wikipedia.org/wiki/Black_metal"}]},"glam-rock-aesthetic":{"summary":"Glam rock在1970年代初英国流行音乐产业中形成，以电视、舞台、唱片封面和粉丝模仿放大闪光、厚底鞋、亮片、强妆与性别模糊表演。Bowie的太空造型是重要个案，但T. Rex、Roxy Music、Slade等路线并不共享一种细长银色廓形。","recognition":"电视棚舞台、演唱会、唱片封面、粉丝群体或时尚肖像按表演者区分；连体衣、宽肩、细腰、喇叭裤、厚底鞋、短发或长发造型并无单一比例；金银、高纯度原色、黑白、宝石色或柔和粉彩按艺人与年代变化；电视棚光、舞台聚光、闪光摄影、镜面反射或日间粉丝摄影；亮片、金属织物、缎面、天鹅绒、皮革、化妆粉与时代电视录像质感。","influencedBy":"rock and roll、好莱坞明星制、俄国与太空时代图像、康普表演、性别角色实验和电视音乐节目","influenced":"punk、goth、new romantic、重金属舞台、流行音乐造型和酷儿时尚","sources":[{"label":"V&A：David Bowie Is","url":"https://www.vam.ac.uk/exhibitions/david-bowie-is"},{"label":"Tate：Glam","url":"https://www.tate.org.uk/art/art-terms/g/glam"}]},"techwear":{"summary":"Techwear是对20世纪末以来将户外、军用、工业与都市服装的功能面料、人体工学剪裁和携带系统结合的市场与网络分类，并非成员明确的时尚运动。防水、透气、活动范围和口袋功能应可验证；全黑、面罩、过量绑带和赛博朋克城市不是定义。","recognition":"行走、骑行、通勤或产品细节场景须展示服装如何与身体和环境工作；立体剪裁、活动褶、可调节开口、可拆模块和口袋必须有功能逻辑，不堆砌绑带；黑、灰、橄榄、藏青、高可见色或户外配色均可，不设全黑要求；阴天城市光、通勤夜光、户外日光或产品棚光应清楚显示结构；防水透气膜、尼龙、弹力梭织、压胶缝、防水拉链、网布与真实磨损。","influencedBy":"户外运动服、军用与工作服、日本与欧洲前卫剪裁、功能膜面料、城市通勤和网络男装论坛","influenced":"当代城市户外服、鞋履、游戏角色设计、时尚摄影和功能生活方式营销","sources":[{"label":"The Museum at FIT：Expedition Fashion","url":"https://www.fitnyc.edu/museum/exhibitions/expedition-fashion.php"},{"label":"V&A：Performance materials in fashion","url":"https://www.vam.ac.uk/collections/fashion"}]},"club-kids-aesthetic":{"summary":"Club Kids是1980年代末至1990年代中期纽约夜店促销者与表演者网络，以主题派对、媒体曝光、性别游戏、廉价材料和极端自我发明把夜生活转化为表演。它不是所有1990年代锐舞或酷儿时尚的同义词，也需面对商业俱乐部、毒品与暴力事件的历史语境。","recognition":"夜店入口、舞池、群体摆拍、电视棚或媒体活动展示造型与观众关系；自制头饰、身体比例改造、drag妆面、玩具、塑料和日常物转化随主题而变；彩虹、荧光、黑白、金属或单一主题色均可，不是随机高饱和堆叠；直接闪光、频闪、夜店色光、电视棚光或后台日光按场景使用；泡沫、塑料、玩具、亮片、网布、缎面、廉价道具、化妆与胶片快照颗粒。","influencedBy":"纽约酷儿夜生活、drag、punk与new romantic、锐舞、电视谈话节目、夜店促销与DIY工艺","influenced":"派对摄影、流行音乐时尚、drag与夜店表演、网络造型文化和1990年代复兴","sources":[{"label":"Museum of the City of New York：New York nightlife","url":"https://www.mcny.org/exhibition/new-york-new-music"},{"label":"Wikipedia：Club Kids","url":"https://en.wikipedia.org/wiki/Club_Kids"}]},"techno-aesthetic":{"summary":"Techno视觉首先根植于1980年代中后底特律黑人电子音乐，将工业城市、机器节奏、欧洲电子乐和未来想象结合，后在柏林等仓库与俱乐部文化中发展出不同设计语汇。黑场、等宽字、频闪和工业栅格是部分场景，不能删除底特律的作者、种族和社会历史。","recognition":"舞池群体、DJ设备、仓库建筑、唱片标签或未来城市图像按地区与年代组织；机器模块、身体重复、工业结构、抽象符号和服装廓形不设单一黑色极简模板；黑灰、银、荼光色、彩色激光、唱片印刷色或底特律未来色彩均可；频闪、激光、冷白工业光、暗场轮廓或日间档案光按实际场景使用；黑胶、金属、混凝土、扬声器网、烟雾、录像带和早期数字图形纹理。","influencedBy":"底特律黑人音乐、funk、欧洲电子乐、Afrofuturism、后工业城市、DJ技术和仓库派对","influenced":"全球俱乐部文化、电子音乐平面设计、锐舞时尚、媒体艺术和城市夜间文化","sources":[{"label":"Detroit Historical Society：Detroit Techno","url":"https://www.detroithistorical.org/learn/encyclopedia-of-detroit/techno"},{"label":"V&A：Night Fever","url":"https://www.vam.ac.uk/exhibitions/night-fever-designing-club-culture"}]},"flapper-style":{"summary":"Flapper是1920年代对一类都市年轻女性、新的消费与夜生活行为的媒体称呼，其服装包括直筒轮廓、下移腰线、较短裙长与短发，但不是所有女性或所有1920年代服装的统一款式。流苏和满身珠饰更偏晚礼服与后世舞台想象，日常服、阶级、种族和地区差异需保留。","recognition":"日常街景、舞厅、杂志插图、影棚肖像或全身服装档案按用途区分；直筒或低腰轮廓、及膝裙长、短发、钟形帽与日常外套；珠饰流苏不是每套必备；黑白、海军蓝、粉彩、宝石色、金银与真实纺织印花按场合变化；日光街拍、影棚柔光、舞厅灯光、早期闪光或印刷平光依媒介处理；真丝、人造丝、羊毛、棉、珠饰、刺绣、帽饰与1920年代印刷和银盐颗粒。","influencedBy":"第一次世界大战后性别变化、女性参政与劳动、青年消费文化、jazz、好莱坞、Art Deco与成衣工业","influenced":"1920年代女性形象、现代成衣、舞台与电影服装、Art Deco复兴和性别现代性讨论","sources":[{"label":"The Met：Fashion in the 1920s","url":"https://www.metmuseum.org/toah/hd/char/hd_char.htm"},{"label":"Smithsonian：Flappers","url":"https://americanhistory.si.edu/explore/stories/flappers"}]},"mod-aesthetic":{"summary":"Mod是1950年代末至1960年代英国青年亚文化，以现代爵士乐、R&B和soul唱片、精心剪裁、舞厅和小型摩托车组织时尚身份。A字超短裙和原色圆形更属于1960年代青年时尚的部分女装图像，不能覆盖男装、工人阶级与音乐消费的核心。","recognition":"俱乐部、唱片店、街头群体、摩托车或时尚摄影须对应不同性别与阶级经验；窄身西装、短外套、高领针织、工装外套、A字裙与几何女装按人物和年代选择；黑白、海军蓝、棕色、英国赛车绿、原色或几何印花，不固定红蓝圆靶；街头日光、夜店暗光、纪录闪光、杂志棚光或电影光按媒介选择；精纺羊毛、棉、马海毛、尼龙外套、皮鞋、摩托车金属与时代胶片颗粒。","influencedBy":"意大利与欧洲大陆剪裁、现代爵士乐、黑人R&B与soul、伦敦青年消费、摩托车和夜店文化","influenced":"skinhead早期文化、Britpop时期复兴、英国青年时尚、电影、音乐平面与街头造型","sources":[{"label":"V&A：Mary Quant","url":"https://www.vam.ac.uk/articles/introducing-mary-quant"},{"label":"Museum of Youth Culture：Mods","url":"https://www.museumofyouthculture.com/mods/"}]},"emo-aesthetic":{"summary":"Emo视觉源于1980年代情感硬核及1990年代独立音乐网络，2000年代才在乐队媒体、MySpace、自拍与商业时尚中出现侧扫发、紧身服和黑红图形等高识别图像。不同乐队、地区与阶段差异明显，不能从外观推断心理疾病或自伤。","recognition":"近距自拍、偏斜上重轮廓与乐队图形层叠；侧扫尖发、紧身轮廓、窄裤和条带配件；黑、红、白、紫与高对比条纹；直接闪光、低照度室内和早期数码色偏；染发、棉 T 恤、丹宁、铆钉带和数码噪点。","influencedBy":"emotional hardcore、indie rock、punk DIY、乐队杂志、网络日志和早期社交媒体","influenced":"2000年代青少年时尚、网络自我形象、乐队商品、scene文化与当代复兴","sources":[{"label":"Museum of Youth Culture：Subcultures","url":"https://www.museumofyouthculture.com/"},{"label":"V&A：Subculture fashion","url":"https://www.vam.ac.uk/articles/an-introduction-to-subculture-fashion"}]},"rave-aesthetic":{"summary":"Rave视觉由1980年代末英国acid house、仓库派对、欧洲与美国电子音乐网络共同形成，涉及传单、灯光、音响、集体舞蹈和不同阶段的功能服。荧光、超宽裤与珠串只对应部分年代和地区，不能概括整个锐舞文化。","recognition":"宽松全身、反光配件节点与舞池群体节奏；超宽裤、短上装、厚底鞋和功能小包；荧光黄绿粉、银、黑与综合色塑料色；UV 黑光、频闪、激光和综合色雾光；尼龙、网布、反光带、塑料珠饰和合成毛绒。","influencedBy":"acid house、techno、disco与酷儿俱乐部、仓库派对、DIY传单和新型电子音响灯光","influenced":"电子音乐节、俱乐部设计、街头时尚、数字图形与全球夜间文化","sources":[{"label":"Museum of Youth Culture：Subcultures","url":"https://www.museumofyouthculture.com/"},{"label":"V&A：Subculture fashion","url":"https://www.vam.ac.uk/articles/an-introduction-to-subculture-fashion"}]},"cybergoth":{"summary":"Cybergoth在1990年代末至2000年代工业、EBM、rave与goth夜店网络中形成，以黑色基底、荧光合成材料、发束、厚底鞋与呼吸面罩式配件建立身体造型。它是特定夜店与时尚分支，不等于所有goth或赛博朋克服装，防毒面具也不应伪造安全功能。","recognition":"黑色中心、荧光发束和管状配件向外放射；厚底靴、束带、呼吸面罩和管线式发饰；黑配荧光绿粉蓝或紫；UV 黑光、冷色轮廓光和金属反射；PVC、乳胶、网布、塑料管、橡胶和铬金属。","influencedBy":"goth、industrial与EBM音乐、rave、网络科幻图像、PVC与荧光俱乐部材料","influenced":"俱乐部时尚、节日造型、网络亚文化摄影和当代复古未来服饰","sources":[{"label":"Museum of Youth Culture：Subcultures","url":"https://www.museumofyouthculture.com/"},{"label":"V&A：Subculture fashion","url":"https://www.vam.ac.uk/articles/an-introduction-to-subculture-fashion"}]},"gyaru-aesthetic":{"summary":"Gyaru是1990年代后日本青年女性时尚的多分支网络，通过杂志、涩谷商业空间、手机摄影与同伴社群发展高识别妆发和服饰。Ganguro、kogyaru、hime等在肤色、廓形和阶级想象上不同，不能以深色肤色、厚底鞋与染发概括。","recognition":"高识别妆发中心、短装比例与密集闪亮配件；蓬松卷发、夸张眼妆、厚底鞋和紧身短轮廓；金棕、粉、白、黑与高饱和综合色；明亮正面闪光和高曝光街拍光；染发光泽、仿皮草、亮片、丹宁和手机照片噪点。","influencedBy":"日本青年杂志、涩谷零售、偶像与海外流行时尚、校服改造、手机和大头贴社交","influenced":"日本美妆与时尚产业、东亚网络造型、青年自我摄影与当代Y2K复兴","sources":[{"label":"The Museum at FIT：Japan Fashion Now","url":"https://www.fitnyc.edu/museum/exhibitions/japan-fashion-now.php"},{"label":"V&A：Japanese street style","url":"https://www.vam.ac.uk/articles/japanese-street-style"}]},"mori-kei":{"summary":"Mori kei在2000年代后期日本社交网络、杂志与街头时尚中形成，以‘像生活在森林中’的想象组织宽松多层、旧化天然材料和手作配件。它是现代都市网络时尚，不是一种古老乡村传统；也不必固定米色、蕾丝和篮子。","recognition":"松散多层、长线下垂与小尺度自然配件；宽松裙裤、披肩、围巾和不对称柔软边缘；奶白、苔绿、褐、灰蓝与低饱和花色；林下或窗边漫射柔光；亚麻、棉、羊毛、针织、蕾丝和手作木饰。","influencedBy":"日本自然系品牌、古着、绘本与森林想象、mixi等网络社群和手作文化","influenced":"日本与国际自然系时尚、慢生活图像、手作零售与网络微美学分类","sources":[{"label":"The Museum at FIT：Japan Fashion Now","url":"https://www.fitnyc.edu/museum/exhibitions/japan-fashion-now.php"},{"label":"V&A：Japanese street style","url":"https://www.vam.ac.uk/articles/japanese-street-style"}]},"visual-kei":{"summary":"Visual kei是1980年代后日本摇滚乐队以视觉表演、杂志、唱片与粉丝文化建立的宽泛场景标签，不是音乐类型或固定时尚款式。Glam、goth、punk、传统服饰与性别表演的引用随乐队和时期差异很大，不能套用一种夸张黑红造型。","recognition":"舞台中心、夸张发型和服装边缘形成尖锐上升轮廓；宽肩窄腰、不对称长短层、束腰和戏剧化发束；黑、白、红、紫、金银与综合色妆面；舞台追光、综合色轮廓光和深暗背景；皮革、蕾丝、天鹅绒、金属、羽饰和光泽妆面。","influencedBy":"日本rock与metal、glam rock、punk、goth、歌舞伎和时代杂志与唱片工业","influenced":"日本音乐时尚、Gothic Lolita、东亚乐队视觉、粉丝角色扮演与当代偶像造型","sources":[{"label":"The Museum at FIT：Japan Fashion Now","url":"https://www.fitnyc.edu/museum/exhibitions/japan-fashion-now.php"},{"label":"V&A：Japanese street style","url":"https://www.vam.ac.uk/articles/japanese-street-style"}]},"dandyism":{"summary":"Dandyism是从18世纪末至19世纪欧美发展的自我塑造与社会姿态，以剪裁、保养、言行和对细节的受控选择表达现代个人性。它不等于奢侈服装或纰绔不羁，且需纳入黑人大西洋、女性与酷儿对dandy形象的重释。","recognition":"挺直中心、精准全身比例与少量精致配件层级；合体西装、清楚肩线、长外套和克制姿态；黑、炭灰、奶白、酒红与深绿；柔和肖像侧光和可读暗部；精纺羊毛、丝绸、皮革、天鹅绒和精细缝制。","influencedBy":"Beau Brummell时代英国男装、城市现代性、阶级礼仪、唯美主义、殖民与离散的服饰重释","influenced":"现代男装、流行文化、酷儿与黑人时尚、摄影肖像和关于自我表演的理论","sources":[{"label":"Museum of Youth Culture：Subcultures","url":"https://www.museumofyouthculture.com/"},{"label":"V&A：Subculture fashion","url":"https://www.vam.ac.uk/articles/an-introduction-to-subculture-fashion"}]},"hippie-aesthetic":{"summary":"Hippie视觉在1960年代美国反文化、反战、公社、音乐节和新左翼运动中形成，宽松服装、旧衣改造和手工刺绣常见。所谓‘民族风’常涉及对南亚、北非、美洲原住民等传统的去语境挲用，不应将无主图案作为反文化装饰。","recognition":"松散层搭、流动长线和多种手工图案并置；喇叭裤、长裙、流苏、宽袖和自然不规则轮廓；土橙、紫、绿、靛蓝与高饱和扎染综合色；暖日光、逆光光晕和自然阴影；棉麻、钩针、麂皮、珠饰、扎染和手工刺绣。","influencedBy":"反战与民权运动、folk与rock音乐、公社生活、二手服饰、手工文化及对多地传统的选择性挲用","influenced":"自然系时尚、音乐节服饰、环保生活方式图像、新时代运动和当代boho商业风格","sources":[{"label":"Museum of Youth Culture：Subcultures","url":"https://www.museumofyouthculture.com/"},{"label":"V&A：Subculture fashion","url":"https://www.vam.ac.uk/articles/an-introduction-to-subculture-fashion"}]},"new-romantic-aesthetic":{"summary":"New Romantic在1979年后伦敦Blitz等俱乐部及新合成器流行音乐中形成，通过历史服装拼接、精致妆面、性别游戏和手作改造反拨punk的直接。海盗衬衫、宽肩和华丽缎面是部分路线，不能覆盖成员、俱乐部和乐队的差异。","recognition":"戏剧中心、宽肩细腰与历史服装元素的层叠；荷叶领、泡袖、军装肩线和夸张帽饰；黑、白、金、深红蓝与华丽综合色；舞台柔光、轮廓光和烟雾；丝缎、天鹅绒、蕾丝、皮革和金属饰件。","influencedBy":"glam rock、punk、伦敦俱乐部、电子音乐、历史男女装、drag与艺术学院DIY","influenced":"1980年代流行音乐影像、时尚摄影、性别模糊舞台、goth和当代复古俱乐部造型","sources":[{"label":"Museum of Youth Culture：Subcultures","url":"https://www.museumofyouthculture.com/"},{"label":"V&A：Subculture fashion","url":"https://www.vam.ac.uk/articles/an-introduction-to-subculture-fashion"}]},"hardcore-punk-aesthetic":{"summary":"Hardcore punk视觉从1970年代末美国等地的高速、低成本DIY音乐网络发展，复印传单、同人志、现场摄影和实用服饰便于快速传播与演出。洛杉矶、华盛顿、纽约等场景的政治、族裔和图形并不相同，不能用一种黑白撕纸滤镜概括。","recognition":"直接近距、短硬轮廓、功能动作和极少装饰；剃短发、宽松 T 恤、工装裤和厚底鞋；黑、白、军绿与有限红色；现场硬光、机顶闪光和高反差黑白；粗棉、丹宁、帆布、胶带和复印颗粒。","influencedBy":"punk、DIY录音与场地、复印技术、滑板、地方政治与青年网络","influenced":"straight edge、post-hardcore、滑板视觉、独立出版、表演海报和当代DIY运动","sources":[{"label":"Museum of Youth Culture：Subcultures","url":"https://www.museumofyouthculture.com/"},{"label":"V&A：Subculture fashion","url":"https://www.vam.ac.uk/articles/an-introduction-to-subculture-fashion"}]},"harajuku-street-style":{"summary":"原宿街头风不是单一时尚派别，而是1980年代以来东京原宿及周边商店、街拍杂志、乐队与青年社群产生的多个造型网络。其价值在主题化全身编辑、旧衣、品牌和DIY的组合，不应被西方媒体统一称为‘可爱混搭’。","recognition":"全身街拍、多个主题层叠与配件从头到脚形成阅读路径；不同廓形并置、比例夸张和自定义改造边缘；多色高饱和、黑白与按造型主题组织的综合色；自然街拍光或直接闪光；成衣、手作改造、塑料配件、古着和街拍数码颗粒。","influencedBy":"东京青年商业区、街拍杂志、古着与独立品牌、音乐、美容和同伴社群","influenced":"全球街头时尚、时尚博客与社交媒体、Lolita、Decora、Visual Kei与品牌营销","sources":[{"label":"The Museum at FIT：Japan Fashion Now","url":"https://www.fitnyc.edu/museum/exhibitions/japan-fashion-now.php"},{"label":"V&A：Japanese street style","url":"https://www.vam.ac.uk/articles/japanese-street-style"}]},"heavy-metal-aesthetic":{"summary":"Heavy metal视觉由1970年代以来的乐队标志、唱片封面、演出灯光、乐迷服饰和杂志共同构成。尖角字、皮革铆钉、火焰和奇幻题材只覆盖部分子类；traditional、thrash、doom、glam等的形象、政治与阶级语境需具体区分。","recognition":"强中心徽章、对称翼状展开与舞台式造型焦点；尖角字形、铆钉、皮革轮廓和夸张肩部；黑、银、红、紫与电蓝；舞台逆光、金属轮廓光和烟雾；皮革、铆钉、铬金属、丹宁和粗颗粒印刷。","influencedBy":"hard rock、blues、恐怖与奇幻图像、工人阶级舞台文化、唱片包装和定制摩托车时尚","influenced":"极端金属子类、音乐标志、乐迷服饰、游戏和奇幻影视视觉","sources":[{"label":"Rock & Roll Hall of Fame：Music history","url":"https://www.rockhall.com/education"},{"label":"V&A：Performance and music","url":"https://www.vam.ac.uk/collections/theatre-performance"}]},"decora-kei":{"summary":"Decora是1990年代末原宿街头时尚的具体分支，以发夹、珠串、玩具、创可贴与层搭配件的高密度重复建立主题，并通过《FRUiTS》等街拍媒体扩散。它并不等于任意彩虹堆叠，也不应将成年穿着者幼态化。","recognition":"配件高密度重复、上半身焦点和从发部向外扩散的层级；小夹子、珠串、贴纸和玩具模块堆叠在圆润轮廓上；彩虹高饱和、粉、黄、蓝、绿与白；明亮正面光和塑料小高光；塑料发夹、珠饰、贴纸、针织和彩色合成纤维。","influencedBy":"原宿街拍、玩具与文具消费文化、手作配件、青年同伴社群和日本杂志","influenced":"原宿全球形象、网络服饰社群、偶像配件、当代maximalist时尚与可爱视觉","sources":[{"label":"The Museum at FIT：Japan Fashion Now","url":"https://www.fitnyc.edu/museum/exhibitions/japan-fashion-now.php"},{"label":"V&A：Japanese street style","url":"https://www.vam.ac.uk/articles/japanese-street-style"}]},"biopunk":{"summary":"Biopunk是从遗传工程、生物信息、企业专利和身体政治出发的科幻子类，并非有统一宣言的视觉运动。湿式实验室、有机组织与工业支架是可用图像，但核心在技术权力、劳动、生命所有权和伦理后果。","recognition":"实验模块、有机生长体与工业支架互相嵌合；膜、管束、细胞式重复和不对称增殖轮廓；组织粉、病态绿、培养液黄、黑与冷白；冷白实验光、透射光和湿亮高光；生物膜、凝胶、玻璃、金属支架和黏液般表面。","influencedBy":"cyberpunk、生物技术与遗传工程、body horror、企业科幻和专利与生命伦理争论","influenced":"科幻文学、电影、游戏、生物艺术和对基因与身体权力的公共讨论","sources":[{"label":"Rhizome：Digital art archive","url":"https://rhizome.org/art/"},{"label":"V&A：Digital art and design","url":"https://www.vam.ac.uk/collections/digital-art-design"}]},"new-aesthetic":{"summary":"New Aesthetic是James Bridle在2011年前后提出的网络研究项目与讨论标签，聚合像素、无人机视角、识别框、地图和计算机视觉进入物理世界的迹象。它不是一种可复制的像素滤镜，其关键是机器如何观看、分类和执行权力。","recognition":"机器视觉框、像素层、现实物体与数字界面同屏并置；识别框、二维码式网格、低模形和硬边数字覆盖；屏幕 RGB、监控灰、荧光功能色与现实综合色；现实环境光与屏幕自发光直接叠加；像素、压缩、三维网格、摄像头噪点和打印输出。","influencedBy":"网络图像流、计算机视觉、卫星与无人机图像、像素艺术、监控与地理信息系统","influenced":"数字文化批评、当代艺术、机器视觉设计、监控美学与物理-数字融合图像","sources":[{"label":"Rhizome：Digital art archive","url":"https://rhizome.org/art/"},{"label":"V&A：Digital art and design","url":"https://www.vam.ac.uk/collections/digital-art-design"}]},"frutiger-metro":{"summary":"Frutiger Metro是后来网络社群对2000年代中后期一类媒体、企业和数字图形的追认性命名，常以黑色流线、高饱和扁平图标、音乐与都市符号区别于Frutiger Aero的仿真自然图像。它不是当时设计师共同使用的历史术语，年代、软件和实例应明确。","recognition":"粗黑流线插画、图标群、波形模块和非对称平面层叠；粗圆轮廓、扁平拟人图标、音乐与交通式符号；黑白配高饱和青绿橙蓝粉；完全平面化，仅用少量光泽色块；清楚矢量边缘、数字贴纸感与简洁渐变。","influencedBy":"2000年代矢量插画软件、青年频道包装、音乐与滑板图形、Web 2.0企业设计","influenced":"网络怀旧分类、Y2K后复兴、数字贴纸与当代青年品牌图形","sources":[{"label":"Rhizome：Digital art archive","url":"https://rhizome.org/art/"},{"label":"V&A：Digital art and design","url":"https://www.vam.ac.uk/collections/digital-art-design"}]},"ottoman-miniature":{"summary":"奥斯曼细密画主要服务宫廷史书、节庆记录、地理、家谱和图册，由绘画、书法和装帧工坊协作。地图式俯视和纪实群组在部分作品中突出，但幻想文学、肖像和不同宫廷阶段也存在，不能一律写成无装饰的编年图解。","recognition":"地图式俯视、建筑分区、横向仪典群组、肖像或幻想场景按文本类型组织；硬边人物、重复姿态、可辨服饰建筑和少量综合色体积随工坊阶段变化；朱红、群青、绿、赭黄、金和纸色按写本与时期选择；平面阅读光与综合色分区建立事件次序，金色保持小范围真实反光；纸本不透明水彩、金、细线、书法、装帧和修订叠层。","influencedBy":"波斯和帖木儿书籍艺术、拜占庭与地中海图像、奥斯曼宫廷史学和nakkaşhane工坊","influenced":"奥斯曼历史图像、地理绘图、宫廷肖像和现代土耳其书籍艺术","sources":[{"label":"The Met：Ottoman court art","url":"https://www.metmuseum.org/essays/the-art-of-the-ottomans-after-1600"},{"label":"Wikipedia：Ottoman miniature","url":"https://en.wikipedia.org/wiki/Ottoman_miniature"}]},"hurufiyya-movement":{"summary":"Hurufiyya是对20世纪中后期西亚、北非及离散艺术家将阿拉伯字母、书写和现代抽象结合的多中心称呼，并非成员统一的正式运动。字母可保持语言、转为形体或承担身份政治；不能用随机阿拉伯线条替代准确书写。","recognition":"字母、词语、书写痕迹或抽象场按具体艺术家与语言关系组织，不固定非线性碎片；字形可清晰、断裂、重复或绘画化，但应保持来源书体与动作可辨；综合色从黑白土色到高纯度现代综合色不等，依作品与地区变化；平面综合色、颜料厚度、书写墨色或装置光按媒介处理；油彩、墨、纸、拼贴、织物、雕塑和真实书写表面。","influencedBy":"阿拉伯书法与不同地区文字传统、现代抽象、反殖民国家建构、身份与语言政治","influenced":"阿拉伯现代与当代艺术、书写抽象、离散身份和全球文字艺术","sources":[{"label":"Tate：Hurufiyya","url":"https://www.tate.org.uk/art/art-terms/h/hurufiyya"},{"label":"Barjeel Art Foundation：Hurufiyya","url":"https://www.barjeelartfoundation.org/collection/hurufiyya/"}]},"qajar-painting":{"summary":"卡扎尔绘画涵盖宫廷大型油画、漆器、写本、相册、玻璃画和后来摄影影响下的作品，以王权肖像和欧洲式明暗的选择性吸收著称。正面长身君主与珠宝只是部分宫廷类型，不能覆盖民间、宗教和晚期题材。","recognition":"纪念性正面肖像、拱形壁龛、相册小像、漆器画或叙事场景按媒介与阶段选择；平滑综合色体积、拉长比例、精密服饰或较民间化轮廓不设统一宫廷脸型；深红、孔雀蓝绿、黑、金、综合色肤色和摄影灰阶均可；正面均匀光、欧洲式柔和明暗或摄影光按作品年代使用，不做电影暗影；油彩、纸本综合色、漆面、玻璃、镜饰、摄影材料和抛光表面。","influencedBy":"萨法维和赞德绘画、欧洲油画版画、卡扎尔宫廷、漆器与摄影","influenced":"伊朗近现代绘画、摄影、咖啡馆绘画和国家肖像文化","sources":[{"label":"The Met：The art of the Qajar period","url":"https://www.metmuseum.org/essays/the-art-of-the-qajar-period-1779-1924"},{"label":"Wikipedia：Qajar art","url":"https://en.wikipedia.org/wiki/Qajar_art"}]},"kufic-calligraphy-aesthetic":{"summary":"库法体是早期阿拉伯书法多类角折或纪念性书体的宽泛称谓，见于《古兰经》写本、建筑、钱币和工艺。方整、延长横画和几何化只描述部分类型；东库法、叶饰库法、方形库法等在年代、媒介和可读性上不能混为一体。","recognition":"基线、横向展开、行距和字间比例按早期写本、建筑或方形库法具体类型组织；角折、宽笔、延长横画、叶饰或网格结构须来自可识别字形而非任意几何；墨黑、羊皮纸、石材、砖、釉色和金依据载体，不设黑金统一方案；写本平面阅读光，石刻砖铭用克制侧光显示真实深度；羊皮纸墨迹、芦苇笔、石刻、砖砌、釉砖、钱币和真实磨损。","influencedBy":"早期阿拉伯文字、伊斯兰宗教书写、羊皮纸写本和建筑铭文","influenced":"伊斯兰建筑书法、手抄本、钱币和当代阿拉伯字体设计","sources":[{"label":"The Met：The nature of Islamic art","url":"https://www.metmuseum.org/essays/the-nature-of-islamic-art"},{"label":"Wikipedia：Kufic","url":"https://en.wikipedia.org/wiki/Kufic"}]},"nastaliq-calligraphy-aesthetic":{"summary":"纳斯塔利克体在伊朗及波斯语文化圈形成，尤其适用于波斯诗歌、书信和相册页，以斜行、悬垂节奏和强烈粗细变化著称。它不是所有波斯文的默认字体，也不适合在无法准确排写连字时被模拟为流动曲线。","recognition":"斜向下降行列、悬挂式词组和宽阔页边按诗歌或书信篇章组织；短竖、长横、流畅弧线和字间连带必须来自准确纳斯塔利克结构；墨黑、纸色、金饰和克制矿物边饰从写本或书法页取得；均匀阅读光突出墨色和斜行节奏，金饰只保留真实反光；芦苇笔墨迹、抛光纸、剪贴书法、金饰和装帧纤维。","influencedBy":"纳斯赫与塔利克书体、波斯语诗歌文化、帖木儿和伊朗书法工坊","influenced":"波斯、莫卧儿和南亚书籍艺术、相册页与现代波斯字体","sources":[{"label":"The Met：The art of the book in the Islamic world","url":"https://www.metmuseum.org/essays/the-art-of-the-book-in-the-islamic-world"},{"label":"Wikipedia：Nastaliq","url":"https://en.wikipedia.org/wiki/Nastaliq"}]},"safavid-miniature":{"summary":"萨法维绘画涵盖大不里士、加兹温、伊斯法罕等阶段的皇家写本、单页人物、相册与市场作品。花园式层叠和纳斯塔利克书法重要，但16世纪大型写本与17世纪单人画页的构图、综合色和赞助机制不同。","recognition":"多焦点写本、花园宫廷、单页人物或相册边饰按阶段与画家选择；精细轮廓、流动衣线、织纹、岩石云树和17世纪拉长人物依作品使用；群青、朱红、粉、绿、金和纸色范围随大不里士至伊斯法罕阶段变化；综合色区、重叠和金饰构成页面空间，不设统一宝石光；抛光纸、不透明水彩、金、精线、剪贴书法、边饰和装帧。","influencedBy":"帖木儿和土库曼书籍艺术、波斯诗歌书法、萨法维宫廷与城市市场","influenced":"莫卧儿、德干、奥斯曼和卡扎尔绘画，以及波斯相册页传统","sources":[{"label":"The Met：The art of the Safavids before 1600","url":"https://www.metmuseum.org/essays/the-art-of-the-safavids-before-1600"},{"label":"Wikipedia：Safavid art","url":"https://en.wikipedia.org/wiki/Safavid_art"}]},"seljuk-art":{"summary":"塞尔柱艺术横跨大塞尔柱和安纳托利亚塞尔柱等不同政权，涵盖清真寺、学院、商队驿站、陶瓷、金属和写本。砖几何、铭文、釉砖与石雕很重要，但伊朗砖建筑和安纳托利亚石门廊不能统一成同一蓝砖风格。","recognition":"伊朗砖砌穹顶和伊万、安纳托利亚石门廊或器物表面按地区功能组织；砖砌几何、石雕卷草、穆卡纳斯、釉砖和书法带依材料与政权区分；砖红、石色、钴蓝、绿松石、黑白来自地区材料，不强制蓝色主导；真实强日光和擦边光显示砖缝、石刻、穆卡纳斯与釉面；砖、石、灰泥、木雕、釉砖、陶瓷、金属嵌饰和风化。","influencedBy":"伊朗、中亚、安纳托利亚与亚美尼亚等区域工艺、伊斯兰建筑和游牧宫廷网络","influenced":"伊尔汗、安纳托利亚诸侯与奥斯曼建筑、伊朗陶瓷金属和几何装饰","sources":[{"label":"The Met：The art of the Seljuqs of Iran","url":"https://www.metmuseum.org/essays/the-art-of-the-seljuqs-of-iran-ca-1040-1196"},{"label":"Wikipedia：Seljuk architecture","url":"https://en.wikipedia.org/wiki/Seljuk_architecture"}]},"timurid-art":{"summary":"帖木儿艺术以撒马尔罕、赫拉特等宫廷的宏大建筑、釉砖、金工、书法和书籍艺术著称，并通过跨地区艺术家迁徙形成多样中心。蓝色建筑和精密写本重要，但不能把建筑瓷砖纹理塞入每幅细密画或把宫廷风格视为整个中亚。","recognition":"城市纪念轴线和庭院、或写本高视点多焦点空间按建筑和书籍分开；高耸门廊、穹顶、釉砖网格与精细人物山水分别服从媒介；钴蓝、绿松石、砖色、群青、朱红、金和纸色按遗址或工坊变化；建筑真实日光与写本平面阅读光分开，不统一蓝金辉光；砖、马赛克釉砖、石膏、纸本综合色、金、书法和抛光装帧。","influencedBy":"伊尔汗和中亚艺术、蒙古帝国交流、伊朗书籍工坊与被迁徙的区域工匠","influenced":"萨法维、莫卧儿和乌兹别克艺术，以及波斯细密画和中亚建筑","sources":[{"label":"The Met：The art of the Timurid period","url":"https://www.metmuseum.org/essays/the-art-of-the-timurid-period-ca-1370-1507"},{"label":"Wikipedia：Timurid art","url":"https://en.wikipedia.org/wiki/Timurid_art"}]},"islamic-arabesque":{"summary":"Arabesque 是欧洲艺术史中用于描述伊斯兰艺术连续卷草、分叉叶茎和抽象植物填充的术语，其涵盖范围宽且外部命名色彩明显。它与几何纹样、书法可组合却不等同，也不能代表所有伊斯兰装饰。","recognition":"连续边带、对称生长、旋转填充或满幅卷草按具体媒介组织，不设一种无限模板；分叉茎线、叶片、花苞和正负形连接保持植物节律与手工结构；综合色来自灰泥、木石、釉彩、织物和金饰，不固定蓝绿金；平面装饰和真实浮雕、釉面或金属反光分别处理；彩绘灰泥、木石雕、陶瓷、织物、金属、纸本综合色与金饰。","influencedBy":"晚期古代卷草、萨珊和拜占庭植物装饰、伊斯兰建筑与工艺抽象化","influenced":"伊斯兰建筑和书籍装饰、欧洲arabesque接受及现代图案设计","sources":[{"label":"Britannica：Arabesque","url":"https://www.britannica.com/art/arabesque-decorative-style"},{"label":"The Met：Vegetal patterns in Islamic art","url":"https://www.metmuseum.org/essays/vegetal-patterns-in-islamic-art"}]},"islamic-manuscript-illumination":{"summary":"伊斯兰写本金饰涵盖《古兰经》、文学、科学和相册等书籍的篇章页、题签、页边与书法周边装饰，跨阿拉伯、波斯、奥斯曼、莫卧儿等多种传统。它不必有中心图像或首字母，也不能把基督教手抄本结构套用为统一模板。","recognition":"篇章页、题签、页框、行间金饰或边际图案围绕文本功能组织，不强制中心图像；几何、卷草、云纹、花卉和金点按地区工坊使用，保持精密手工边缘；金、群青、朱红、绿、纸或羊皮纸本色依文本、时期和资源变化；均匀阅读光保留书法与装饰层级，金箔只呈真实小反射；羊皮纸或纸、墨、金箔或金泥、矿物综合色、抛光和装帧。","influencedBy":"早期《古兰经》制作、晚期古代书籍工艺、纸张传播、书法和各宫廷装帧作坊","influenced":"波斯、奥斯曼、莫卧儿书籍艺术和现代手工装帧","sources":[{"label":"The Met：The art of the book in the Islamic world","url":"https://www.metmuseum.org/essays/the-art-of-the-book-in-the-islamic-world"},{"label":"British Library：Illuminated manuscripts","url":"https://www.bl.uk/sacred-texts/articles/illuminated-manuscripts"}]},"hyperrealism":{"summary":"Hyperrealism在1960年代末至1970年代与照相写实、大尺度雕塑及欧洲展览语境交叉，借照片中介和过度清晰显示消费表面、身体与感知不安。它与Photorealism的边界在地区和评论中并不稳定，不应宣称一定更‘真’或更高清。","recognition":"开放结构、材料关系与观看路径共同组织画面；以流派特有的轮廓、笔触和形体变形处理用户主体；受控综合色与流派特有的色彩对比；以画面明度和色温组织光感，避免通用电影光；材料本体、制作痕迹与当代展示表面并置。","influencedBy":"照相写实、Pop Art、消费摄影、广告图像、模具与树脂技术及关于复制的讨论","influenced":"当代具象绘画与雕塑、数字渲染、特效化妆和对图像真实性的批评","sources":[{"label":"Tate：Art terms","url":"https://www.tate.org.uk/art/art-terms"},{"label":"MoMA：Art terms","url":"https://www.moma.org/collection/terms"}]},"light-and-space":{"summary":"Light and Space是对1960至1970年代南加州艺术家以光、半透明材料、建筑开口和观者感知构造作品的地区性称呼。真实空间、适应时间和观看位置是核心，不能将它转成画面上的霓虹渐变效果。","recognition":"空室、开口、雾化场域与观看位置精确控制；几乎消失的边界、连续平面与感知性几何；白、综合色光谱与低对比综合色；光本身作为材料，制造无边界渐变和综合色适应；玻璃、树脂、荧光灯、环境雾与光滑墙面。","influencedBy":"Minimalism、南加州航空与树脂制造、现象学、建筑空间、光学和沙漠环境","influenced":"场域特定艺术、安装、媒体建筑、感知研究和当代沉浸式光艺术","sources":[{"label":"Tate：Art terms","url":"https://www.tate.org.uk/art/art-terms"},{"label":"MoMA：Art terms","url":"https://www.moma.org/collection/terms"}]},"post-painterly-abstraction":{"summary":"‘后绘画性抽象’是克莱门特·格林伯格为1964年巡展提出的集合名称，涵盖综合色场、硬边和压低手势的多种美国及加拿大绘画。它不是成员自称的统一运动，也不能只以薄染画布定义。","recognition":"开放色场、清晰大形与压低手势中心；平坦轮廓、长条或宽阔色区与有限边缘变化；清澈高纯度综合色与大面积同色层；综合色明度而非颜料堆积建立空间；薄丙烯、染色画布与克制笔触。","influencedBy":"抽象表现主义、综合色场绘画、现代主义形式批评、丙烯材料和对厚涂手势的反应","influenced":"硬边绘画、综合色场、极简视觉和后续抽象绘画","sources":[{"label":"Tate：Post-painterly abstraction","url":"https://www.tate.org.uk/art/art-terms/p/post-painterly-abstraction"},{"label":"LACMA：Post-Painterly Abstraction","url":"https://www.lacma.org/art/exhibition/post-painterly-abstraction"}]},"post-minimalism":{"summary":"后极简主义是评论与展览使用的宽泛术语，涵盖过程艺术、柔性材料、身体、偶发和场地实践对极简主义的扩展与反应。毡的垂坠、乳胶卷曲只是个案；部分作品仍保留模块和工业材料。","recognition":"重复单元受重力改变、开放铺陈与非刚性秩序；垂坠、卷曲、堆叠与过程形成的软性几何；材料本色、灰白、土色与有限综合色；自然展示光强调重力和柔性阴影；毡、绳、乳胶、玻璃纤维与过程痕迹。","influencedBy":"极简主义、过程艺术、女性主义、身体与舞蹈、工业和柔性材料实验","influenced":"过程、装置、身体与生态艺术，以及雕塑对重力和时间的研究","sources":[{"label":"Tate：Postminimalism","url":"https://www.tate.org.uk/art/art-terms/p/postminimalism"},{"label":"Guggenheim：Post-Minimalism","url":"https://www.guggenheim.org/artwork/movement/post-minimalism"}]},"washington-color-school":{"summary":"华盛顿综合色画派是对莫里斯·路易斯、肯尼斯·诺兰、吉恩·戴维斯等华盛顿特区艺术家的地区性称呼，成员并非样式一致的正式团体。浸染、条带、靶形和综合色帷幕各有不同制作机制，不能统一为透明软边综合色场。","recognition":"大面积开放色场、中心靶形或条带节奏；染色软边、同心圆、竖条与简化几何；明亮透明综合色与未涂画布底色；综合色透明度和画布吸收产生发光感；稀释丙烯浸染、裸画布纤维与无厚涂表面。","influencedBy":"抽象表现主义、综合色场、海伦·弗兰肯瑟勒的浸染、丙烯颜料和华盛顿艺术网络","influenced":"后绘画性抽象、硬边、综合色场及美国地区现代主义研究","sources":[{"label":"Smithsonian American Art Museum：Washington Color School","url":"https://americanart.si.edu/art/highlights/washington-color-school"},{"label":"National Gallery of Art：Washington Color School","url":"https://www.nga.gov/features/washington-color-school.html"}]},"geometric-abstraction":{"summary":"几何抽象是以线、平面、网格、曲线和比例关系组织非具象作品的上位类别，涵盖不同理论、综合色、空间和制作方式。它比具体艺术范围更广，也不必完全排除象征、直觉、手工边缘或三维空间。","recognition":"非客观网格、比例分区与重复几何秩序；直线、圆、弧、多边形与精确闭合边缘；受控纯色、黑白与清楚明度级；平面无影，以色形关系建层；平滑颜料、矢量硬边或工业制表面。","influencedBy":"立体主义、俄国先锋、De Stijl、包豪斯、数学与非再现艺术理论","influenced":"具体艺术、硬边、Op Art、极简、建筑设计和数字生成艺术","sources":[{"label":"Tate：Geometric abstraction","url":"https://www.tate.org.uk/art/art-terms/g/geometric-abstraction"},{"label":"MoMA：Geometric abstraction","url":"https://www.moma.org/collection/terms/geometric-abstraction"}]},"concrete-art":{"summary":"具体艺术由Theo van Doesburg等人在1930年宣言中主张作品应由综合色、线和表面自身构成，而非抽象自然对象。其理性、非再现和预先构成原则影响广泛，但不同国家并不都坚持数学秩序或无手工痕迹。","recognition":"完全非再现的比例系统、模块排列与数学秩序；精确基本几何、等距关系与无象征形；有限纯色、黑白与系统化综合色组合；均匀平面光，不模拟自然空间；平滑颜料、清楚硬边与工业化表面。","influencedBy":"De Stijl、构成主义、几何抽象、现代设计和非再现理论","influenced":"瑞士、阿根廷和巴西具体艺术、系统与几何抽象、现代视觉设计","sources":[{"label":"Tate：Concrete art","url":"https://www.tate.org.uk/art/art-terms/c/concrete-art"},{"label":"MoMA：Concrete Art","url":"https://www.moma.org/collection/terms/concrete-art"}]},"pattern-and-decoration":{"summary":"Pattern and Decoration是1970年代美国艺术家重新肯定装饰、工艺和综合色愉悦的运动，常回应现代主义、极简和艺术/工艺等级中的性别偏见。它借鉴伊斯兰、亚洲及民间传统时也涉及挪用问题，不能将‘多文化纹样’当作可自由拼贴的无主资源。","recognition":"满幅重复、边带和层级纹样可并置，但具体文化来源必须分辨，不能做无主拼贴；花卉、几何、贴片和手工单元按艺术家与媒介组织，不设统一装饰词汇；高纯度多色、金属、土色或纤维本色依作品变化；均匀展览光显示综合色与材质，局部反射来自真实陶瓷、珠饰或金属；织物、丙烯、拼贴、陶瓷、珠饰、手工接缝及工业材料。","influencedBy":"女性主义艺术、纺织与陶瓷、装饰史、Matisse、民间艺术及对极简主义和现代主义反装饰立场的批评","influenced":"当代绘画、纤维、装置、女性主义工艺复兴和装饰研究","sources":[{"label":"Tate：Pattern and Decoration","url":"https://www.tate.org.uk/art/art-terms/p/pattern-and-decoration"},{"label":"Whitney Museum：Making Knowing","url":"https://whitney.org/exhibitions/making-knowing"}]},"pictures-generation":{"summary":"Pictures Generation得名于Douglas Crimp策划1977年《Pictures》展及后续评论，艺术家通过再摄影、挪用、表演和语境转换分析媒介图像如何建构性别、欲望与作者权。它不是一种带印刷网点的复古照片风格，版权与来源语境是内容核心。","recognition":"既有媒体图像的再裁切、放大、重复与语境置换；广告、电影或艺术史图像的复制轮廓与版式痕迹；保留来源图像综合色或强化复制色偏；复制品平面光、屏幕光或商品展示光；摄影翻拍、丝网、胶印、录像与再生产颗粒。","influencedBy":"Conceptual Art、Pop Art、电视广告和电影、女性主义媒介批评、摄影复制和后现代作者论","influenced":"挲用艺术、当代摄影、视频和数字媒介批评、版权与图像政治讨论","sources":[{"label":"Tate：Art terms","url":"https://www.tate.org.uk/art/art-terms"},{"label":"MoMA：Art terms","url":"https://www.moma.org/collection/terms"}]},"neo-concretism":{"summary":"巴西新具体主义由1959年宣言确立，反对把艺术化约为机械和知觉公式，强调身体、时间、主观经验与作品作为‘准身体’。可折叠Bichos、参与物和环境各异，不能统一为柔化的红黄蓝几何。","recognition":"几何模块脱离画框、可参与空间与身体尺度关系；折叠平面、铰接几何与柔化的非刚性结构；白、红、蓝、黄与克制纯色；环境光和真实投影参与观看；木、金属、纸、织物与可触摸涂层。","influencedBy":"巴西具体主义、现象学、梅洛-庞蒂、Grupo Frente及对过度理性几何的反应","influenced":"巴西参与式、身体与装置艺术，并深刻影响全球对拉丁美洲战后艺术的理解","sources":[{"label":"MoMA：Neo-Concretism","url":"https://www.moma.org/collection/terms/neo-concretism"},{"label":"Tate：Neo-concrete","url":"https://www.tate.org.uk/art/art-terms/n/neo-concrete"}]},"new-leipzig-school":{"summary":"New Leipzig School是1990年代末后对莱比锡视觉艺术学院及当地画家的市场与批评称呼，不是成员统一的正式团体。具象叙事、东德工业记忆和超现实并置在部分作品中显著，但不应把Neo Rauch的舞台式空间套给所有艺术家。","recognition":"主体与建筑碎片并置、舞台式空间和不连贯叙事；具象轮廓、错位尺度与绘画性变形；灰绿、棕、综合色蓝红与不协调局部强色；冷暖混合、来源不统一的绘画光；可见油画层、擦除、薄涂与局部厚涂。","influencedBy":"莱比锡学院具象教学、东德视觉文化、德国统一后工业转型、超现实主义和当代艺术市场","influenced":"德国当代具象绘画、国际艺术市场对绘画的复兴和后社会主义记忆图像","sources":[{"label":"Tate：Art terms","url":"https://www.tate.org.uk/art/art-terms"},{"label":"MoMA：Art terms","url":"https://www.moma.org/collection/terms"}]},"hard-edge-painting":{"summary":"硬边绘画名称由评论家Jules Langsner于1959年提出，指综合色区域边界清晰、整体均等且压低笔触的抽象绘画。它与后绘画性抽象、几何抽象和综合色场相交，但并非所有几何画或胶带边缘作品都属于同一地区运动。","recognition":"大尺度几何分区、清楚边界与非透视平衡；锐利直线、弧形与完全闭合的平面色块；纯净高饱和综合色或强明度对比；均匀无影画面光，色块自身建立层级；平滑丙烯、胶带遮蔽硬边与无笔触表面。","influencedBy":"几何抽象、综合色场、抽象表现主义反拨、丙烯颜料和美国西海岸艺术网络","influenced":"后绘画性抽象、极简视觉、平面设计及后续精确抽象","sources":[{"label":"Tate：Hard edge painting","url":"https://www.tate.org.uk/art/art-terms/h/hard-edge-painting"},{"label":"Guggenheim：Hard-edge painting","url":"https://www.guggenheim.org/artwork/movement/hard-edge-painting"}]}});
